tw:twjianying.code:
{
    audio: "xinjianying",
    subfrequent: ["draw"],
    enable: "chooseToUse",
    usable: 1,
    filter(event2, player2) {
      const card = event2.twjianying_vcard;
      if (!card) return false;
      const suit = event2.twjianying_suit || null;
      return player2.hasCard((cardx) => {
        const vcard = get.autoViewAs({ ...card, suit, cards: [cardx], storage: { twjianying: true } }, [cardx]);
        return event2.filterCard(vcard, player2, event2);
      }, "hes");
    },
    viewAs(cards2, player2) {
      const event2 = get.event();
      const card = event2.twjianying_vcard;
      const suit = event2.twjianying_suit || null;
      return { ...card, suit, storage: { twjianying: true } };
    },
    filterCard: true,
    position: "hes",
    check(card) {
      const player2 = get.player();
      if (get.event().type !== "phase") return 7 - get.value(card);
      return 7 - player2.getUseValue(card, null, true);
    },
    async precontent(event2, trigger, player2) {
      event2.getParent().addCount = false;
    },
    prompt(event2, player2) {
      return "将一张牌当做" + get.translation(event2.twjianying_vcard) + (event2.twjianying_suit ? "(" + get.translation(event2.twjianying_suit) + ")" : "") + "使用";
    },
    onChooseToUse(event2) {
      if (!game.online) {
        const player2 = event2.player;
        const last = player2.getLastUsed();
        if (last && lib.phaseName.some((phase) => last.getParent(phase) === event2.getParent(phase))) {
          const suit = get.suit(last.card, false);
          if (suit != "none") {
            event2.set("twjianying_suit", suit);
          }
        }
        const history = player2.getAllHistory("useCard");
        if (history.length) {
          for (let num = history.length - 1; num >= 0; num--) {
            const trigger = history[num];
            if (get.type(trigger.card) !== "equip") {
              event2.set("twjianying_vcard", { name: trigger.card.name, nature: trigger.card.nature });
              break;
            }
          }
        }
      }
    },
    hiddenCard(player2, name) {
      if (!player2.hasCards("hes") || player2.getStat().skill?.twjianying) return false;
      const history = player2.getAllHistory("useCard");
      if (history.length) {
        for (let num = history.length - 1; num >= 0; num--) {
          const trigger = history[num];
          if (get.type(trigger.card) !== "equip") return name === trigger.card.name;
        }
      }
      return false;
    },
    locked: false,
    mod: {
      cardUsable(card, player2, num) {
        if (card?.storage?.twjianying) return Infinity;
      }
    },
    ai: {
      respondSha: true,
      respondShan: true,
      skillTagFilter(player2, tag, arg) {
        if (arg === "respond") return false;
        return lib.skill.twjianying.hiddenCard(player2, { respondSha: "sha", respondShan: "shan" }[tag]);
      },
      order(item, player2) {
        const event2 = get.event();
        player2 = player2 || event2.player;
        if (player2.hasCard((card) => {
          return player2.getUseValue(card, null, true) > player2.getUseValue(event2.twjianying_vcard);
        }, "hs"))
          return 0;
        return get.order(event2.twjianying_vcard, player2) - 0.1;
      },
      result: { player: 7 }
    },
    group: ["twjianying_draw", "twjianying_mark"],
    init(player2, skill) {
      var history = player2.getAllHistory("useCard");
      if (history.length) {
        for (let num = history.length - 1; num >= 0; num--) {
          const trigger = history[num];
          if (num === history.length - 1) {
            if (get.suit(trigger.card, player2) !== "none" && typeof get.number(trigger.card, player2) === "number") {
              player2.setStorage(skill, trigger.card, true);
              game.broadcastAll(
                function(player3, suit, skill2) {
                  if (player3.marks[skill2]) {
                    player3.marks[skill2].firstChild.innerHTML = get.translation(suit);
                  }
                },
                player2,
                get.suit(trigger.card, player2),
                skill
              );
            } else {
              player2.unmarkSkill(skill);
            }
          }
          if (get.type(trigger.card) !== "equip") {
            player2.addTip(skill, [skill, { name: trigger.card.name, nature: trigger.card.nature }].map(get.translation).join(" "));
            break;
          }
        }
      }
    },
    onremove(player2, skill) {
      player2.removeTip(skill);
      delete player2.storage[skill];
    },
    intro: {
      markcount(card, player2) {
        return get.strNumber(get.number(card, player2));
      },
      content(card, player2) {
        var suit = get.suit(card, player2);
        var num = get.number(card, player2);
        var str = "<li>上一张牌的花色：" + get.translation(suit);
        str += "<br><li>上一张牌的点数：" + get.strNumber(num);
        return str;
      },
      onunmark(storage, player2, skill) {
        delete player2.storage[skill];
      }
    },
    subSkill: {
      draw: {
        audio: "twjianying",
        inherit: "dcjianying"
      },
      mark: {
        charlotte: true,
        trigger: { player: "useCard1" },
        silent: true,
        async content(event2, trigger, player2) {
          const skill = get.sourceSkillFor(event2.name);
          lib.skill[skill].init(player2, skill);
        }
      }
    }
  }

