refresh:dcshibei.code:
{
    audio: 2,
    audioname2: { tw_jushou: "shibei_xin_jushou" },
    trigger: { player: "damageEnd" },
    check(event, player) {
      return player.getHistory("damage").indexOf(event) == 0;
    },
    filter(event, player) {
      var index = player.getHistory("damage").indexOf(event);
      return index == 0 || index == 1;
    },
    forced: true,
    async content(event, trigger, player) {
      if (player.getHistory("damage").indexOf(trigger) > 0) {
        await player.loseHp();
      } else {
        await player.recover();
      }
    },
    subSkill: {
      damaged: {},
      ai: {}
    },
    ai: {
      maixie_defend: true,
      threaten: 0.9,
      effect: {
        target(card, player, target) {
          if (player.hasSkillTag("jueqing", false, target)) {
            return;
          }
          if (target.hujia) {
            return;
          }
          if (player._shibei_tmp) {
            return;
          }
          if (target.hasSkill("shibei_ai")) {
            return;
          }
          if (_status.event.getParent("useCard", true) || _status.event.getParent("_wuxie", true)) {
            return;
          }
          if (get.tag(card, "damage")) {
            if (target.getHistory("damage").length > 0) {
              return [1, -2];
            } else {
              if (get.attitude(player, target) > 0 && target.hp > 1) {
                return 0;
              }
              if (get.attitude(player, target) < 0 && !player.hasSkillTag("damageBonus", "e", {
                target,
                card
              })) {
                if (card.name == "sha") {
                  return;
                }
                var sha = false;
                player._shibei_tmp = true;
                var num = player.countCards("h", function(card2) {
                  if (card2.name == "sha") {
                    if (sha) {
                      return false;
                    } else {
                      sha = true;
                    }
                  }
                  return get.tag(card2, "damage") && player.canUse(card2, target) && get.effect(target, card2, player, player) > 0;
                });
                delete player._shibei_tmp;
                if (player.hasSkillTag("damage")) {
                  num++;
                }
                if (num < 2) {
                  var enemies = player.getEnemies();
                  if (enemies.length == 1 && enemies[0] == target && player.needsToDiscard()) {
                    return;
                  }
                  return 0;
                }
              }
            }
          }
        }
      }
    }
  }

tw:twshuyin.code:
{
    audio: 2,
    trigger: { player: "useCardAfter" },
    filter(event2, player2) {
      return !player2.getStorage("twshuyin_used").includes(get.suit(event2.card));
    },
    async cost(event2, trigger, player2) {
      const result = await player2.chooseButtonTarget({
        createDialog: [
          "姝音：你可选择一项",
          [
            [
              ["effect", "你下次使用的♥️牌（装备牌与延时锦囊牌除外）额外结算一次"],
              ["gain", "令一名角色将一张牌作为“芳妍”牌置于你的武将牌上，否则失去1点体力。"]
            ],
            "textbutton"
          ]
        ],
        filterTarget(card, player3, target) {
          if (!ui.selected.buttons?.length || ui.selected.buttons[0].link == "effect") {
            return false;
          }
          return true;
        },
        selectTarget() {
          if (!ui.selected.buttons?.length || ui.selected.buttons[0].link == "effect") {
            return -1;
          }
          return 1;
        },
        complexSelect: true,
        ai1(button) {
          return 1 + Math.random();
        },
        ai2(target) {
          if (!ui.selected.buttons?.length || ui.selected.buttons[0].link == "effect") {
            return 0;
          }
          return -get.attitude(get.player(), target);
        }
      }).forResult();
      if (result?.bool && result.links?.length) {
        event2.result = {
          bool: true,
          cost_data: result.links[0]
        };
        if (result.targets?.length) {
          event2.result.targets = result.targets;
        }
      }
    },
    async content(event2, trigger, player2) {
      const { targets, cost_data: link } = event2;
      player2.addTempSkill(event2.name + "_used");
      player2.markAuto(event2.name + "_used", [get.suit(trigger.card)]);
      if (targets?.length) {
        const target = targets[0];
        const result = target.hasCards("he") ? await target.chooseCard({
          prompt: `将一张牌作为“芳妍”牌置于${get.translation(player2)}的武将牌上或失去1点体力`,
          position: "he",
          ai(card) {
            const { player: player3, target: target2 } = get.event();
            if (get.attitude(target2, player3) > 0) {
              return 114514 - get.value(card);
            } else if (["tao", "jiu"].includes(card.name)) {
              return 0;
            }
            return 6 - get.value(card);
          }
        }).set("target", player2).forResult() : { bool: false };
        if (result?.bool && result.cards?.length) {
          await player2.addToExpansion({ cards: result.cards, source: target, animate: "give", gaintag: ["twfangyan"] });
        } else {
          await target.loseHp();
        }
      } else {
        player2.addSkill(event2.name + "_effect");
      }
    },
    subSkill: {
      effect: {
        audio: "twshuyin",
        charlotte: true,
        mark: true,
        intro: { content: "下次使用红桃牌额外结算一次" },
        forced: true,
        locked: false,
        trigger: { player: "useCard" },
        filter(event2, player2) {
          return get.suit(event2.card) == "heart" && !["equip", "delay"].includes(get.type(event2.card));
        },
        async content(event2, trigger, player2) {
          trigger.effectCount++;
          player2.removeSkill(event2.name);
        }
      },
      used: { charlotte: true, onremove: true, intro: { content: "本回合已使用：$" } }
    }
  }

tw:twfangyan.code:
{
    audio: 2,
    forced: true,
    trigger: { player: ["changeHpAfter", "phaseZhunbeiBegin"] },
    filter(event2, player2) {
      return (event2.name == "phaseZhunbei" || event2.changedHp < 0) && player2.hasExpansions("twfangyan");
    },
    async content(event2, trigger, player2) {
      const cards2 = player2.getExpansions(event2.name);
      if (cards2?.length) {
        await player2.gain({ cards: cards2, animate: "gain2" });
        await player2.draw({ num: cards2.length });
      }
    },
    mod: {
      suit(card, suit) {
        const player2 = get.owner(card) || get.player();
        if (!player2) {
          return;
        }
        let suits = player2.getExpansions("twfangyan").map((cardx) => cardx.suit).unique();
        suits = lib.suit.slice().removeArray(suits);
        if (suits.includes(suit)) {
          return "heart";
        }
      }
    },
    intro: {
      content: "expansion",
      markcount: "expansion"
    },
    onremove(player2, skill) {
      var cards2 = player2.getExpansions(skill);
      if (cards2.length) {
        player2.loseToDiscardpile(cards2);
      }
    },
    ai: { combo: "twshuyin" }
  }

tw:twanshu.code:
{
    audio: 2,
    enable: "phaseUse",
    usable: 1,
    filter(event2, player2) {
      return game.hasPlayer((current) => get.info("twanshu").filterTarget(null, player2, current));
    },
    filterTarget(card, player2, target) {
      return target.hasCards("hej");
    },
    async content(event2, trigger, player2) {
      const target = event2.target;
      if (!target.hasCards("hej")) return;
      let result;
      result = await player2.discardPlayerCard({
        prompt: `暗疏：请弃置${get.translation(target)}至多两个区域内的各一张牌`,
        target,
        position: "hej",
        filterButton(button, player3) {
          if (!ui.selected.buttons?.length) return true;
          return get.position(button.link) != get.position(ui.selected.buttons[0].link);
        },
        forced: true,
        selectButton: [1, 2]
      }).set("target", target).forResult();
      if (result?.bool && result.links?.length) {
        const cards2 = result.links;
        await target.modedDiscard({ cards: cards2, discarder: player2 });
        const bool = game.hasPlayer((current) => current != player2 && current != target);
        result = bool ? await player2.chooseTarget({
          prompt: `暗疏：将${get.translation(cards2)}交给一名角色`,
          filterTarget(card, player3, target2) {
            return target2 != get.event().target;
          },
          forced: true,
          ai(target2) {
            return get.attitude(target2, get.player());
          }
        }).set("target", target).forResult() : { bool: true, targets: [player2] };
        if (result?.bool && result.targets?.length) {
          const targetx = result.targets[0];
          player2.line(targetx);
          await targetx.gain({ cards: cards2, animate: "giveAuto", gaintag: ["twanshu_tag"], source: player2 });
          targetx.addSkill("twanshu_tag");
        }
      }
    },
    subSkill: {
      tag: {
        charlotte: true,
        onremove(player2, skill) {
          player2.removeGaintag(skill);
        },
        silent: true,
        mod: {
          cardUsable(card) {
            if (get.number(card) === "unsure" || card.cards?.some((card2) => card2.hasGaintag("twanshu_tag"))) {
              return Infinity;
            }
          }
        },
        trigger: {
          player: ["useCardAfter", "useCard"]
        },
        filter(event2, player2, name) {
          const evtx = name == "useCard" ? event2 : event2.getParent();
          if (!player2.hasHistory("lose", (evt) => {
            if (evt.getParent(name == "useCard" ? 1 : 2) !== evtx) {
              return false;
            }
            return Object.values(evt.gaintag_map).flat().includes("twanshu_tag");
          })) {
            return false;
          }
          if (name == "useCard") {
            return event2.addCount != false && get.is.damageCard(event2.card);
          }
          return !get.is.damageCard(event2.card);
        },
        async content(event2, trigger, player2) {
          if (event2.triggername == "useCard") {
            trigger.addCount = false;
            const stat = player2.getStat().card, name = trigger.card.name;
            if (typeof stat[name] === "number") {
              stat[name]--;
            }
          } else {
            await player2.draw();
          }
        }
      }
    },
    ai: {
      order: 9,
      result: {
        player: 1,
        target(player2, target) {
          return get.effect(target, { name: "guohe_copy" }, player2, player2) > 0;
        }
      }
    }
  }

tw:twtongce.code:
