      const num = Math.min(cardsLen, maxNum - myLen);
      if (num > 0) {
        cards2 = cards2.randomGets(num);
      }
      const next = player2.addToExpansion(cards2, "gain2");
      next.gaintag.add("twsbqingjian");
      await next;
    },
    marktext: "俭",
    intro: {
      content: "expansion",
      markcount: "expansion"
    },
    subSkill: {
      give: {
        audio: "sbqingjian",
