        filter(event2, player2) {
          return player2.getExpansions("twsbqingjian").length > 0;
        },
        async cost(event2, trigger, player2) {
          if (_status.connectMode) {
            game.broadcastAll(() => {
              _status.noclearcountdown = true;
            });
          }
          const given_map = {}, targets = [], expansions = player2.getExpansions("twsbqingjian");
          do {
            const result = expansions.length > 1 ? await player2.chooseButtonTarget({
              createDialog: [`清俭：请选择要分配的牌`, expansions],
              selectButton: [1, Infinity],
              filterTarget: true,
              ai1(button) {
                return get.value(button.link);
              },
              canHidden: true,
              complexSelect: true,
              ai2(target) {
                const att = get.attitude(get.player(), target);
                if (get.value(ui.selected.buttons[0]?.link, player2, "raw") < 0) {
                  return Math.max(0.01, 100 - att);
                } else if (att > 0) {
                  return Math.max(0.1, att / Math.sqrt(2 + target.countCards("h")));
                } else {
                  return Math.max(0.01, (100 + att) / 200);
                }
              }
