{
    audio: "wuhun",
    trigger: { player: "die" },
    forceDie: true,
    skillAnimation: true,
    animationColor: "soil",
    locked: true,
    check(event2, player2) {
      return game.hasPlayer(function(current) {
        return current != player2 && current.hasMark("twwuhun") && get.attitude(player2, current) < 0;
      });
    },
    async content(event2, trigger, player2) {
      const judge = player2.judge((card) => {
        const name = get.name(card, false);
        return name === " tao" || name === "taoyuan" ? -25 : 15;
      });
      judge.set("forceDie", true);
      judge.set("judge2", (result2) => result2.bool);
      const judgeResult = await judge.forResult();
      if (!judgeResult?.bool) {
        return;
      }
      const num = game.countPlayer((current) => current !== player2 && current.hasMark("twwuhun"));
      if (num === 0) {
        return;
      }
      const prompt = "请选择【武魂】的目标";
      const prompt2 = "选择至少一名拥有“梦魇”标记的角色。令这些角色各自失去X点体力（X为其“梦魇”标记数）";
      const next = player2.chooseTarget(prompt, prompt2, [1, num], true);
      next.set("filterTarget", (card, _player, target) => target !== player2 && target.hasMark("twwuhun"));
      next.set("forceDie", true);
      next.set("ai", (target) => -get.attitude(get.player(), target));
      const result = await next.forResult();
      if (!result.targets?.length) {
        return;
      }
      const targets = result.targets.sortBySeat();
      player2.line(targets);
      for (const target of targets) {
        const num2 = target.countMark("twwuhun");
        if (num2 > 0) {
          await target.loseHp(num2);
        }
      }
    },
    marktext: "魇",
    intro: {
      name: "梦魇",
      content: "mark",
      onunmark: true
    },
    group: "twwuhun_gain",
    subSkill: {
      gain: {
        audio: "wuhun",
        trigger: {
          player: "damageEnd",
          source: "damageSource"
        },
        forced: true,
        filter(event2, player2, name) {
          if (event2.player == event2.source) {
            return false;
          }
          var target = lib.skill.twwuhun_gain.logTarget(event2, player2);
          if (!target || !target.isIn()) {
            return false;
          }
          return name == "damageEnd" || target.hasMark("twwuhun");
        },
        logTarget(event2, player2) {
          if (player2 == event2.player) {
            return event2.source;
          }
          return event2.player;
        },
        async content(event2, trigger, player2) {
          const target = lib.skill.twwuhun_gain.logTarget(trigger, player2);
          target.addMark("twwuhun", player2 == trigger.source ? 1 : trigger.num);
          await game.delayx();
        }
      }
    },
    ai: {
      notemp: true,
      maixie_defend: true,
      effect: {
        target: (card, player2, target) => {
          if (!get.tag(card, "damage") || !target.hasFriend()) {
            return;
          }
          let die = [], extra = [null, 0], temp;
          game.filterPlayer((i) => {
            if (!i.hasMark("twwuhun")) {
              return false;
            }
            temp = get.attitude(target, i);
            if (temp < 0) {
              die.push(i);
            } else {
              temp = Math.sqrt(temp) * i.countMark("twwuhun");
              if (!extra[0] || temp < extra[1]) {
                extra = [i, temp];
              }
            }
          });
          if (extra[0] && !die.length) {
            die.push(extra[0]);
          }
          if (target.hp + target.hujia > 1 && (!die.length || get.attitude(player2, target) <= 0)) {
            die.add(player2);
          }
          if (die.length) {
            return [
              1,
              0,
              1,
              die.reduce((num, i) => {
                return num -= 2 * get.sgnAttitude(player2, i);
              }, 0)
            ];
          }
        }
      }
    }
  }

