tw:twshelun.code:
{
    audio: "jsrgshelun",
    enable: "phaseUse",
    usable: 1,
    filter(event2, player2) {
      return player2.countCards("h") && game.hasPlayer((current) => current != player2 && player2.inRange(current));
    },
    filterTarget(card, player2, target) {
      return player2 != target && player2.inRange(target);
    },
    multitarget: true,
    multiline: true,
    selectTarget: [1, 2],
    async content(event2, trigger, player2) {
      const { targets: targetsx } = event2;
      const num = player2.countCards("h"), targets = game.filterPlayer((target) => {
        return target.countCards("h") <= num && !targetsx.includes(target);
      });
      if (!targets?.length) {
        return;
      }
      await player2.chooseToDebate(targets).set("callback", async function(event3, trigger2, player3) {
        const result = event3.debateResult;
        if (result.bool && result.opinion) {
          const opinion = result.opinion;
          const targets2 = event3.getParent().targetsx;
          if (opinion && ["red", "black"].includes(opinion)) {
            player3.logSkill("twshelun", targets2, null, null, [opinion == "red" ? 3 : 4]);
            if (opinion == "red") {
              await game.doAsyncInOrder(targets2, async (target) => player3.discardPlayerCard(target, "he", true, 2));
            } else {
              await game.doAsyncInOrder(targets2, async (target) => target.damage());
            }
          }
        }
      }).set("ai", (card) => {
        const player3 = get.player();
        const targets2 = get.event().getParent(2).targetsx;
        const color = player3 == _status.event.source || targets2.reduce((sum, target) => sum + get.damageEffect(target, player3, player3), 0) > 0 ? "black" : "red";
        let val = 5 - get.value(card);
        if (get.color(card) == color) {
          val += 10;
        }
        return val;
      }).set("aiCard", (target) => {
        const targets2 = get.event().getParent(2).targetsx;
        const color = target == _status.event.source || targets2.reduce((sum, target2) => sum + get.damageEffect(target2, player2, player2), 0) > 0 ? "black" : "red";
        let hs = target.getCards("h", { color });
        if (!hs.length) {
          hs = target.getCards("h");
        }
        return { bool: true, cards: [hs.randomGet()] };
      }).set("targetsx", targetsx);
    },
    ai: {
      order: 8,
      expose: 0.2,
      result: { target: -1 }
    }
  }

