mobile:mbjiwei.code:
{
    audio: 4,
    getNum(event, player) {
      let num = 0;
      if (game.countPlayer2((current) => current.hasHistory("lose")) >= 1) {
        num++;
      }
      if (game.countPlayer2((current) => current.hasHistory("damage")) >= 1) {
        switch (get.mode()) {
          case "doudizhu": {
            num += 2;
            break;
          }
          case "identity":
            break;
          default: {
            num++;
            break;
          }
        }
      }
      if (event.name == "phase") {
        return num;
      }
      if (get.mode() == "identity") {
        return Math.max(game.countPlayer(), player.getHp());
      }
      if (game.hasPlayer2((current) => !current.isAlive())) {
        return 114514;
      }
      return 5;
    },
    trigger: {
      player: "phaseZhunbeiBegin",
      global: "phaseEnd"
    },
    filter(event, player) {
      const num = get.info("mbjiwei").getNum(event, player);
      if (event.name == "phaseZhunbei") {
        return player.countCards("h") >= num && game.hasPlayer((current) => current != player);
      }
      return event.player != player && num > 0;
    },
    logAudio(event, player) {
      if (event.name == "phaseZhunbei") {
        return ["mbjiwei3.mp3", "mbjiwei4.mp3"];
      }
      return ["mbjiwei1.mp3", "mbjiwei2.mp3"];
    },
    forced: true,
    async content(event, trigger, player) {
      const num = get.info(event.name).getNum(trigger, player);
      if (trigger.name == "phase") {
        await player.draw(num);
      } else {
        const cards2 = player.getCards("h"), map = {};
        for (let color of ["red", "black", "none"]) {
          if (typeof map[color] != "number") {
            map[color] = 0;
          }
          map[color] += cards2.filter((card) => get.color(card) == color).length;
        }
        const list = [];
        for (var i in map) {
          if (map[i] > 0) {
            list.push([`${i}2`, map[i]]);
          }
        }
        list.sort((a, b) => b[1] - a[1]);
        let colors = list.filter((i2) => i2[1] == list[0][1]).map((i2) => i2[0]);
        const control = colors.length == 1 ? colors[0] : (await player.chooseControl(colors).set("prompt", "济危：请选择一个颜色").forResult()).control;
        let togive = player.getCards("h").filter((card) => get.color(card) == control.slice(0, -1));
        if (_status.connectMode) {
          game.broadcastAll(() => _status.noclearcountdown = true);
        }
        let given_map = [];
        while (togive.length && game.hasPlayer((current) => current != player) && player.hasCard((card) => !card.hasGaintag("olsujian_given"), "h")) {
          const result = await player.chooseCardTarget({
            forced: true,
            filterCard(card, player2) {
              return get.event().togive.includes(card) && !card.hasGaintag("olsujian_given");
            },
            selectCard: [1, Infinity],
            position: "h",
            filterTarget: lib.filter.notMe,
            prompt: "济危：请选择要分配的卡牌和目标",
            ai1(card) {
              return !ui.selected.cards.length && card.name == "du" ? 1 : 0;
            },
            ai2(target) {
              const player2 = get.event().player;
              const card = ui.selected.cards[0];
              if (card) {
                return get.value(card, target) * get.attitude(player2, target);
              }
              return 0;
            },
            togive,
            allowChooseAll: true
          }).forResult();
          if (result?.cards?.length && result.targets?.length) {
            const {
              cards: cards3,
              targets: [target]
            } = result;
            togive.removeArray(cards3);
            if (given_map.some((i2) => i2[0] == target)) {
              given_map[given_map.indexOf(given_map.find((i2) => i2[0] == target))][1].addArray(cards3);
            } else {
              given_map.push([target, cards3]);
            }
            player.addGaintag(cards3, "olsujian_given");
          } else {
            break;
          }
        }
        if (_status.connectMode) {
          game.broadcastAll(() => {
            delete _status.noclearcountdown;
            game.stopCountChoose();
          });
        }
        if (given_map.length) {
          await game.loseAsync({
            gain_list: given_map,
            player,
            cards: given_map.slice().flatMap((list2) => list2[1]),
            giver: player,
            animate: "giveAuto"
          }).setContent("gaincardMultiple");
        }
      }
    }
  }

