tw:twmiyong.code:
{
    audio: 2,
    limited: true,
    skillAnimation: true,
    animationColor: "thunder",
    enable: "phaseUse",
    filter(event2, player2) {
      return player2.hasCard((card) => get.name(card, player2) == "sha", "h");
    },
    filterCard: (card, player2) => get.name(card, player2) == "sha" && !player2.getStorage("twmiyong_effect").includes(card),
    check: (card, player2) => player2.getUseValue(card),
    position: "h",
    selectCard: [1, 2],
    lose: false,
    discard: false,
    delay: false,
    async content(event2, trigger, player2) {
      player2.awakenSkill(event2.name);
      const cards2 = event2.cards;
      const skill = "twmiyong_effect";
      await player2.showCards(cards2);
      player2.addGaintag(cards2, skill);
      player2.addSkill(skill);
      cards2.forEach((card) => {
        card.storage[skill] = true;
      });
    },
    subSkill: {
      effect: {
        audio: "twmiyong",
        mod: {
          aiOrder(card, player2, num) {
          }
        },
        onremove(player2, skill) {
          player2.removeGaintag(skill);
          delete player2.storage[skill];
        },
        charlotte: true,
        forced: true,
        trigger: {
          global: ["loseAfter", "loseAsyncAfter", "cardsDiscardAfter"]
        },
        getSha(event2, player2) {
          let gain = [];
          const cards2 = event2.cards.filter((card) => card.storage.twmiyong_effect);
          if (!cards2.length) {
            return gain;
          }
          let use = [], respond = [], discard = [];
          game.checkGlobalHistory("cardMove", (evt) => {
            const cardsx = evt.cards;
            if (!cardsx || !cardsx.some((card) => cards2.includes(card))) {
              return false;
            }
            if (event2.name.indexOf("lose") == 0 && ["lose", "loseAsync"].includes(evt.name)) {
              if (evt.position != ui.discardPile || evt.type != "discard" || evt.getlx === false) {
                return false;
              }
              discard.add(evt);
            } else if (evt.name == "cardsDiscard" && event2.name == "cardsDiscard") {
              const evtx = evt.getParent();
              if (evtx.name !== "orderingDiscard") {
                return false;
              }
              const evt2 = evtx.relatedEvent || evtx.getParent();
              if (evt2.name == "useCard") {
                use.add(evt);
              } else if (evt2.name == "respond") {
                respond.add(evt);
              }
            }
          });
          gain.addArray(
            cards2.filter((card) => {
              return [use, respond, discard].some((list) => list.filter((evt) => evt.cards.includes(card)).indexOf(event2) == 0);
            })
          );
          return gain.filterInD("d");
        },
        filter(event2, player2) {
          if (event2.name.indexOf("lose") == 0) {
            if (event2.position != ui.discardPile || event2.type != "discard" || event2.getlx === false) {
              return false;
            }
          } else {
            const evt = event2.getParent();
            if (evt.name !== "orderingDiscard") {
              return false;
            }
            const evt2 = evt.relatedEvent || evt.getParent();
            if (!["useCard", "respond"].includes(evt2.name)) {
              return false;
            }
          }
          const cards2 = lib.skill.twmiyong_effect.getSha(event2, player2);
          if (cards2.length) {
            event2.set("twmiyong_effect", cards2);
            return true;
          }
          return false;
        },
        async content(event2, trigger, player2) {
          const cards2 = trigger[event2.name].filterInD("d");
          if (!cards2.length) {
            return;
          }
          await player2.showCards(cards2);
          await player2.gain(cards2, "gain2").set("gaintag", [event2.name]);
        }
      }
    }
  }

