            player2.markAuto("twqianxiong_damage", [target]);
            target.when("phaseEnd").step(async (event3, trigger2, player3) => {
              const cards2 = player3.getExpansions("twqianxiong").filter((card) => {
                return player3.hasHistory("useCard", (evt) => evt.card.name == card.name) || player3.hasHistory("respond", (evt) => evt.card.name == card.name);
