                return get.order(button.link);
              }).forResult();
              const card = result.links[0];
              cards2.remove(card);
              player2.$gain2(card, false);
              game.delayx();
              await player2.chooseUseTarget(card, true);
            }
          }
        }
      }
    }
  }

