{
    audio: 3,
    logAudio: (index) => typeof index === "number" ? "twhuazhang" + index + ".mp3" : 2,
    trigger: {
      player: "phaseUseEnd"
    },
    filter(event2, player2) {
      return player2.countCards("h") >= 2 && player2.hasCard((card) => player2.canRecast(card), "h");
    },
    check: () => true,
    async content(event2, trigger, player2) {
      const cards2 = player2.getCards("h", (card) => player2.canRecast(card)), num = cards2.length;
      await player2.recast(cards2);
      let count = 0;
      if (cards2.map((card) => get.suit(card)).unique().length == 1) {
        count++;
      }
      const nums = cards2.map((card) => get.number(card)).unique().sort((a, b) => a - b);
      if (nums.length == cards2.length && nums.length > 1) {
        if (nums[nums.length - 1] - nums[0] == nums.length - 1) {
          count++;
        }
      }
      if (cards2.map((card) => get.name(card, player2)).unique().length == 1) {
        count++;
      }
      if (count > 0) {
        player2.logSkill("twhuazhang", null, null, null, [3]);
        await player2.draw(num);
      }
      if (count > 1) {
        player2.addTempSkill("twhuazhang_hs");
        player2.addMark("twhuazhang_hs", num, false);
      }
      if (count > 2) {
        await player2.draw(num);
        player2.addMark("twhuazhang_hs", num, false);
      }
    },
    subSkill: {
      hs: {
        onremove: true,
        charlotte: true,
        markimage: "image/card/handcard.png",
        mod: {
          maxHandcard(player2, num) {
            return num + player2.countMark("twhuazhang_hs");
          }
        },
        intro: {
          content: "本回合手牌上限+#"
        }
      }
    }
  }

