tw:twfushu.code:
{
    audio: 2,
    enable: "chooseToUse",
    hiddenCard(player2, name) {
      return name === "tao" && player2.countCards("h") > 0 && !player2.hasSkillTag("noCompareSource");
    },
    filter(event2, player2) {
      if (event2.twfushu) {
        return false;
      }
      return event2.filterCard({ name: "tao", isCard: true }, player2, event2) && player2.countCards("h") && !player2.hasSkillTag("noCompareSource");
    },
    filterCard: () => true,
    selectCard: 1,
    lose: false,
    discard: false,
    delay: false,
    log: false,
    check(card) {
      if (typeof card == "string" && lib.skill[card]) {
        var ais = lib.skill[card].check || function() {
          return 0;
        };
        return ais();
      }
      get.owner(card);
      var getn = function(card2) {
        return get.number(card2);
      };
      _status.event.getParent();
      var addi = get.value(card) >= 8 && get.type(card) != "equip" ? -6 : 0;
      if (card.name == "du") {
        addi -= 5;
      }
      return getn(card) - get.value(card) / 5 + addi;
    },
    prompt: "选择一张手牌与牌堆顶的一张牌拼点：若你赢，你视为使用一张【桃】；若你没赢，你下次受到的伤害值+1",
    async precontent(event2, trigger, player2) {
      player2.logSkill("twfushu");
      player2.tempBanSkill("twfushu", null, false);
      const next = player2.chooseToCompare().set("target", "cardPile");
      next.fixedResult ??= {};
      next.fixedResult[player2.playerid] = event2.result.cards[0];
      event2.result.card = { name: "tao", isCard: true };
      delete event2.result.cards;
      const result = await next.forResult();
      if (!result.bool) {
        player2.addSkill("twfushu_damage");
        player2.addMark("twfushu_damage", 1, false);
        const evt = event2.getParent();
        evt.set("twfushu", true);
        evt.goto(0);
        delete evt.openskilldialog;
        return;
      }
    },
    viewAs: {
      name: "tao",
      isCard: true
    },
    ai: {
      save: true,
      skillTagFilter(player2, tag, arg) {
        return player2.countCards("h") > 0 && !player2.hasSkillTag("noCompareSource");
      },
      order: 7,
      result: {
        player(player2) {
          if (_status.event.dying) {
            return get.attitude(player2, _status.event.dying);
          }
          return 1;
        }
      }
    },
    subSkill: {
      damage: {
        audio: 2,
        onremove: true,
        intro: {
          content: "下次受到的伤害+1"
        },
        charlotte: true,
        forced: true,
