tw:twkanpo.code:
{
    init(player2) {
      if (!player2.storage.twkanpo) {
        player2.storage.twkanpo = [3, [], []];
        player2.markSkill("twkanpo");
      }
    },
    audio: "sbkanpo",
    trigger: { global: "roundStart" },
    filter(event2, player2) {
      var storage = player2.storage.twkanpo;
      return storage[0] || storage[1].length;
    },
    forced: true,
    locked: false,
    async content(event2, trigger, player2) {
      var storage = player2.storage.twkanpo;
      var sum = storage[0];
      storage[1] = [];
      player2.markSkill("twkanpo");
      if (!sum) {
        return;
      }
      const list = get.inpileVCardList((info) => {
        if (info[2] == "sha" && info[3]) {
          return false;
        }
        return info[0] != "equip";
      });
      const func = () => {
        const event3 = get.event();
        const controls = [
          (link) => {
            const evt = get.event();
            if (evt.dialog && evt.dialog.buttons) {
              for (let i = 0; i < evt.dialog.buttons.length; i++) {
                const button = evt.dialog.buttons[i];
                button.classList.remove("selectable");
                button.classList.remove("selected");
                const counterNode = button.querySelector(".caption");
                if (counterNode) {
                  counterNode.childNodes[0].innerHTML = ``;
                }
              }
              ui.selected.buttons.length = 0;
              game.check();
            }
            return;
          }
        ];
        event3.controls = [ui.create.control(controls.concat(["清除选择", "stayleft"]))];
      };
      if (event2.isMine()) {
        func();
      } else if (event2.isOnline()) {
        event2.player.send(func);
      }
      var result = await player2.chooseButton(["看破：是否记录至多" + get.cnNumber(sum) + "个牌名？", [list, "vcard"]], [1, sum], false).set("ai", function(button) {
        if (ui.selected.buttons.length >= Math.max(3, game.countPlayer() / 2)) {
          return 0;
        }
        switch (button.link[2]) {
          case "wuxie":
            return 5 + Math.random();
          case "sha":
            return 5 + Math.random();
          case "tao":
            return 4 + Math.random();
          case "jiu":
            return 3 + Math.random();
          case "lebu":
            return 3 + Math.random();
          case "shan":
            return 4.5 + Math.random();
          case "wuzhong":
            return 4 + Math.random();
          case "shunshou":
            return 2.7 + Math.random();
          case "nanman":
            return 2 + Math.random();
          case "wanjian":
            return 1.6 + Math.random();
          default:
            return 1.5 + Math.random();
        }
      }).set("filterButton", (button) => {
        return !_status.event.names.includes(button.link[2]);
      }).set("names", storage[2]).set("custom", {
        add: {
          confirm(bool) {
            if (bool != true) {
              return;
            }
            const event3 = get.event().parent;
            if (event3.controls) {
              event3.controls.forEach((i) => i.close());
            }
            if (ui.confirm) {
              ui.confirm.close();
            }
            game.uncheck();
          },
          button() {
            if (ui.selected.buttons.length) {
              return;
            }
            const event3 = get.event();
            if (event3.dialog && event3.dialog.buttons) {
              for (let i = 0; i < event3.dialog.buttons.length; i++) {
                const button = event3.dialog.buttons[i];
                const counterNode = button.querySelector(".caption");
                if (counterNode) {
                  counterNode.childNodes[0].innerHTML = ``;
                }
              }
            }
            if (!ui.selected.buttons.length) {
              const evt = event3.parent;
              if (evt.controls) {
                evt.controls[0].classList.add("disabled");
              }
            }
          }
        },
        replace: {
          button(button) {
            const event3 = get.event(), sum2 = event3.sum;
            if (!event3.isMine()) {
              return;
            }
            if (button.classList.contains("selectable") == false) {
              return;
            }
            if (ui.selected.buttons.length >= sum2) {
              return false;
            }
            button.classList.add("selected");
            ui.selected.buttons.push(button);
            let counterNode = button.querySelector(".caption");
            const count = ui.selected.buttons.filter((i) => i == button).length;
            if (counterNode) {
              counterNode = counterNode.childNodes[0];
              counterNode.innerHTML = `×${count}`;
            } else {
              counterNode = ui.create.caption(`<span style="font-size:24px; font-family:xinwei; text-shadow:#FFF 0 0 4px, #FFF 0 0 4px, rgba(74,29,1,1) 0 0 3px;">×${count}</span>`, button);
              counterNode.style.right = "5px";
              counterNode.style.bottom = "2px";
            }
            const evt = event3.parent;
            if (evt.controls) {
              evt.controls[0].classList.remove("disabled");
            }
            game.check();
          }
        }
      }).set("sum", sum).forResult();
      if (result.bool) {
        var names = result.links.map((link) => link[2]);
        storage[0] -= names.length;
        storage[1] = names;
        storage[2] = names;
      } else {
        storage[2] = [];
      }
      player2.markSkill("twkanpo");
    },
    marktext: "破",
    intro: {
      markcount(storage) {
        return storage[1].length;
      },
      mark(dialog, content, player2) {
        const storage = player2.getStorage("twkanpo");
        const sum = storage[0];
        const names = storage[1];
        dialog.addText("剩余可记录" + sum + "次牌名");
        if (player2.isUnderControl(true) && names.length) {
          dialog.addText("当前记录牌名：");
          dialog.addSmall([names, "vcard"]);
        }
      }
    },
    group: "twkanpo_kanpo",
    subSkill: {
      kanpo: {
        audio: "sbkanpo",
        trigger: { global: "useCard" },
        filter(event2, player2) {
          return event2.player != player2 && player2.storage.twkanpo[1].includes(event2.card.name);
        },
        prompt2(event2, player2) {
          return "移除" + get.translation(event2.card.name) + "的记录，令" + get.translation(event2.card) + "无效";
        },
        check(event2, player2) {
          var effect = 0;
          if (event2.card.name == "wuxie" || event2.card.name == "shan") {
            if (get.attitude(player2, event2.player) < -1) {
              effect = -1;
            }
          } else if (event2.targets && event2.targets.length) {
            for (var i = 0; i < event2.targets.length; i++) {
              effect += get.effect(event2.targets[i], event2.card, event2.player, player2);
            }
          }
          if (effect < 0) {
            if (event2.card.name == "sha") {
              var target = event2.targets[0];
              if (target == player2) {
                return !player2.countCards("h", "shan");
              } else {
                return target.hp == 1 || target.countCards("h") <= 2 && target.hp <= 2;
              }
            } else {
              return true;
            }
          }
          return false;
        },
        logTarget: "player",
        async content(event2, trigger, player2) {
          player2.storage.twkanpo[1].remove(trigger.card.name);
          player2.markSkill("twkanpo");
          trigger.targets.length = 0;
          trigger.all_excluded = true;
          player2.draw();
        }
      }
    }
  }

