    audioname: ["huan_caoang_shadow"],
    trigger: { global: "phaseBegin" },
    filter(event2, player2) {
      return event2.player != player2 && player2.hasEnabledSlot();
    },
    async cost(event2, trigger, player2) {
      const { player: target } = trigger, equips = Array.from({ length: 5 }).map((_, i) => [i + 1, get.translation(`equip${i + 1}`)]).filter((i) => player2.hasEnabledSlot(`equip${i[0]}`));
      const { bool, links } = await player2.chooseButton(2, [
        "炽灰：请选择你要废除的装备栏和相应操作",
        '<div class="text center">即将废除的装备栏</div>',
        [equips, "tdnodes"],
        `<div class="text center">对${get.translation(target)}执行的操作</div>`,
        [
          [
            ["discard", `弃置其牌`],
            ["equip", `置入装备牌`]
          ],
          "tdnodes"
        ]
      ]).set("filterButton", (button) => {
        const { link } = button, { player: player3, target: target2 } = get.event();
        if (Boolean(ui.selected.buttons.length) == (typeof link == "number")) {
          return false;
        }
        if (ui.selected.buttons.length) {
          return link == "equip" || target2.countDiscardableCards(player3, "hej");
        }
        return true;
      }).set("ai", (button) => {
        const { link } = button, { player: player3, target: target2, list } = get.event();
        let att = get.attitude(player3, target2);
        if (att < 0) {
          att = -Math.sqrt(-att);
        } else {
          att = Math.sqrt(att);
        }
        const eff = att * lib.card.guohe.ai.result.target(player3, target2);
        if (!ui.selected.buttons.length) {
          const bool2 = player3.hasSkill("twfuxi");
          const getVal = (num) => {
            const card = player3.getEquip(`equip${num}`);
            if (card) {
              const val = get.value(card);
              if (val > 0) {
                return 0;
              }
              return 5 - val;
            }
            switch (num) {
              case "3":
                return 4.5;
              case "4":
                return 4.4;
              case "5":
                return 4.3;
              case "2":
                return (3 - player3.hp) * 1.5;
              case "1": {
                if (game.hasPlayer((current) => (get.realAttitude || get.attitude)(player3, current) < 0 && get.distance(player3, current) > 1) && !bool2) {
                  return 0;
                }
                return bool2 ? 4.9 : 3.2;
              }
            }
          };
          list.sort((a, b) => getVal(b) - getVal(a));
          if (link == list[0]) {
            return 1;
          }
          return 0;
        }
        if (link == "discard" && eff < 0) {
          return 0;
        }
        if ((att < 0 || target2.isMaxEquip()) && link == "equip") {
          return 0;
        }
        return 1;
      }).set("target", target).set(
        "list",
        equips.map((i) => i[0])
      ).forResult();
      event2.result = {
        bool,
        cost_data: links
      };
    },
    logTarget: "player",
    async content(event2, trigger, player2) {
      const { player: target } = trigger, { cost_data: links } = event2;
      await player2.disableEquip(`equip${links[0]}`);
      if (links[1] == "discard") {
        if (target.countDiscardableCards(player2, "hej")) {
          await player2.discardPlayerCard(target, "hej", true);
        }
      } else {
        const equip = get.cardPile2((card) => get.subtype(card) == `equip${links[0]}`);
        if (equip) {
          await target.equip(equip);
          await game.delayx();
        }
      }
      await player2.loseHp();
      const num = player2.getDamagedHp();
      if (num) {
        await player2.draw(Math.min(2, num));
      }
    }
  }

