      if (event2.name == "phaseZhunbei") {
        return player2.hasDisabledSlot();
      }
      return player2.getStorage("twhuangzhu_effect").length && player2.hasDisabledSlot();
    },
    async cost(event2, trigger, player2) {
      if (trigger.name == "phaseZhunbei") {
        const list = Array.from({ length: 5 }).map((_, i) => `equip${i + 1}`).filter((i) => player2.hasDisabledSlot(i)).concat(["cancel2"]);
        const { control } = await player2.chooseControl(list).set("prompt", "煌烛：选择一个已废除装备栏的类别").set("prompt2", "从牌堆或弃牌堆中随机获得一张对应副类别的装备牌，并记录其牌名").set("ai", () => {
          return get.event().controls.filter((i) => i !== "cancel2").randomGet();
        }).forResult();
        event2.result = {
          bool: control != "cancel2",
          cost_data: control
        };
      } else {
        const storage = player2.getStorage("twhuangzhu_effect");
        const storage2 = player2.getStorage("twhuangzhu_equip").slice().map((equip) => equip[2]);
        let virtualList = {};
        let disabled = [1, 2, 3, 4, 5].filter((num) => player2.countDisabledSlot(num)).map((num) => "equip" + num);
        for (let i of disabled) {
          virtualList[i] = [];
        }
        if (storage2?.length) {
          for (let i of storage2) {
            if (disabled.includes(get.subtype(i))) {
              virtualList[get.subtype(i)].add(i);
            }
          }
        }
        let chooseList = [];
        chooseList.push('###煌烛###<div class="text center">为至多两个已废除的装备栏选择或替换牌名</div>');
        for (let i of disabled) {
          let str = get.translation(i) + "栏：";
          if (virtualList[i]?.length) {
            str += "已视为装备" + get.translation(virtualList[i]);
          } else {
            str += "未视为装备任何牌";
          }
          chooseList.push(str);
          let equips = storage.slice().filter((name) => get.subtypes(name).includes(i));
          let list = [equips, "vcard"];
          if (equips.length) {
            chooseList.push(list);
          }
        }
        const { bool, links } = await player2.chooseButton(chooseList, [1, 2]).set("filterButton", (button) => {
          let storage22 = get.event().storage2;
          if (storage22.includes(button.link[2])) {
            return false;
          }
          if (ui.selected.buttons.length) {
            if (get.subtype(ui.selected.buttons[0].link[2]) == get.subtype(button.link[2])) {
              return false;
            }
          }
          return true;
        }).set("storage2", storage2).set("ai", (button) => get.equipValue({ name: button.link[2] }, get.player())).forResult();
        event2.result = {
          bool,
          cost_data: links
        };
      }
