          await player2.gain(equip, "gain2");
          await game.delayx();
          player2.addSkill(event2.name + "_effect");
          player2.markAuto(event2.name + "_effect", [get.name(equip)]);
        }
      } else {
        const equip = event2.name + "_equip";
        const subtypes = cost_data.map((name) => get.subtypes(name[2])).flat();
        player2.unmarkAuto(
          equip,
          player2.getStorage(equip).filter((name) => subtypes.some((t) => get.subtypes(name[2]).includes(t)))
        );
        player2.addSkill(equip);
        player2.markAuto(equip, cost_data);
        player2.addAdditionalSkill(
          equip,
          player2.getStorage(equip).map((name) => lib.card[name[2]]?.skills || []).flat()
        );
        player2.addExtraEquip(
          equip,
          player2.getStorage(equip).map((name) => name[2]),
          true
        );
      }
    },
    subSkill: {
      effect: {
        charlotte: true,
        onremove: true,
        intro: { content: "已记录牌名：$" }
      },
      equip: {
        charlotte: true,
        mod: {
          globalFrom(from, to, distance) {
            return distance + from.getStorage("twhuangzhu_equip").reduce((sum, name) => sum + (lib.card[name[2]]?.distance?.globalFrom || 0), 0);
          },
          globalTo(from, to, distance) {
            return distance + to.getStorage("twhuangzhu_equip").reduce((sum, name) => sum + (lib.card[name[2]]?.distance?.globalTo || 0), 0);
          },
          attackRange(from, distance) {
            return distance - from.getStorage("twhuangzhu_equip").reduce((sum, name) => sum + (lib.card[name[2]]?.distance?.attackFrom || 0), 0);
          },
          attackTo(from, to, distance) {
            return distance + to.getStorage("twhuangzhu_equip").reduce((sum, name) => sum + (lib.card[name[2]]?.distance?.attackTo || 0), 0);
          }
        },
        onremove(player2, skill) {
          player2.removeAdditionalSkill(skill);
        },
        intro: {
          markcount: "expansion",
          mark(dialog, storage = []) {
            if (!storage.length) {
              return "当前未视为装备任意牌";
            }
            dialog.addText("当前视为装备");
            dialog.addSmall([storage, "vcard"]);
          }
        },
        trigger: { player: "enableEquipEnd" },
        filter(event2, player2) {
          if (!event2.slots?.length) {
            return false;
          }
          return player2.getStorage("twhuangzhu_equip").some((name) => event2.slots.some((t) => get.subtypes(name[2]).includes(t)));
        },
        forced: true,
        popup: false,
        async content(event2, trigger, player2) {
          const skill = event2.name;
          player2.unmarkAuto(
            skill,
            player2.getStorage(skill).filter((name) => trigger.slots.some((t) => get.subtypes(name[2]).includes(t)))
          );
          const storage = player2.getStorage(skill);
          if (!storage.length) {
            player2.removeExtraEquip(skill);
            player2.removeSkill(skill);
          } else {
            player2.addExtraEquip(
              skill,
              storage.map((name) => name[2]),
              true
            );
            player2.addAdditionalSkill(skill, storage.map((name) => lib.card[name[2]]?.skills || []).flat());
          }
        }
      }
    }
  }

