mobile:zhongzuo.code:
{
    audio: 2,
    trigger: { global: "phaseJieshuBegin" },
    direct: true,
    filter(event, player) {
      return player.getHistory("damage").length > 0 || player.getHistory("sourceDamage").length > 0;
    },
    async content(event, trigger, player) {
      const result = await player.chooseTarget(get.prompt("zhongzuo"), "令一名角色摸两张牌。若其已受伤，则你摸一张牌。").set("ai", function(target) {
