      if (!lib.filter.cardDiscardable(card, player2, "twlifeng")) return false;
      if (!ui.selected.cards?.length) return true;
      return get.number(card, player2) != get.number(ui.selected.cards[0], player2);
    },
    selectCard: 2,
    position: "he",
    filterTarget(card, player2, target) {
      if (ui.selected.cards.length < 2) {
        return false;
      }
      let cards2 = ui.selected.cards, num = Math.abs(get.number(cards2[0], player2) - get.number(cards2[1], player2));
      return get.distance(target, player2) <= num;
    },
    selectTarget: -1,
    multiline: true,
    multitarget: true,
    check(card) {
      return 7 - get.value(card);
    },
    complexSelect: true,
    lose: false,
    discard: false,
    delay: false,
    async content(event2, trigger, player2) {
      const { cards: cards2, targets } = event2;
      targets.sortBySeat();
      await player2.discard(cards2);
      await game.doAsyncInOrder(targets, async (target) => {
        await target.damage({ source: player2, num: 1 });
      });
      const num = Math.abs(get.number(cards2[0], player2) - get.number(cards2[1], player2));
      player2.addTip(event2.name, `${get.translation(event2.name)} ${num}`, "phaseAnyAfter");
      const history = player2.getHistory("custom");
      const evt = event2.getParent("phaseUse");
