tw:twniwo.code:
{
    audio: 2,
    trigger: { player: "phaseUseBegin" },
    filter(event2, player2) {
      return player2.hasCards("h") && game.hasPlayer((current) => current != player2 && current.hasCards("h"));
    },
    async cost(event2, trigger, player2) {
      event2.result = await player2.chooseTarget(get.prompt2(event2.skill), (card, player3, current) => {
        return current != player3 && current.hasCards("h");
      }).set("ai", (target) => {
        return -get.attitude(get.player(), target) / (target.countCards("h") + 1);
      }).forResult();
    },
    async content(event2, trigger, player2) {
      const target = event2.targets[0];
      if ([player2, target].some((current) => !current.hasCards("h"))) {
        return;
      }
      const dialog = ["选择你与" + get.translation(target) + "的等量张手牌"];
      if (player2.hasCards("h")) {
        dialog.add("你的手牌");
        dialog.add(player2.getCards("h"));
      }
      if (target.hasCards("h")) {
        dialog.add(get.translation(target) + "的手牌");
        let hs = target.getCards("h");
        if (player2.hasSkillTag("viewHandcard", null, target, true)) {
          dialog.add(hs);
        } else {
          dialog.add([hs, "blank"]);
        }
      }
      let result = await player2.chooseButton(dialog, true, [2, Infinity]).set("filterOk", () => {
        const buttons = ui.selected.buttons;
        return buttons.filter((i) => get.owner(i.link) == get.player()).length * 2 == buttons.length;
      }).set(
        "cards",
        (() => {
          let cards2 = player2.getCards("h").slice(0).sort((a, b) => get.value(a) - get.value(b));
          let result2 = [];
          while (result2.length < target.countCards("h")) {
            let card = cards2.shift();
            if (card != null && get.value(card) <= 5) {
              result2.push(card);
            } else {
              break;
            }
          }
          return result2.concat(target.getCards("h").randomGets(result2.length));
        })()
      ).set("ai", (button) => {
        return get.event().cards.includes(button.link);
      }).forResult();
      if (!result?.links?.length) {
        return;
      }
      const links = result.links;
      result = await player2.chooseControl({
        controls: ["选项一", "选项二"],
        choiceList: [`你与${get.translation(target)}本回合无法使用或打出这些牌`, `交换你与${get.translation(target)}选择的牌，然后〖砺锋〗本回合失效`],
        ai: () => get.event().controls.slice().randomGet()
      }).forResult();
      if (typeof result?.control == "string") {
        if (result.control == "选项一") {
          for (const owner of [player2, target]) {
            owner.addTempSkill("twniwo_block");
            owner.addGaintag(
              links.filter((i) => get.owner(i) == owner),
              "twniwo"
            );
          }
        } else {
          await player2.swapHandcards(
            target,
            links.filter((i) => get.owner(i) == player2),
            links.filter((i) => get.owner(i) == target)
          );
          player2.tempBanSkill("twlifeng");
        }
      }
    },
    subSkill: {
      block: {
        charlotte: true,
        onremove(player2) {
          player2.removeGaintag("twniwo");
        },
        mod: {
          cardEnabled2(card) {
            if (get.itemtype(card) == "card" && card.hasGaintag("twniwo")) {
              return false;
            }
          }
        }
      }
    }
  }

