      const card = get.cards(1, true)[0];
      await player2.showCards([card], get.translation(player2) + "发动了【归汉】");
      let num = 0;
      for (const target of event2.targets.sortBySeat()) {
        const result = await target.chooseCard("归汉：将一张" + get.translation(get.type2(card)) + "牌置于牌堆顶，或失去1点体力", (card2, player3) => {
          return get.type2(card2) == get.event().type;
        }).set("type", get.type2(card)).set("ai", (card2) => {
          const player3 = get.player();
          if (get.effect(player3, { name: "losehp" }, player3, player3) > 0) {
            return 0;
          }
          return 7 - get.value(card2);
        }).forResult();
        if (!result.bool) {
          await target.loseHp();
        } else {
          num++;
          target.$throw(1, 1e3);
          await target.lose(result.cards, ui.cardPile, "insert");
          game.log(target, "将一张牌置于了牌堆顶");
