        await game.delayx();
      }
      const { index } = await player2.chooseControl().set("choiceList", ["摸" + get.cnNumber(num) + "张牌", "获得牌堆顶第" + get.cnNumber(num) + "张牌下的两张牌"]).set("prompt", "归汉：请选择一项").set("ai", () => {
        const player3 = get.player(), index2 = num >= 3 - num ? 0 : 1;
        return player3.hasSkillTag("nogain") ? 1 - index2 : index2;
      }).set("num", num).forResult();
      if (index == 0 && num > 0) {
        await player2.draw(num);
      } else if (ui.cardPile.childElementCount > num) {
        const gains = Array.from(ui.cardPile.childNodes).slice(num, num + 2);
        if (gains.length > 0) {
          await player2.gain(gains, "gain2");
        }
      }
    },
    ai: {
      order: 1,
      threaten: 4.5,
      result: { target: -1 }
    }
  }

