tw:twciyin.code:
{
    audio: 2,
    global: "beOfOneHeart",
    oneHeart: true,
    trigger: {
      global: "phaseZhunbeiBegin"
    },
    filter(event2, player2) {
      const target = event2.player;
      return player2 == target || player2.getStorage("beOfOneHeartWith").includes(target);
    },
    async content(event2, trigger, player2) {
      const num = Math.min(trigger.player.getHp() * 2, 10);
      const cards2 = get.cards(num, true);
      await player2.showCards(cards2);
      const gain = cards2.filter((card) => ["heart", "spade"].includes(get.suit(card)));
      if (!gain.length) {
        return;
      }
      const { links } = await player2.chooseButton(["慈荫：你可以将其中任意张黑桃/红桃牌置于武将牌上", gain], [1, Infinity], "allowChooseAll").set("ai", get.buttonValue).forResult();
      if (!links || !links.length) {
        return;
      }
      const next = player2.addToExpansion(links);
      next.gaintag.add("twciyin");
      await next;
    },
    marktext: "荫",
    intro: {
      content: "expansion",
      markcount: "expansion"
    },
    onremove(player2, skill) {
      const cards2 = player2.getExpansions(skill);
      if (cards2.length) {
        player2.loseToDiscardpile(cards2);
      }
    },
    group: "twciyin_heart",
    subSkill: {
      heart: {
        audio: "twciyin",
        trigger: {
          player: "addToExpansionAfter"
        },
        filter(event2, player2) {
          if (!event2.gaintag.includes("twciyin")) {
            return false;
          }
          const history = game.getAllGlobalHistory("everything", (evt) => evt.name == "twciyin_heart" && evt.player == player2);
          const limit = history.map((evt) => evt.cost_data).flat();
          return !limit.includes("选项一") || !limit.includes("选项二") && player2.countCards("h") < player2.maxHp;
        },
        getIndex(event2, player2) {
          const history = game.getAllGlobalHistory("everything", (evt) => evt.name == "twciyin_heart" && evt.player == player2);
          const limit = history.map((evt) => evt.cost_data).flat();
          return Math.floor(player2.getExpansions("twciyin").length / 3) - limit.length;
        },
        async cost(event2, trigger, player2) {
          const history = game.getAllGlobalHistory("everything", (evt) => evt.name == "twciyin_heart" && evt.player == player2);
          const limit = history.map((evt) => evt.cost_data).flat();
          const choices = [];
          const choiceList = ["增加1点体力上限并回复1点体力", "将手牌摸至体力上限"];
          if (!limit.includes("选项一")) {
            choices.push("选项一");
          } else {
            choiceList[0] = '<span style="opacity:0.5;">' + choiceList[0] + "</span>";
          }
          if (!limit.includes("选项二") && player2.countCards("h") < player2.maxHp) {
            choices.push("选项二");
          } else {
            choiceList[1] = '<span style="opacity:0.5;">' + choiceList[1] + "</span>";
          }
          const control = choices.length == 1 ? choices[0] : (await player2.chooseControl(choices).set("prompt", get.prompt(event2.skill)).set("choiceList", choiceList).set("ai", () => {
            const player3 = get.player(), num = player3.maxHp - player3.countCards("h");
            return get.recoverEffect(player3, player3, player3) > get.effect(player3, { name: "draw" }, player3, player3) * num ? "选项一" : "选项二";
          }).forResult()).control;
          event2.result = {
            bool: true,
            cost_data: [control]
          };
        },
        async content(event2, trigger, player2) {
          if (event2.cost_data.includes("选项一")) {
            await player2.gainMaxHp();
            await player2.recover();
          }
          if (event2.cost_data.includes("选项二")) {
            await player2.drawTo(player2.maxHp);
          }
        }
      }
