{
    trigger: { player: "phaseBegin" },
    filter(event2, player2) {
      if (!game.hasPlayer((current) => current !== player2)) {
        return false;
      }
      return player2.getSkills().some((skill) => {
        const info = get.info(skill);
        if (!info || !info.oneHeart) {
          return false;
        }
        return true;
      });
    },
    forced: true,
    ruleSkill: true,
    async content(event2, trigger, player2) {
      const beOfOneHeartLimit = player2.storage.beOfOneHeartLimit || 1;
      const { targets } = await player2.chooseTarget("请选择你的“同心”角色", lib.filter.notMe, [1, beOfOneHeartLimit]).set("ai", function(target) {
        const aiCheck = lib.skill.beOfOneHeart.aiCheck.slice();
        let eff = 0;
        while (aiCheck.length) {
          const func = aiCheck.shift();
          if (typeof func !== "function") {
            continue;
          }
          eff += func.apply(this, arguments);
        }
        return eff;
      }).forResult();
      if (!targets || !targets.length) {
        return;
      }
      player2.line(targets, "green");
      game.log(player2, "选择了", targets, "作为自己的同心角色");
      player2.setStorage("beOfOneHeartWith", targets);
      player2.markSkill("beOfOneHeart");
      player2.when({ player: "phaseBegin" }, false).assign({ firstDo: true }).step(async () => {
        delete player2.storage.beOfOneHeartWith;
        player2.unmarkSkill("beOfOneHeart");
      }).finish();
      await game.delayx();
    },
    marktext: "❤",
    aiCheck: [
      (target) => {
        return get.attitude(get.player(), target);
