tw:twciyin_heart.code:
{
        audio: "twciyin",
        trigger: {
          player: "addToExpansionAfter"
        },
        filter(event2, player2) {
          if (!event2.gaintag.includes("twciyin")) {
            return false;
          }
          const history = game.getAllGlobalHistory("everything", (evt) => evt.name == "twciyin_heart" && evt.player == player2);
          const limit = history.map((evt) => evt.cost_data).flat();
          return !limit.includes("选项一") || !limit.includes("选项二") && player2.countCards("h") < player2.maxHp;
        },
        getIndex(event2, player2) {
          const history = game.getAllGlobalHistory("everything", (evt) => evt.name == "twciyin_heart" && evt.player == player2);
          const limit = history.map((evt) => evt.cost_data).flat();
          return Math.floor(player2.getExpansions("twciyin").length / 3) - limit.length;
        },
        async cost(event2, trigger, player2) {
          const history = game.getAllGlobalHistory("everything", (evt) => evt.name == "twciyin_heart" && evt.player == player2);
          const limit = history.map((evt) => evt.cost_data).flat();
          const choices = [];
          const choiceList = ["增加1点体力上限并回复1点体力", "将手牌摸至体力上限"];
          if (!limit.includes("选项一")) {
            choices.push("选项一");
          } else {
            choiceList[0] = '<span style="opacity:0.5;">' + choiceList[0] + "</span>";
          }
          if (!limit.includes("选项二") && player2.countCards("h") < player2.maxHp) {
            choices.push("选项二");
          } else {
            choiceList[1] = '<span style="opacity:0.5;">' + choiceList[1] + "</span>";
          }
          const control = choices.length == 1 ? choices[0] : (await player2.chooseControl(choices).set("prompt", get.prompt(event2.skill)).set("choiceList", choiceList).set("ai", () => {
            const player3 = get.player(), num = player3.maxHp - player3.countCards("h");
            return get.recoverEffect(player3, player3, player3) > get.effect(player3, { name: "draw" }, player3, player3) * num ? "选项一" : "选项二";
          }).forResult()).control;
          event2.result = {
            bool: true,
            cost_data: [control]
          };
        },
        async content(event2, trigger, player2) {
          if (event2.cost_data.includes("选项一")) {
            await player2.gainMaxHp();
            await player2.recover();
          }
          if (event2.cost_data.includes("选项二")) {
            await player2.drawTo(player2.maxHp);
          }
        }
      }

tw:twchenglong.code:
{
    audio: 2,
    trigger: { global: "phaseJieshuBegin" },
    forced: true,
    juexingji: true,
    skillAnimation: true,
    animationColor: "gray",
    filter(event2, player2) {
      return game.getAllGlobalHistory("everything", (evt) => evt.name == "twciyin_heart" && evt.player == player2).map((evt) => evt.cost_data).flat().length == 2;
    },
    async content(event2, trigger, player2) {
      player2.awakenSkill(event2.name);
      const cards2 = player2.getExpansions("twciyin");
      if (cards2.length) {
        await player2.gain(cards2, "gain2");
      }
      await player2.removeSkills("twciyin");
      let list = [];
      if (_status.characterlist) {
        for (const name of _status.characterlist) {
          if (["shu", "qun"].includes(lib.character[name][1])) {
            list.push(name);
          }
        }
      } else if (_status.connectMode) {
        list = get.charactersOL((name) => !["shu", "qun"].includes(lib.character[name][1]));
      } else {
        list = get.gainableCharacters((info) => ["shu", "qun"].includes(info[1]));
      }
      for (const current of game.players.concat(game.dead)) {
        list.removeArray(get.nameList(current));
      }
      const filter = (skill) => {
        const translation = get.skillInfoTranslation(skill, player2);
        if (!translation.length) {
          return false;
        }
        const info = get.info(skill);
        return info && !info.zhuSkill && !info.limited && !info.juexingji && !info.hiddenSkill && !info.charlotte && !info.dutySkill && ["【杀】", "【闪】"].some((str) => get.plainText(translation).includes(str));
      };
      list = list.filter((name) => (lib.character[name][3] || []).some(filter));
      if (!list.length) {
        return;
      }
      const skillList = {};
      list = list.randomGets(4);
      for (const name of list) {
        skillList[name] = (lib.character[name][3] || []).filter(filter).flat();
      }
      if (Object.values(skillList).length) {
        const result = await player2.chooseButton({
          createDialog: [
            [
              [[`成龙：获得其中至多两个技能`], "addNewRow"],
              [
                list,
                (item, type, position, noclick, node) => {
                  node = ui.create.button(item, "character", position, true);
                  lib.setIntro(node);
                  return node;
                }
              ],
              [
                [
                  Object.values(skillList).flat().map((skill) => [skill, get.translation(skill)]),
                  "tdnodes"
                ]
              ],
              [
                (dialog) => {
                  dialog.style.setProperty("top", get.is.phoneLayout() ? "20%" : "25%", "important");
                },
                "handle"
              ]
            ]
          ],
          forced: true,
          selectButton: [1, 2],
          ai(button) {
            const { link } = button;
            const info = get.info(link);
            if (info?.ai?.neg || info?.ai?.halfneg) {
              return 0;
            }
            return 1 + Math.random();
          }
        }).forResult();
        if (result?.links?.length) {
          await player2.addSkills(result.links);
        }
      }
    },
    ai: { combo: "twciyin" }
  }

