      return player2.getHistory("lose", (evt) => evt.cards2?.length).map((evt) => evt.cards2.map((card) => get.type2(card))).flat().unique().length > 1;
    },
    async cost(event2, trigger, player2) {
      const target = trigger.player;
      const choices = [];
      const choiceList = [`获得${get.translation(target)}装备区一张牌`, `获得并使用一张牌堆或弃牌堆中空置装备栏对应类别的装备牌`];
