        choices.push("选项一");
      } else {
        choiceList[0] = '<span style="opacity:0.5;">' + choiceList[0] + "</span>";
      }
      if (Array.from({ length: 5 }).map((_, i) => i + 1).some((i) => player2.hasEmptySlot(i))) {
        choices.push("选项二");
      } else {
        choiceList[1] = '<span style="opacity:0.5;">' + choiceList[1] + "</span>";
      }
      const { control } = await player2.chooseControl(choices, "cancel2").set("prompt", get.prompt(event2.skill)).set("choiceList", choiceList).set("ai", () => {
        const choices2 = get.event().controls.slice();
        const player3 = get.player(), evt = get.event().getTrigger(), target2 = evt.player;
        const eff = get.damageEffect(target2, player3, player3, evt.nature), att = get.attitude(player3, target2);
        if (att > 0) {
          if (eff >= 0) {
            return "cancel2";
          }
          return "选项二";
        }
        if (eff <= 0) {
          if (choices2.includes("选项一")) {
            return "选项一";
          }
          return "选项二";
        }
        if (target2.hp == 1 && att < 0 || evt.num > 1 || player3.hasSkill("tianxianjiu") || player3.hasSkill("luoyi2") || player3.hasSkill("reluoyi2")) {
          return "cancel2";
        }
        if (choices2.includes("选项一") && target2.countCards("e", (card) => {
          return get.effect(player3, card, player3, player3) > 0;
        })) {
          return "选项一";
        }
        return "选项二";
      }).forResult();
      event2.result = {
        bool: control != "cancel2",
        cost_data: control
      };
    },
    async content(event2, trigger, player2) {
      if (event2.cost_data == "选项一") {
        await player2.gainPlayerCard(trigger.player, "e", true);
