        for (let i = 1; i < 7; i++) {
          if (player2.hasEmptySlot(i)) {
            const sub = "equip" + i, equip = get.cardPile((card) => get.subtype(card, false) == sub && player2.hasUseTarget(card));
            if (equip) {
              player2.$gain2(equip);
