            return false;
          }
          if (event2.player == player2) {
            return !event2.iwhile;
          }
          return true;
        },
        forced: true,
        async content(event2, trigger, player2) {
          const num = player2.getDamagedHp();
          if (player2 == trigger.player) {
            trigger.num1 += num;
            if (trigger.num1 > 13) {
              trigger.num1 = 13;
            }
