        return true;
      }
      if (name == "shan" && filter({ name: "sha", cards: [card] }, player, event)) {
        return true;
      }
      if (name == "tao" && filter({ name: "jiu", cards: [card] }, player, event)) {
        return true;
      }
      if (name == "jiu" && filter({ name: "tao", cards: [card] }, player, event)) {
        return true;
      }
