tw:twguose.code:
{
    audio: 2,
    trigger: { global: ["changeHpAfter", "gainMaxHpAfter", "loseMaxHpAfter"] },
    filter(event2, player2) {
      if ((!event2.player || !event2.player.isDisabledJudge()) && event2.player?.hasJudge("lebu")) {
        return false;
      }
      if (!player2.hasCards("he") && (!event2.player || !event2.player.hasCards("he"))) {
        return false;
      }
      return get.info("twguose").damageStatusChanged(event2.player, event2);
    },
    damageStatusChanged(player2, evt) {
      if (!evt.changedMaxHp) {
        if (evt.changedHp > 0) {
          return !player2.isDamaged();
        }
        if (evt.changedHp < 0) {
          return player2.hp - evt.changedHp === player2.maxHp;
        }
      }
      if (evt.changedMaxHp > 0) {
        return player2.maxHp - evt.changedMaxHp === player2.getHp();
      }
      if (evt.changedMaxHp < 0) {
        return !player2.isDamaged() && evt.changedHp !== evt.changedMaxHp;
      }
      return false;
    },
    async skipDiscard(event2, trigger, player2) {
      if (event2._result.bool === false) {
        player2.skip("phaseDiscard");
