            return Math.random();
          }
          if (att <= 0) {
            return 20 + get.effect(targetx, { name: "lebu" }, player3, player3);
          } else if (targetx.hp <= 1) {
            return 0;
          }
          return Math.random();
        }
      }).set("targetx", target).forResult();
