          const target = event2.targets[0];
          const card = trigger.card;
          target.when("lebuBegin").filter((evt) => evt.getParent() == trigger.getParent()).then(async (event3, trigger2, player3) => {
            trigger2.setContent(get.info("twguose").skipDiscard);
          });
          game.log(player2, "将", get.translation(card), "改为跳过弃牌阶段");
        }
      },
      ai: {
        ai: {
          effect: {
            target(card, player2, target, result2) {
