    popup: false,
    async content(event2, trigger, player2) {
      const cards2 = get.bottomCards(4, true);
      const { links } = await player2.chooseButton([get.translation(trigger.player) + "的" + (trigger.judgestr || "") + "判定为" + get.translation(trigger.player.judging[0]) + "，" + get.prompt("twguimou"), cards2], true).set("filterButton", (button) => {
        const player3 = get.player(), card = button.link;
        const mod2 = game.checkMod(card, player3, "unchanged", "cardEnabled2", player3);
        if (mod2 != "unchanged") {
          return mod2;
        }
        const mod = game.checkMod(card, player3, "unchanged", "cardRespondable", player3);
        if (mod != "unchanged") {
          return mod;
        }
        return true;
      }).set("ai", (button) => {
        const card = button.link, trigger2 = get.event().getTrigger();
        const player3 = get.player(), judging = get.event().judging;
        const result = trigger2.judge(card) - trigger2.judge(judging) + 1e-5;
        const attitude = get.attitude(player3, trigger2.player);
        const name = trigger2.getParent().name;
        if (name == "twzongquan") {
          const target = trigger2.getParent().targets[0];
          const history = game.getAllGlobalHistory("everything", (evt2) => {
            if (evt2.name != "judge") {
              return false;
            }
            const evtx = evt2.getParent();
            return evtx.name == "twzongquan" && evtx.player == player3 && evtx != trigger2.getParent();
          });
          const evt = history[history.length - 1];
          if (evt && evt.getParent().targets[0] == target) {
            if (get.color(card) != evt.color) {
              return 114514 * result * attitude;
            }
          }
        }
        return result * attitude;
      }).set("judging", trigger.player.judging[0]).forResult();
      if (!links || !links.length) {
        return;
      }
      cards2.removeArray(links);
      await player2.respond(links, "twguimou", "highlight", "noOrdering");
      if (trigger.player.judging[0].clone) {
        trigger.player.judging[0].clone.classList.remove("thrownhighlight");
        game.broadcast(function(card) {
          if (card.clone) {
            card.clone.classList.remove("thrownhighlight");
          }
        }, trigger.player.judging[0]);
        game.addVideo("deletenode", player2, get.cardsInfo([trigger.player.judging[0].clone]));
      }
      await game.cardsDiscard(trigger.player.judging[0]);
