            return get.judge(judge)(card) * att;
          }
          return player3.getUseValue(card) * att;
        };
        const cards3 = list[0][1].slice(0);
        cards3.sort(function(a, b) {
          return check(b) * att - check(a) * att;
        });
        return [cards3];
