        return false;
      }
      if (cards2.length >= player2.getHp() || cards2.some((card) => get.name(card, player2) == "tao" || get.name(card, player2) == "jiu")) {
        return true;
      }
      return player2.getHp() > 2 && cards2.length > 1;
    },
    prompt2(event2, player2) {
      const cards2 = get.info("twqiaosi").getCards(player2);
      let str = "获得" + get.translation(cards2);
      if (cards2.length < player2.getHp()) {
        str += "，然后你失去1点体力";
      }
      return str;
    },
    async content(event2, trigger, player2) {
      const cards2 = get.info("twqiaosi").getCards(player2);
      await player2.gain(cards2, "gain2");
      if (cards2.length < player2.getHp()) {
        await player2.loseHp();
      }
    },
    getCards(player2) {
      let cards2 = [], targets = game.players.slice().concat(game.dead.slice());
      for (const target of targets) {
        if (target == player2) {
          continue;
        }
        const history = target.getHistory("lose", (evt) => evt.position == ui.discardPile);
        if (history.length) {
          for (const evt of history) {
            cards2.addArray(evt.cards2.filterInD("d"));
          }
        }
      }
      const historyx = game.getGlobalHistory("cardMove", (evt) => {
        if (evt.name != "cardsDiscard") {
          return false;
        }
        const evtx = evt.getParent();
        if (evtx.name != "orderingDiscard") {
          return false;
        }
        const evt2 = evtx.relatedEvent || evtx.getParent();
        const current = evt2.player;
        if (evt2.name == "phaseJudge" || current == player2) {
          return false;
        }
        return current.hasHistory("lose", (evtx3) => {
          const evtx4 = evtx3.relatedEvent || evtx3.getParent();
          if (evt2 != evtx4) {
            return false;
          }
          return evtx3.getl(current).cards2.length > 0;
        });
      });
      if (historyx.length) {
        for (const evtx of historyx) {
          cards2.addArray(evtx.cards.filterInD("d"));
        }
      }
      return cards2;
    }
  }

