{
    audio: 2,
    trigger: { player: "phaseEnd" },
    filter(event2, player2) {
      return player2.getHistory("sourceDamage", (evt) => {
        return evt.card && evt.card.name == "sha";
      }).length && player2.getHistory("custom", (evt) => {
        return evt.twhuajing_skills;
      }).reduce((list, evt) => list.addArray(evt.twhuajing_skills), []).some((skill) => player2.hasMark(skill));
    },
    forced: true,
    async content(event2, trigger, player2) {
      const { bool, targets } = await player2.chooseTarget(lib.filter.notMe, true).set("prompt", "天授：令一名其他角色获得1枚“武”并获得此标记的效果").set("ai", (target) => {
        const player3 = get.event().player, att = get.attitude(player3, target);
        const card = new lib.element.VCard({ name: "sha", isCard: true });
        if (att > 0) {
          return game.countPlayer((aim) => {
            return target.canUse(card, target) && get.effect(aim, card, target, player3) > 0 && get.effect(aim, card, target, target) > 0;
          }) + 10;
        }
        if (att == 0) {
          return 1.5 + Math.random();
        }
        return 0.1 + Math.random();
      }).forResult();
      if (bool) {
        const target = targets[0];
        const skills2 = player2.getHistory("custom", (evt) => {
          return evt.twhuajing_skills;
        }).reduce((list, evt) => list.addArray(evt.twhuajing_skills), []).filter((skill) => player2.hasMark(skill));
        let choiceList = skills2.map((i) => {
          return '<div class="skill">【' + get.translation(lib.translate[i + "_ab"] || get.translation(i).slice(0, 2)) + "】</div><div>" + get.skillInfoTranslation(i, player2, false) + "</div>";
        });
        const { control } = await player2.chooseControl(skills2).set("prompt", "选择令" + get.translation(target) + "获得的“武”").set("choiceList", choiceList).set("displayIndex", false).set("ai", () => get.event().controls.randomGet()).forResult();
        if (control) {
          player2.removeMark(control, 1);
          player2.markSkill("twhuajing");
          player2.popup(control, "metal");
          target.addTempSkill(control, { player: "phaseAfter" });
          target.addTempSkill("twhuajing_blocker", { player: "phaseAfter" });
          target.getHistory("custom").push({ twhuajing_skills: [control] });
          await player2.draw(2);
        }
      }
    },
    ai: { combo: "twhuajing" }
  }

tw:twdengjian.code:
{
    audio: 2,
    trigger: { global: "phaseDiscardEnd" },
    filter(event2, player2) {
      return event2.player != player2 && lib.skill.twdengjian.getCards(player2, event2.player).length;
    },
    getCards(player2, target) {
      let cards2 = target.getHistory("useCard", (evt) => {
        return evt.cards && evt.cards.filterInD("d").some((card) => get.name(card, false) == "sha") && target.getHistory("sourceDamage", (evtx) => {
          return evtx.card && evtx.card == evt.card;
        }).length;
      }).reduce((list, evt) => list.addArray(evt.cards.filterInD("d").filter((card) => get.name(card, false) == "sha")), []);
      if (cards2.length) {
        const history = player2.actionHistory;
        for (let i = history.length - 1; i >= 0; i--) {
          for (let evt of history[i].gain) {
            if (evt.getParent().name == "twdengjian") {
              const card = evt.cards[0];
              cards2 = cards2.filter((cardx) => get.color(cardx) != get.color(card));
              if (!cards2.length) {
                break;
              }
            }
          }
          if (history[i].isRound) {
            break;
          }
        }
      }
      return cards2;
    },
    frequent: true,
    async content(event2, trigger, player2) {
      const cards2 = lib.skill.twdengjian.getCards(player2, trigger.player);
      await player2.gain(cards2.randomGet(), "gain2").gaintag.add("twdengjianx");
    },
    group: "twdengjian_buff",
    subSkill: {
      buff: {
        mod: {
          aiOrder(player2, card, num) {
            if (get.itemtype(card) == "card" && card.hasGaintag("twdengjianx")) {
              return num + 0.1;
            }
          }
        },
        audio: "twdengjian",
        trigger: { player: "useCard1" },
        filter(event2, player2) {
          return event2.cards && event2.cards.length == 1 && player2.getHistory("lose", (evt) => {
            if ((evt.relatedEvent || evt.getParent()) != event2) {
              return false;
            }
            for (var i in evt.gaintag_map) {
              if (evt.gaintag_map[i].includes("twdengjianx")) {
                return true;
              }
            }
            return false;
          }).length && event2.addCount !== false;
        },
        forced: true,
        locked: false,
        async content(event2, trigger, player2) {
          trigger.addCount = false;
          if (player2.stat[player2.stat.length - 1].card.sha > 0) {
            player2.stat[player2.stat.length - 1].card.sha--;
          }
          game.log(trigger.card, "不计入次数限制");
        }
      }
    }
  }

