{
    audio: 2,
    trigger: { player: "useCard" },
    filter(event2, player2) {
      if (event2.card.name != "sha") {
        return false;
      }
      const goon = !player2.getHistory("useCard", (evt) => {
        return evt != event2 && evt.card.name == "sha" && get.color(evt.card) == get.color(event2.card);
      }).length && player2.isPhaseUsing();
      if (!player2.hasSkill("twxinshou_0")) {
        return goon;
      }
      if (!player2.hasSkill("twxinshou_1")) {
        return goon && game.hasPlayer((target) => target != player2);
      }
      return game.hasPlayer((target) => {
        if (target == player2) {
          return false;
        }
        return !target.hasSkill("twdengjian", null, null, false);
      }) && player2.hasSkill("twdengjian", null, null, false);
    },
    direct: true,
    async content(event2, trigger, player2) {
      if (player2.hasSkill("twxinshou_0") && player2.hasSkill("twxinshou_1")) {
        const { bool, targets } = await player2.chooseTarget((card, player3, target) => {
          return target != player3 && !target.hasSkill("twdengjian", null, null, false);
        }).set("ai", (target) => {
          const player3 = get.event().player;
          if (get.attitude(player3, target) > 0) {
            if (target.isTurnedOver()) {
              return 0;
            }
            const card = new lib.element.VCard({ name: "sha", isCard: true });
            if (game.hasPlayer((aim) => {
              return target.canUse(card, target) && get.effect(aim, card, target, player3) > 0 && get.effect(aim, card, target, target) > 0;
            })) {
              return target.countCards("h") - 3;
            }
            return 0;
          }
          return 0;
        }).set("prompt", get.prompt("twxinshou")).set("prompt2", "令【登剑】失效并令一名其他角色获得【登剑】，你的下个回合开始时，其失去【登剑】，若其这期间使用【杀】造成过伤害，则你结束【登剑】的失效状态").forResult();
        if (bool) {
          const target = targets[0];
          player2.logSkill("twxinshou", target);
          player2.tempBanSkill("twdengjian", "forever");
          target.addAdditionalSkills("twxinshou_" + player2.playerid, "twdengjian");
          player2.popup("登剑");
          target.popup("登剑");
          game.log(player2, "将", "#g【登剑】", "传授给了", target);
          const evtx = event2;
          player2.when("phaseBegin").step(async (event3, trigger2, player3) => {
            await target.removeAdditionalSkills("twxinshou_" + player3.playerid);
            const history = game.getAllGlobalHistory("everything");
            for (let i = history.length - 1; i >= 0; i--) {
              const evt = history[i];
              if (evt.name == "damage" && evt.card && evt.source && evt.card.name == "sha" && evt.source == target) {
                player3.popup("洗具");
                delete player3.storage[`temp_ban_twdengjian`];
                game.log(player3, "结束了", "#g【登剑】", "的失效状态");
                return;
              }
              if (evt == evtx) {
                break;
              }
            }
            player3.popup("杯具");
            player3.chat("剑法废掉了...");
          });
        }
      } else {
        let choice = [], choiceList = ["摸一张牌", "交给一名其他角色一张牌"];
        if (!player2.hasSkill("twxinshou_0")) {
          choice.push("摸牌");
        } else {
          choiceList[0] = '<span style="opacity:0.5">' + choiceList[0] + "</span>";
        }
        if (!player2.hasSkill("twxinshou_1") && game.hasPlayer((target) => target != player2)) {
          choice.push("给牌");
        } else {
          choiceList[1] = '<span style="opacity:0.5">' + choiceList[1] + "</span>";
        }
        const { control } = await player2.chooseControl(choice, "cancel2").set("prompt", get.prompt("twxinshou")).set("choiceList", choiceList).set("ai", () => {
          if (get.event().controls.includes("摸牌")) {
            return "摸牌";
          }
          const player3 = get.event().player;
          return game.hasPlayer((target) => {
            if (target == player3) {
              return false;
            }
            if (player3.countCards("he", (card) => card.name == "du") && get.attitude(player3, target) <= 0) {
              return true;
            }
            if (player3.countCards("he", (card) => get.value(card, player3) < 0 && get.attitude(player3, target) * get.value(card, target) > 0)) {
              return true;
            }
            return get.attitude(player3, target) > 0;
          }) && get.event().controls.includes("给牌") ? "给牌" : "cancel2";
        }).forResult();
        if (control == "cancel2") {
          return;
        }
        player2.logSkill("twxinshou");
        if (control == "摸牌") {
          player2.addTempSkill("twxinshou_0");
          await player2.draw();
        }
        if (control == "给牌") {
          player2.addTempSkill("twxinshou_1");
          const { bool, targets } = await player2.chooseTarget("交给一名其他角色一张牌", lib.filter.notMe, true).set("ai", (target) => {
