              return -att;
            }
            let cards2 = player3.getCards("he", (card) => get.value(card, player3) < 0);
            if (cards2.length) {
              cards2.sort((a, b) => get.value(a, player3) - get.value(b, player3));
              return get.value(cards2[0], target) * att;
            }
            return att;
          }).forResult();
          if (bool) {
            const target = targets[0];
            player2.line(target);
            await player2.chooseToGive(target, "he", true);
          }
        }
      }
    },
    derivation: "twdengjian",
    subSkill: {
      0: { charlotte: true },
      1: { charlotte: true }
    }
  }

