tw:twshenyi.code:
{
    audio: 2,
    trigger: { global: "damageEnd" },
    filter(event2, player2) {
      if (!event2.player.isIn()) {
        return false;
      }
      if (event2.player.getHistory("damage").indexOf(event2) != 0) {
        return false;
      }
      return event2.player == player2 || player2.inRange(event2.player);
    },
    usable: 1,
    async cost(event2, trigger, player2) {
      const { player: target } = trigger;
      const list = get.inpileVCardList((info) => {
        return ["basic", "trick", "delay"].includes(info[0]) && !player2.getStorage(event2.skill).includes(info[2]);
      });
      const dialog = [`###${get.prompt(event2.skill, target)}###<div class="text center">从牌堆中将一张牌作为“侠义”置于武将牌上${player2 != target && player2.countCards("h") ? "，然后将任意张手牌交给其" : ""}</div>`, [list, "vcard"]];
      const { bool, links } = await player2.chooseButton(dialog).set("ai", (button) => {
        _status.event.getTrigger();
        get.player();
        const name = button.link[2];
        if (!get.cardPile2((card) => card.name == name)) {
          return 0;
        }
        const value = get.value({ name });
        if (["tao", "jiu", "caochuan", "wuxie"].includes(name) && get.event().getRand() > 0.4) {
          return value * 2;
        }
        return value;
      }).forResult();
      event2.result = {
        bool,
        cost_data: links,
        targets: [target]
      };
    },
    async content(event2, trigger, player2) {
      const {
        cost_data: links,
        targets: [target],
        name: skillName
      } = event2;
      const name = links[0][2], nature = links[0][3];
      const cardx = { name, nature };
      player2.popup(cardx);
      player2.markAuto(skillName, [name]);
      game.log(player2, "声明了", `#y${get.translation(cardx)}`);
      const card = get.cardPile2((card2) => get.name(card2, false) == name && get.nature(card2, false) == nature);
      if (card) {
        const next = player2.addToExpansion([card], "gain2");
        next.gaintag.add(skillName);
        await next;
      } else {
        const card2 = get.cardPile2((card3) => get.type2(card3) == get.type2(name));
        if (card2) {
          const next = player2.addToExpansion([card2], "gain2");
          next.gaintag.add(skillName);
          await next;
        } else {
          player2.chat("无牌可得？！");
        }
      }
      if (target != player2 && player2.countCards("h")) {
        game.delayex();
        const skill = `${skillName}_${player2.playerid}`;
        game.addTempTag(skill, `义·${get.translation(player2.name)}`);
        player2.addSkill(skillName + "_draw");
        const next = player2.chooseToGive(target, `伸义：是否将任意张手牌交给${get.translation(target)}？`, [1, player2.countCards("h")], "allowChooseAll").set("ai", (card2) => {
          if (!_status.event.goon) {
            return 0;
          }
          return 7 - get.value(card2);
        }).set("goon", get.attitude(player2, target) > 0);
        next.gaintag.add(skill);
        await next;
      }
    },
    marktext: "义",
    intro: {
      name: "侠义",
      content: "expansion",
      markcount: "expansion"
    },
    onremove(player2, skill) {
      delete player2.storage[skill];
    },
    subSkill: {
      draw: {
        charlotte: true,
        audio: "twshenyi",
        trigger: { global: ["loseAfter", "equipAfter", "addJudgeAfter", "gainAfter", "loseAsyncAfter", "addToExpansionAfter"] },
        filter(event2, player2, name, target) {
          return target?.isIn();
        },
        forced: true,
        getIndex(event2, player2) {
          return game.filterPlayer((target) => {
            const evt = event2.getl(target);
            if (!evt?.hs?.length) {
              return false;
            }
            return Object.values(evt.gaintag_map).flat().includes(`twshenyi_${player2.playerid}`);
          }).sortBySeat();
        },
        logTarget: (event2, player2, triggername, target) => target,
        async content(event2, trigger, player2) {
          const evt = trigger.getl(event2.targets[0]);
          const num = Object.values(evt.gaintag_map).flat().reduce((numx, tag) => numx + (tag.includes(`twshenyi_${player2.playerid}`) ? 1 : 0), 0);
          if (num) {
            await player2.draw(num);
          }
        }
      }
    }
  }

