          player2.addSkill("twchengxi_effect");
        } else {
          const card = { name: "sha", isCard: true };
          if (target.canUse(card, player2, false)) {
            await target.useCard(card, player2, false);
          }
          player2.addSkill("twchengxi_add");
          player2.markAuto("twchengxi_add", [target]);
        }
      }
    },
