            return 0;
          }
          if (hs[0].number > ts[0].number) {
            return -3;
          }
          if (!target.canUse({ name: "sha", isCard: true }, player2, false)) {
            return -1;
          }
          return 0;
        }
      }
    },
    subSkill: {
      add: {
