tw:twdanlie.code:
{
    audio: 2,
    enable: "phaseUse",
    filter(event2, player2) {
      return game.hasPlayer((target) => player2.canCompare(target));
    },
    filterTarget(card, player2, target) {
      return player2.canCompare(target);
    },
    usable: 1,
    selectTarget: [1, 3],
    multitarget: true,
    multiline: true,
    group: "twdanlie_add",
    async content(event2, trigger, player2) {
      const { targets } = event2;
      const result = await player2.chooseToCompare(targets).setContent("chooseToCompareMeanwhile").forResult();
      if (result.winner && result.winner === player2) {
        player2.line(targets);
        for (const target of targets) {
          await target.damage();
        }
      } else {
        await player2.loseHp();
      }
    },
    ai: {
      order: 10,
      result: {
        target(player2, target) {
          const att = get.attitude(player2, target);
          if (att >= 0) {
            return 0;
          }
          if (player2.getHp() > 2) {
            return -get.damageEffect(target, player2, player2) - 10 / target.countCards("h");
          }
          const hs = player2.getCards("h").sort((a, b) => b.number - a.number);
          const ts = target.getCards("h").sort((a, b) => b.number - a.number);
          if (!hs.length || !ts.length) {
            return 0;
          }
          if (Math.min(13, hs[0].number + player2.getDamagedHp()) > ts[0].number) {
            return -get.damageEffect(target, player2, player2);
          }
          return 0;
        }
      }
    },
    subSkill: {
      add: {
        audio: "twdanlie",
        trigger: { player: "compare", target: "compare" },
        filter(event2, player2) {
          if (!player2.isDamaged()) {
            return false;
          }
          if (player2 !== event2.target && event2.iwhile) {
            return false;
          }
          return true;
        },
        forced: true,
        locked: false,
        async content(event2, trigger, player2) {
          const num = player2.getDamagedHp();
          if (player2 === trigger.player) {
            trigger.num1 += num;
            if (trigger.num1 > 13) {
              trigger.num1 = 13;
            }
          } else {
            trigger.num2 += num;
            if (trigger.num2 > 13) {
              trigger.num2 = 13;
            }
          }
          game.log(player2, "的拼点牌点数+", num);
        }
      }
    }
  }

