tw:twhuzhong.code:
{
    audio: 2,
    trigger: { player: "useCardToPlayer" },
    filter(event2, player2) {
      return event2.card.name === "sha" && !game.hasNature(event2.card, "linked") && event2.targets.length === 1 && player2.isPhaseUsing() && (game.hasPlayer((target) => !event2.targets.includes(target) && player2.canUse(event2.card, target)) || event2.target.hasCards("h"));
    },
    async cost(event2, trigger, player2) {
      const target = trigger.target;
      const list = ["cancel2"];
      const choiceList = ["令此【杀】可以额外指定一个目标", `弃置${get.translation(target)}一张手牌，若此【杀】造成伤害，则你本阶段可以额外使用一张【杀】`];
      if (target.hasCards("h")) {
        list.unshift("其弃置");
      } else {
        choiceList[1] = `<span style="opacity:0.5">${choiceList[1]}</span>`;
      }
      if (game.hasPlayer((targetx) => !trigger.targets.includes(targetx) && player2.canUse(trigger.card, targetx))) {
        list.unshift("多指");
      } else {
        choiceList[0] = `<span style="opacity:0.5">${choiceList[0]}</span>`;
      }
      const goon = (!target.mayHaveShan(player2, "use") || player2.hasSkillTag(
        "directHit_ai",
        true,
        {
          target,
          card: trigger.card
        },
        true
      )) && get.attitude(player2, target) < 0 && !player2.hasSkillTag("jueqing", false, target);
      const controlResult = await player2.chooseControl({
        controls: list,
        choiceList,
        prompt: "护众：是否摸一张牌并执行其中一项？",
        ai: () => {
          if (list.includes("其弃置") && goon) {
            return "其弃置";
          }
          if (list.includes("多指") && game.hasPlayer((targetx) => !trigger.targets.includes(targetx) && player2.canUse(trigger.card, targetx) && get.effect(targetx, trigger.card, player2, player2) > 0)) {
            return "你弃置";
          }
          return "cancel2";
        }
      }).setHiddenSkill(event2.skill).forResult();
      event2.result = {
        bool: controlResult.control !== "cancel2",
        targets: [target],
        cost_data: controlResult.control
      };
    },
    async content(event2, trigger, player2) {
      const target = event2.targets[0];
      await player2.draw();
      if (event2.cost_data === "其弃置") {
        await player2.discardPlayerCard({
          target,
          position: "h",
          forced: true
        });
        player2.when("useCardAfter").filter((evt) => evt === trigger.getParent()).step(async (event3, trigger2, player3) => {
          if (player3.getHistory("sourceDamage", (evt) => evt.card === trigger2.card).length) {
            player3.addTempSkill("twhuzhong_sha", "phaseUseAfter");
            player3.addMark("twhuzhong_sha", 1, false);
          }
        });
        return;
      }
      const targetResult = await player2.chooseTarget({
        prompt: `请选择${get.translation(trigger.card)}的额外目标`,
        filterTarget: (card, player3, target2) => {
          const trigger2 = _status.event.getTrigger();
          return !trigger2.targets.includes(target2) && player3.canUse(trigger2.card, target2);
        },
        ai: (target2) => {
          const player3 = _status.event.player;
          const trigger2 = _status.event.getTrigger();
          return get.effect(target2, trigger2.card, player3, player3);
        }
      }).forResult();
      if (targetResult.bool) {
        player2.line(targetResult.targets);
        trigger.getParent().targets.addArray(targetResult.targets);
        game.log(targetResult.targets, "成为了", trigger.card, "的额外目标");
      }
    },
    subSkill: {
      sha: {
        charlotte: true,
        onremove: true,
        mod: {
          cardUsable(card, player2, num) {
            if (card.name === "sha") {
              return num + player2.countMark("twhuzhong_sha");
            }
          }
        }
      }
    }
  }

