tw:twquanqian.code:
{
    audio: 2,
    trigger: { global: "phaseDrawEnd" },
    sunbenSkill: true,
    filter(event2, player2) {
      return event2.player != player2 && game.hasPlayer((current) => current.countCards("h") > 0);
    },
    check(event2, player2) {
      if (get.attitude(player2, event2.player) > 0) {
        return true;
      }
      return !player2.isMaxHandcard();
    },
    logTarget: "player",
    async content(event2, trigger, player2) {
      player2.awakenSkill(event2.name);
      player2.addSkill("twquanqian_sunben");
      const max = game.findPlayer((current) => current.isMaxHandcard());
      if (max) {
        const num = Math.min(5, max.countCards("h") - player2.countCards("h"));
        if (num > 0) {
          await player2.draw(num);
        }
      }
      if (!player2.countCards("he")) {
        player2.addMark("twquanqian_sunben", 1, false);
        return;
      }
      const target = trigger.player;
      const result = await player2.chooseToGive("he", target, [1, Infinity], "allowChooseAll", `是否交给${get.translation(target)}任意张牌？`).set("complexCard", true).set("ai", (card) => {
        if (get.event().att <= 0) {
          return 0;
        }
        if (ui.selected.cards.every((cardx) => get.type2(cardx) != get.type2(card))) {
          return 9 - get.value(card);
        }
        return 2 - get.value(card);
      }).set("att", get.attitude(player2, trigger.player)).forResult();
      if (!result?.bool || !result.cards?.length) {
        player2.addMark("twquanqian_sunben", 1, false);
        return;
      }
      const types = result.cards.map((card) => get.type2(card)).toUniqued();
      if (types.length) {
        await player2.draw(types.length);
      }
      const suits = result.cards.map((card) => get.suit(card)).toUniqued();
      if (suits.length) {
        target.addTempSkill("twquanqian_effect");
        target.addMark("twquanqian_effect", suits.length, false);
      }
      player2.addMark("twquanqian_sunben", result.cards.length, false);
    },
    subSkill: {
      sunben: {
        charlotte: true,
        init(player2, skill) {
          player2.clearMark(skill, false);
        },
        onremove: true,
        intro: { content: "还需#次有角色成为非延时伤害牌的目标且未受到该牌伤害" },
        trigger: { global: "useCardAfter" },
        getIndex(event2) {
          return event2.targets;
        },
        filter(event2, player2, name, target) {
          if (!event2.targets?.length) {
            return false;
          }
          if (!get.is.damageCard(event2.card)) {
            return false;
          }
          return !target?.hasHistory("damage", (evt) => evt.card == event2.card);
        },
        forced: true,
        popup: false,
        firstDo: true,
        async content(event2, trigger, player2) {
          player2.removeMark(event2.name, 1, false);
          if (!player2.countMark(event2.name)) {
            player2.removeSkill(event2.name);
            if (player2.hasSkill("twquanqian", null, null, false) && !player2.hasSkill("twquanqian")) {
              player2.popup("劝迁");
              player2.restoreSkill("twquanqian");
              game.log(player2, "恢复了技能", "#g【劝迁】");
            }
          }
        }
      },
      effect: {
        charlotte: true,
        onremove: true,
        intro: {
          content: "出杀次数+#"
        },
        mod: {
          cardUsable(card, player2, num) {
