        }
        if (player2.hasSkill("twzhiqu")) {
          const cnt = game.countPlayer((current) => get.distance(player2, current) === 2);
          if (att > 0) {
            if (cnt || player2.needsToDiscard(1)) {
              return 0;
            }
            return 1;
          }
          if (!cnt) {
            return 0;
          }
          if (cnt >= 2 || get.distance(target, player2, "attack") === 2 || get.distance(target, player2) === 2) {
            return 1;
          }
          return 0;
        }
        if (att < 0 || player2.needsToDiscard(1) && game.hasPlayer((current) => current !== player2 && current !== target && !player2.inRange(current))) {
          return 0;
        }
        return [0, 1].randomGet();
      })();
