          player2.storage.twxuechang_add = {};
        }
        if (!player2.storage.twxuechang_add[target.playerid]) {
          player2.storage.twxuechang_add[target.playerid] = 0;
        }
        player2.storage.twxuechang_add[target.playerid]++;
        player2.markSkill("twxuechang_add");
      }
    },
    ai: {
      order: 6.5,
      result: {
        target(player2, target) {
          var hs = player2.getCards("h").sort(function(a, b) {
            return get.number(b) - get.number(a);
          });
          var ts = target.getCards("h").sort(function(a, b) {
            return get.number(b) - get.number(a);
          });
          if (!hs.length || !ts.length) {
            return 0;
          }
          if (get.attitude(player2, target) < 0 && (get.number(hs[0]) > get.number(ts[0]) || get.number(hs[0]) - ts.length >= 9 + Math.min(2, player2.hp / 2))) {
            return get.sgnAttitude(player2, target) * get.effect(target, { name: "shunshou_copy2" }, player2, player2);
          }
          return 0;
        }
      }
    },
    subSkill: {
      add: {
        audio: "twxuechang",
        trigger: { source: "damageBegin1" },
        filter(event2, player2) {
          return player2.storage.twxuechang_add && player2.storage.twxuechang_add[event2.player.playerid];
        },
        forced: true,
        charlotte: true,
        async content(event2, trigger, player2) {
          trigger.num += player2.storage.twxuechang_add[trigger.player.playerid];
          delete player2.storage.twxuechang_add[trigger.player.playerid];
          if (get.is.empty(player2.storage.twxuechang_add)) {
            player2.removeSkill("twxuechang_add");
          } else {
            player2.markSkill("twxuechang_add");
          }
        },
        marktext: "偿",
        intro: {
          content(storage, player2) {
            if (!storage) {
              return "";
            }
            var str = "";
            var map = _status.connectMode ? lib.playerOL : game.playerMap;
            for (var i in storage) {
              str += "<li>下次对" + get.translation(map[i]) + "造成的伤害+" + storage[i];
            }
            return str;
          }
        }
      }
    }
  }

tw:twduoren.code:
{
    audio: 2,
    trigger: { global: "dieAfter" },
    check(event2, player2) {
      const skills2 = event2.player.getStockSkills(true, true).filter((skill) => {
        if (player2.hasSkill(skill, null, false, false)) {
          return false;
        }
        const info = get.info(skill);
        return info && !info.hiddenSkill && !info.zhuSkill && !info.charlotte;
      });
      return skills2.length > 0;
    },
    prompt2(event2, player2) {
      const skills2 = event2.player.getStockSkills(true, true).filter((skill) => {
        const info = get.info(skill);
        return info && !info.hiddenSkill && !info.zhuSkill && !info.charlotte;
      });
      let str1 = "";
      for (const i of skills2) {
        str1 += "〖" + get.translation(i) + "〗、";
      }
      str1 = str1.slice(0, str1.length - 1);
      let str2 = "";
      for (const i of player2.getSkills(null, false, false).filter((skill) => {
        const info = get.info(skill);
        return info && !info.charlotte && !player2.getStockSkills(true, true).includes(skill);
      })) {
        str2 += "〖" + get.translation(i) + "〗、";
      }
      str2 = str2.slice(0, str2.length - 1);
      return `${str2.length ? `失去${str2}，然后` : ""}${str1.length ? "获得" + str1 : "听一句技能配音"}`;
    },
    filter(event2, player2) {
      return event2.player != player2 && (player2.hasAllHistory("sourceDamage", (evt) => evt.player == event2.player) || player2.hasAllHistory("damage", (evt) => evt.source == event2.player)) && !event2.reserveOut;
    },
    logTarget: "player",
    async content(event2, trigger, player2) {
      await player2.changeSkills(
        trigger.player.getStockSkills(true, true).filter((skill) => {
          const info = get.info(skill);
          return info && !info.hiddenSkill && !info.zhuSkill && !info.charlotte;
        }),
        player2.getSkills(null, false, false).filter((skill) => {
          const info = get.info(skill);
          return info && !info.charlotte && !player2.getStockSkills(true, true).includes(skill);
        })
      );
    }
  }

tw:twyanshi.code:
{
    audio: 2,
    enable: "phaseUse",
    filter(event2, player2) {
      const cards2 = event2.twyanshi;
      return cards2?.length > 0 && player2.countCards("hs") > 0;
    },
    onChooseToUse(event2) {
      if (game.online || event2.twyanshi) {
        return;
      }
      const targets = game.filterPlayer((current) => {
        return current.hasMark("twyanshi_mark");
      }), player2 = event2.player;
      if (!targets?.length) {
        event2.set("twyanshi", []);
        return;
      }
      const list = get.inpileVCardList((list2) => {
        const info = lib.card[list2[2]];
        if (!info || info.notarget || info.selectTarget && info.selectTarget != 1) {
          return false;
        }
        if (!get.tag({ name: list2[2] }, "damage")) {
          return false;
        }
        return targets?.some((target) => player2.canUse(list2[2], target));
      });
      event2.set("twyanshi", list);
    },
