tw:twrenchou.code:
{
    audio: 2,
    trigger: { global: ["die", "dieAfter"] },
    forced: true,
    forceDie: true,
    filter(event2, player2, name) {
      if (name == "die") {
        return event2.player == player2 && player2.getStorage("twyanshi").some((i) => i.isIn());
      }
      return player2.getStorage("twyanshi").includes(event2.player);
    },
    skillAnimation: true,
    animationColor: "water",
    async content(event2, trigger, player2) {
      if (trigger.player == player2) {
        for (const current of player2.getStorage("twyanshi").sortBySeat(_status.currentPhase)) {
          if (current.isIn()) {
            player2.line(current, "green");
            await current.addSkills("twyanshi");
          }
        }
      } else {
        player2.addSkill("twrenchou_fuqi");
      }
    },
    ai: {
      combo: "twyanshi"
    },
    subSkill: {
      fuqi: {
        trigger: {
          player: "useCard"
        },
        charlotte: true,
        filter(event2, player2) {
          const targets = get.info("twrenchou_fuqi")?.logTarget(event2, player2);
          return targets?.length;
        },
        logTarget(event2, player2) {
          return game.filterPlayer((current) => {
            return current.countMark("twyanshi_mark");
          });
        },
        forced: true,
        locked: false,
        async content(event2, trigger, player2) {
          trigger.directHit.addArray(event2.targets);
        }
      },
      ai: {
        ai: {
          effect: {
            target(card, player2, target) {
              if (!get.tag(card, "damage")) {
                return;
              }
              if (target.hp > 1) {
                return;
              }
              var num = 0;
              game.filterPlayer((current) => {
                if (current.getStorage("twyanshi").some((i) => target == i)) {
                  num += current.hp;
                }
              });
              var targets = target.getStorage("twyanshi").filter((i) => i.isIn());
              for (var targetx of targets) {
                num += targetx.hp;
              }
              if (num >= player2.hp) {
                return 0;
              }
              if (num > 0) {
                return [1, 0, 0, 0.5 - 1.5 * num];
              }
            }
          }
        }
      }
    }
  }

tw:twkaizeng.code:
{
    audio: 2,
    global: "twkaizeng_want",
    refuseInfo: ["不给", "拒绝"],
    subSkill: {
      want: {
        audio: "twkaizeng",
        forceaudio: true,
        enable: "phaseUse",
        charlotte: true,
        prompt: "点击“确定”来寻求施舍",
        filter(event2, player2) {
          if (player2.hasSkill("twkaizeng_used")) {
            return false;
          }
          return game.hasPlayer((current) => current != player2 && current.hasSkill("twkaizeng") && current.countCards("h"));
        },
        chooseButton: {
          dialog(event2, player2) {
            const targets = game.filterPlayer((current) => current != player2 && current.hasSkill("twkaizeng") && current.countCards("h"));
            return ui.create.dialog("###慨赠###选择一种基本牌的牌名或非基本牌的类型，然后令" + get.translation(targets) + (targets.length > 1 ? "中的一人" : "") + "选择是否交给你任意张手牌");
          },
          chooseControl() {
            const list = [];
            for (let i = 0; i < lib.inpile.length; i++) {
              const name = lib.inpile[i];
              const type = get.type2(name);
              if (type == "basic") {
                list.push(name);
              } else {
                list.add(type);
              }
            }
            list.push("cancel2");
            return list;
          },
          check(event2, player2) {
            if (Math.random() < 0.4) {
              const list2 = get.event().controls.slice();
              list2.remove("du");
              return list2.randomGet();
            }
            const targets = game.filterPlayer((current) => current != player2 && current.hasSkill("twkaizeng") && current.countCards("h"));
            targets.sort((a, b) => get.attitude(player2, b) - get.attitude(player2, a));
            const cards2 = targets[0].getCards("h");
            const list = [];
            for (const card of cards2) {
              const type = get.type2(card);
              if (type == "basic") {
                list.add(get.name(card));
              } else {
                list.add(type);
              }
            }
            const need = ["trick", "equip"].randomSort();
            need.addArray(["sha", "jiu"].randomSort());
            for (const type of need) {
              if (list.includes(type)) {
                return type;
              }
            }
            return list.randomGet();
          },
          backup(result, player2) {
            return {
              audio: "twkaizeng",
              type: result.control,
              log: false,
              delay: false,
              filterTarget(card, player3, target) {
                return target.hasSkill("twkaizeng");
              },
              selectTarget() {
                const player3 = get.player();
                const targets = game.filterPlayer((current) => current != player3 && current.hasSkill("twkaizeng") && current.countCards("h"));
                return targets.length > 1 ? 1 : -1;
              },
              prepare(cards2, player3, targets) {
                targets[0].logSkill("twkaizeng_want", player3);
              },
              async content(event2, trigger, player3) {
                player3.addTempSkill("twkaizeng_used", "phaseUseAfter");
                const { target, name } = event2;
                const type = lib.skill[name].type;
                const isbasic = lib.card[type];
                const { bool, cards: cards2 } = await target.chooseToGive(player3, `慨赠：是否交给${get.translation(player3)}任意张手牌？`, `若你以此法：交给其至少两张牌，你摸一张牌；交给其的牌包含${get.translation(type)}${isbasic ? "" : "牌"}，你获得一张不为此牌名或类型的牌`, [1, Infinity]).set("allowChooseAll", true).set("ai", (card) => {
                  const { player: player4, target: target2, goon, type: type2 } = get.event();
                  if (!goon) {
                    return -get.value(card);
                  }
                  if (ui.selected.cards.length > player4.countCards("h") / 2 && ui.selected.cards.length >= 2) {
                    return 0;
                  }
                  const isbasic2 = lib.card[type2];
                  let add = 0;
                  if (!ui.selected.cards.some((i) => get[isbasic2 ? "name" : "type2"](i, target2) == type2)) {
                    add += 3;
                  }
                  if (ui.selected.cards.length < 2) {
                    add += 3;
                  }
                  return get.value(card, target2) - get.value(card, player4) + add;
                }).set("type", type).set("goon", get.attitude(target, player3) > 0).forResult();
                if (bool) {
                  if (cards2.length > 1) {
                    await target.draw();
                  }
                  const fn = isbasic ? "name" : "type2";
                  if (cards2.some((card) => get[fn](card, player3) == type)) {
                    const card = get.cardPile((cardx) => get[fn](cardx, target) != type);
                    if (card) {
                      await target.gain(card, "gain2");
                    }
                  }
                  await game.delayx();
                } else {
                  const refuseInfo = lib.skill.twkaizeng.refuseInfo.slice();
                  if (get.attitude(target, player3) < 0) {
                    refuseInfo.push("没门");
                  }
                  target.chat(refuseInfo.randomGet());
                }
              },
              ai: { result: { target: 1 } }
            };
          },
          prompt: () => "请选择一名有【慨赠】的角色"
        },
        ai: {
          order: 10,
          result: {
            player(player2) {
              if (game.hasPlayer((current) => current != player2 && current.hasSkill("twkaizeng") && current.countCards("h") && get.attitude(player2, current) > 0)) {
                return 1;
              }
              return 0;
            }
          }
        }
      },
      want_backup: {},
      used: { charlotte: true }
    },
    ai: { threaten: 3 }
  }

