tw:twliexi.code:
{
    audio: 2,
    trigger: { player: "phaseZhunbeiBegin" },
    filter(event2, player2) {
      return player2.hasCards("he");
    },
    chooseAi: (event2, player2) => {
      const cards2 = [];
      const wq = [];
      player2.getCards("he", (card) => {
        if (!lib.filter.cardDiscardable(card, player2)) {
          return false;
        }
        if (get.subtype(card) === "equip1") {
          wq.push([get.value(card, player2), card.cardid, true]);
        } else {
          cards2.push([get.value(card, player2), card.cardid]);
        }
      });
      cards2.sort((a, b) => a[0] - b[0]);
      wq.sort((a, b) => a[0] - b[0]);
      const targets = [];
      const damage = get.damageEffect(player2, player2, event2.player);
      game.countPlayer((cur) => {
        if (player2 === cur) {
          return false;
        }
        const eff = get.damageEffect(cur, player2, event2.player);
        const dui = eff + damage - 2 * (wq.length ? wq[0][0] : cards2[0][0]);
        if (eff <= 0) {
          if (dui > 0) {
            targets.push([cur, dui, [wq.length ? wq[0][1] : cards2[0][1]]]);
          }
          return false;
        }
        if (cards2.length + wq.length <= cur.hp && //牌不够弃且没有武器可砸或者有但是太亏的不选
        (!wq.length || dui <= 0)) {
          return false;
        }
        let allcards = cards2.concat(wq).sort((a, b) => a[0] - b[0]);
        let can;
        if (allcards.length <= cur.hp) {
          targets.push([cur, dui, [wq[0][1]]]);
          return false;
        }
        can = eff - allcards.slice(0, cur.hp + 1).reduce((acc, val) => acc + val[0], 0);
        if (!wq.length) {
          if (can > 0) {
            targets.push([cur, can, allcards.slice(0, cur.hp + 1).map((i) => i[1])]);
          }
          return false;
        }
        const other = [wq[0]];
        for (const card of allcards) {
          if (other.length > cur.hp) {
            break;
          }
          if (wq[0][1] === card[1]) {
            continue;
          }
          other.push(card);
        }
        if (can < 2 * eff - other.reduce((acc, val) => acc + val[0], 0)) {
          can = 2 * eff - other.reduce((acc, val) => acc + val[0], 0);
          allcards = other.map((i) => i[1]);
        }
        if (dui > can) {
          can = dui;
          allcards = [wq[0][1]];
        }
        if (can > 0) {
          targets.push([cur, can, allcards]);
        }
      });
      if (targets.length) {
        return targets.sort((a, b) => b[1] - a[1])[0];
      }
      return [null, 0, []];
    },
    async cost(event2, trigger, player2) {
      event2.result = await player2.chooseCardTarget({
        filterCard: lib.filter.cardDiscardable,
        selectCard: [1, Infinity],
        position: "he",
        filterTarget: lib.filter.notMe,
        prompt: get.prompt2(event2.skill),
        aiSelected: lib.skill.twliexi.chooseAi(_status.event, player2),
        ai1(card) {
          if (get.event().aiSelected[2].includes(card.cardid)) {
            return 30 - get.value(card);
          }
          return 0;
        },
        ai2(target) {
          if (get.event().aiSelected[0] === target) {
            return 10;
          }
          return 0;
        },
        allowChooseAll: true
      }).forResult();
    },
    async content(event2, trigger, player2) {
      const target = event2.targets[0];
      const cards2 = event2.cards;
      await player2.discard({ cards: cards2 });
      if (cards2.length > target.hp) {
        await target.damage();
      } else {
        await player2.damage({ source: target });
      }
      if (!cards2.some((card) => get.subtype(card) === "equip1")) {
        return;
      }
      await game.delayx();
      await target.damage();
    }
  }

tw:twshezhong.code:
{
    audio: 2,
    trigger: { player: "phaseJieshuBegin" },
    direct: true,
    async content(event2, trigger, player2) {
      const damage = player2.getHistory("sourceDamage").length;
      if (damage) {
        const minusResult = await player2.chooseTarget({
          prompt: get.prompt("twshezhong"),
          prompt2: `令至多${get.cnNumber(damage)}名其他角色下个摸牌阶段的摸牌数-1`,
          selectTarget: [1, damage],
          filterTarget: lib.filter.notMe,
          ai: (target) => -get.attitude(_status.event.player, target)
        }).forResult();
        if (minusResult.bool) {
          player2.logSkill("twshezhong", minusResult.targets);
          for (const target of minusResult.targets) {
            target.addSkill("twshezhong_minus");
            target.addMark("twshezhong_minus", 1, false);
          }
        }
      }
      const targets = [];
      for (const evt of player2.getHistory("damage")) {
        if (evt.source && evt.source.isIn()) {
          targets.add(evt.source);
        }
      }
      if (!targets.length) {
        return;
      }
      const drawResult = await player2.chooseTarget({
        prompt: get.prompt("twshezhong"),
        prompt2: "将手牌摸至一名与一名本回合对你造成过伤害的角色的体力值相同，且至多摸至五张",
        filterTarget: (card, player3, target) => targets.includes(target),
        ai: (target) => Math.max(0.1, target.hp - _status.event.player.countCards("h"))
      }).forResult();
      if (drawResult.bool) {
        const target = drawResult.targets[0];
        player2.logSkill("twshezhong", target);
        const num = Math.min(target.hp, 5) - player2.countCards("h");
        if (num > 0) {
          await player2.draw(num);
        }
      }
    },
    subSkill: {
      minus: {
        trigger: { player: "phaseDrawBegin" },
        forced: true,
        onremove: true,
        async content(event2, trigger, player2) {
          const num = player2.countMark("twshezhong_minus");
          trigger.num -= num;
          game.log(player2, "的额定摸牌数", `#g-${num}`);
          player2.removeSkill("twshezhong_minus");
        },
        mark: true,
        intro: {
          content: "额定摸牌数-#"
        }
      }
    }
  }

tw:twbingde.code:
{
    audio: 2,
    enable: "phaseUse",
    usable: 1,
    filter(event2, player2) {
      return player2.countCards("he") && player2.getStorage("twbingde_clear").length < 4;
    },
    onChooseToUse(event2) {
      if (event2.type == "phase" && !game.online) {
        const map = {};
        event2.player.getHistory("useCard", (evt) => {
          const evtx = evt.getParent("phaseUse"), suit = get.suit(evt.card);
          if (!lib.suit.includes(suit)) {
            return;
          }
          if (evtx != event2.getParent("phaseUse")) {
            return;
          }
          if (typeof map[suit] != "number") {
            map[suit] = 0;
          }
          map[suit]++;
        });
        event2.set("twbingde_map", map);
      }
    },
    chooseButton: {
      dialog(event2, player2) {
        let str = get.translation("twbingde_info"), str2 = "";
        if (event2.twbingde_map) {
          str2 = '<div class="text center">本回合使用牌对应花色数：</div>';
          str2 += '<div class="text center">';
          for (const suit of lib.suit) {
            str2 += get.translation(suit) + "：" + get.cnNumber(event2.twbingde_map[suit] || 0) + "张；";
          }
          str2 = str2.slice(0, str2.length - 1) + "</div>";
        }
        return ui.create.dialog("###秉德###" + str, str2);
      },
      chooseControl(event2, player2) {
        const list = lib.suit.slice();
        list.removeArray(player2.getStorage("twbingde_clear"));
        list.push("cancel2");
        return list;
      },
      check(event2, player2) {
        const map = event2.twbingde_map;
        const suit = lib.suit.filter((suit2) => !player2.getStorage("twbingde_clear").includes(suit2) && player2.hasCard((card) => get.suit(card) == suit2, "he")).sort((a, b) => {
          return map[b] - map[a];
        })[0];
        if (map[suit] == 0) {
          return "cancel2";
        }
        return suit;
      },
      backup(result, player2) {
        return {
          audio: "twbingde",
          filterCard: lib.filter.cardDiscardable,
          position: "he",
          suit: result.control,
          check(card) {
            const suit = lib.skill.twbingde_backup.suit;
            if (get.suit(card) == suit) {
              return 10 - get.value(card);
            }
            return 6 - get.value(card);
          },
          async content(event2, trigger, player3) {
            const { suit } = get.info(event2.name);
            let num = 0;
            player3.popup(suit + 2);
            game.log(player3, "选择了", "#y" + suit + 2);
            player3.addTempSkill("twbingde_clear", "phaseUseAfter");
            player3.markAuto("twbingde_clear", [suit]);
            player3.getHistory("useCard", (evt) => {
              var evtx = evt.getParent("phaseUse"), suitx = get.suit(evt.card);
              if (!evtx || evtx != event2.getParent("phaseUse") || suit != suitx) {
                return false;
              }
              num++;
            });
            if (num > 0) {
              await player3.draw(num);
            }
            if (get.suit(event2.cards[0], player3) == suit && player3.getStat("skill").twbingde) {
              delete player3.getStat("skill").twbingde;
              game.log(player3, "重置了", "#g【秉德】");
            }
          },
          ai: { result: { player: 1 } }
        };
      },
      prompt: () => "秉德：弃置一张牌"
    },
    ai: {
      order: 2,
      result: { player: 1 }
    },
    subSkill: {
      backup: {},
      clear: {
        charlotte: true,
        onremove: true
      }
    }
  }

