tw:twxiafeng.code:
{
    audio: 2,
    trigger: { player: "phaseUseBegin" },
    filter(event2, player2) {
      return player2.countMark("baonvezhi") > 0;
    },
    init(player2) {
      lib.skill.baonvezhi.change(player2, 0);
    },
    async cost(event2, trigger, player2) {
      const result = await player2.chooseButton({
        createDialog: ["黠凤：选择要消耗的暴虐值", [["tw_bn_1", "tw_bn_2", "tw_bn_3"], "vcard"]],
        filterButton: (button) => {
          const link = button.link[2];
          return link[link.length - 1] * 1 <= player2.storage.baonvezhi;
        },
        ai: (button) => {
          let num = player2.countCards("hs", (card) => get.tag(card, "damage") && game.hasPlayer((current) => get.effect(current, card, player2, player2) > 0));
          if (num <= 0) {
            return 0;
          }
          if (num >= 3) {
            num = 3;
          }
          if (button.link[2] === `tw_bn_${num}`) {
            return 10;
          }
          return 1;
        }
      }).forResult();
      event2.result = {
        bool: result.bool,
        cost_data: result.links
      };
    },
    async content(event2, trigger, player2) {
      const link = event2.cost_data[0][2];
      const num = link[link.length - 1] * 1;
      player2.addTempSkill("twxiafeng_effect");
      player2.storage.twxiafeng_effect = num;
      lib.skill.baonvezhi.change(player2, -num);
    },
    subSkill: {
      effect: {
        audio: "twxiafeng",
        trigger: { player: "useCard" },
        filter(event2, player2) {
          return !player2.storage.twxiafeng_effect2;
        },
        forced: true,
        async content(event2, trigger, player2) {
          const count = player2.getHistory("useCard", (evt) => evt.getParent("phaseUse").player === player2).length;
          if (count === player2.storage.twxiafeng_effect) {
            player2.storage.twxiafeng_effect2 = true;
          }
          if (count <= player2.storage.twxiafeng_effect) {
            trigger.directHit.addArray(game.players);
            if (trigger.addCount !== false) {
              trigger.addCount = false;
              const stat = player2.getStat().card;
              const name = trigger.card.name;
              if (typeof stat[name] === "number") {
                stat[name]--;
              }
            }
          }
        },
        onremove(player2) {
          delete player2.storage.twxiafeng_effect;
          delete player2.storage.twxiafeng_effect2;
        },
        mod: {
          targetInRange(card, player2, target, now) {
            if (!player2.storage.twxiafeng_effect2) {
              return true;
            }
          },
          cardUsableTarget(card, player2, target) {
            if (!player2.storage.twxiafeng_effect2) {
              return true;
            }
          },
          maxHandcard(player2, num) {
            return num + (player2.storage.twxiafeng_effect || 0);
          }
        }
      }
    },
    ai: {
      combo: "twjuntun"
    }
  }

