tw:twlinglu.code:
{
    trigger: { player: "phaseUseBegin" },
    filter(event2, player2) {
      return game.hasPlayer((current) => current !== player2);
    },
    async cost(event2, trigger, player2) {
      event2.result = await player2.chooseTarget({
        prompt: get.prompt2(event2.skill),
        filterTarget: (card, player3, target) => target !== player3,
        ai: (target) => {
          const player3 = _status.event.player;
          const attitude = get.attitude(player3, target);
          if (target.countCards("hs") > 4 && target.hp >= 3) {
            return attitude;
          }
          if (player3.getStorage("twlinglu").includes(target)) {
            return -2 * attitude;
          }
          return -attitude;
        }
      }).forResult();
    },
    async content(event2, trigger, player2) {
      const target = event2.targets[0];
      target.addTempSkill("twlinglu_order", { player: "phaseAfter" });
      if (!target.storage.twlinglu_settle) {
        target.storage.twlinglu_settle = [];
      }
      target.storage.twlinglu_settle.unshift([player2, 1]);
      if (!player2.getStorage("twlinglu").includes(target)) {
        return;
      }
      const settleTwice = await player2.chooseBool({
        prompt: `是否令${get.translation(target)}于〖令戮〗失败时进行两次结算？`,
        ai: () => true
      }).forResult();
      if (settleTwice?.bool) {
        target.storage.twlinglu_settle[0][1]++;
        game.log(target, "于本次强令失败时进行两次结算");
