          return player2.getStorage("twjichou").includes(get.name(card));
        })) {
          dialog._chosenOpt = [];
          var table = document.createElement("div");
          table.classList.add("add-setting");
          table.style.margin = "0";
          table.style.width = "100%";
          table.style.position = "relative";
