            if (i == list[0]) {
              td.classList.add("bluebg");
              dialog._chosenOpt.add(td);
            }
            td.addEventListener(lib.config.touchscreen ? "touchend" : "click", function() {
              if (_status.dragged) {
                return;
              }
              if (_status.clicked) {
                return;
              }
              if (_status.justdragged) {
                return;
              }
              _status.tempNoButton = true;
              _status.clicked = true;
              setTimeout(function() {
                _status.tempNoButton = false;
              }, 500);
              var link = this.link;
              if (link == "交出锦囊牌") {
                game.uncheck();
              }
              var current = this.parentNode.querySelector(".bluebg");
              if (current) {
                current.classList.remove("bluebg");
                dialog._chosenOpt.remove(current);
              }
              dialog._chosenOpt.add(this);
              this.classList.add("bluebg");
              game.check();
            });
            table.appendChild(td);
            dialog.buttons.add(td);
          }
          dialog.content.appendChild(table);
        }
        var list = [], record = player2.getStorage("twjichou");
        for (var name of lib.inpile) {
          if (get.type(name) == "trick" && !record.includes(name) && event2.filterCard({ name, isCard: true }, player2, event2)) {
            list.push(["锦囊", "", name]);
          }
        }
        dialog.add([list, "vcard"]);
        return dialog;
      },
      filter(button) {
