            return false;
          }
          return true;
        }
        return false;
      },
      select() {
        if (_status.event.dialog) {
          var opts = _status.event.dialog._chosenOpt;
          return opts && opts.length && opts[0].link == "交出锦囊牌" ? 0 : 1;
