tw:twjilun.code:
{
    audio: 2,
    trigger: { player: "damageEnd" },
    async cost(event2, trigger, player2) {
      const num = Math.min(Math.max(1, player2.getStorage("twjichou").length), 5);
      const list = player2.getStorage("twjichou").filter((name) => !player2.getStorage(event2.skill).includes(name)).map((name) => ["锦囊", "", name]);
      if (list.length) {
        const result = await player2.chooseButton([`###${get.prompt(event2.skill)}###摸${get.cnNumber(num)}张牌或者视为使用一张牌`, [[[num, `摸${get.cnNumber(num)}张牌`]], "tdnodes"], [list, "vcard"]]).set("filterButton", (button) => {
          const { player: player3, numx } = get.event();
          const { link } = button;
          if (!Array.isArray(link)) {
            return true;
          }
          return player3.hasUseTarget({ name: link[2], nature: link[3] });
        }).set("ai", (button) => {
          const { player: player3, numx } = get.event();
          const { link } = button;
          const val = numx > 3 ? Math.min(1.5, 1 + (numx - 3) * 0.1) : 1;
          if (Array.isArray(link)) {
            if (player3.getUseValue({ name: link[2], nature: link[3] }) > 4 * val) {
              return 1;
            }
          }
          if (typeof link == "number") {
            return 1;
          }
          return 0;
        }).set("numx", num).forResult();
        event2.result = {
          bool: result?.bool,
          cost_data: result?.links
        };
      } else {
        event2.result = await player2.chooseBool(get.prompt(event2.skill), `摸${get.cnNumber(num)}张牌`).forResult();
        if (event2.result?.bool) {
          event2.result.cost_data = [num];
        }
      }
    },
    async content(event2, trigger, player2) {
      const { cost_data: links } = event2;
      if (typeof links[0] == "number") {
        await player2.draw(links[0]);
      } else {
        const card = get.autoViewAs({ name: links[0][2], nature: links[0][3], isCard: true });
        player2.markAuto(event2.name, [card.name]);
        await player2.chooseUseTarget(card, true);
      }
    },
    marktext: "论",
    intro: { content: "已记录牌名：$" },
    onremove: true,
    ai: {
      maixie: true,
      maixie_defend: true,
      threaten: 0.7
    }
  }

tw:twxiongzheng.code:
{
    audio: 2,
    onremove: true,
    trigger: { global: "roundStart" },
    filter(event2, player2) {
      return game.hasPlayer((target) => !player2.getStorage("twxiongzheng").includes(target));
    },
    async cost(event2, trigger, player2) {
      event2.result = await player2.chooseTarget(get.prompt(event2.skill), "选择一名未选择过的角色，称为“雄争”角色", (card, player3, target) => {
        return !player3.getStorage("twxiongzheng").includes(target);
      }).set("ai", (target) => {
        var player3 = _status.event.player, att = get.attitude(player3, target);
        if (game.roundNumber <= 1 && player3.hasUnknown()) {
          return 0;
        }
        return -att;
      }).forResult();
    },
    async content(event2, trigger, player2) {
      var target = event2.targets[0];
      player2.markAuto("twxiongzheng", [target]);
      player2.storage.twxiongzheng_target = target;
      player2.addTempSkill("twxiongzheng_mark", "roundStart");
      target.addTempSkill("twxiongzheng_threaten", "roundStart");
      await game.delayx();
    },
    subSkill: {
      mark: {
        charlotte: true,
        onremove(player2, skill) {
          delete player2.storage[skill];
          delete player2.storage.twxiongzheng_target;
        },
        intro: { content: "$参与了〖雄争〗的争斗" },
        trigger: { global: "damage" },
        filter(event2, player2) {
          return event2.player == player2.storage.twxiongzheng_target && get.itemtype(event2.source) == "player";
        },
        direct: true,
        firstDo: true,
        async content(event2, trigger, player2) {
          player2.markAuto("twxiongzheng_mark", [trigger.source]);
        },
        group: "twxiongzheng_effect"
      },
      threaten: {
        charlotte: true,
        mark: true,
        intro: { content: "本轮〖雄争〗目标" },
        ai: { threaten: 10 }
      },
      effect: {
        charlotte: true,
        audio: "twxiongzheng",
        trigger: { global: "roundEnd" },
        filter(event2, player2) {
          const sha = new lib.element.VCard({ name: "sha", isCard: true });
          return game.hasPlayer((target) => player2.getStorage("twxiongzheng_mark").includes(target) || player2.canUse(sha, target, false));
        },
        async cost(event2, trigger, player2) {
          const target = player2.storage.twxiongzheng_target;
          if (!target) {
            return;
          }
          const sha = new lib.element.VCard({ name: "sha", isCard: true });
          const list = game.filterPlayer((target2) => player2.getStorage("twxiongzheng_mark").includes(target2));
          const list2 = game.filterPlayer((target2) => !list.includes(target2) && player2.canUse(sha, target2, false));
          let choiceList = [
            ["sha", `视为对任意名本轮未对${get.translation(target)}造成过伤害的角色依次使用一张【杀】`],
            ["draw", `令任意名本轮对${get.translation(target)}造成过伤害的角色摸两张牌`]
          ];
          if (list2.length) {
            choiceList[0][1] += `（${get.translation(list2)}）`;
          }
          if (list.length) {
            choiceList[1][1] += `（${get.translation(list)}）`;
          }
          const result = await player2.chooseButtonTarget({
            createDialog: ["雄争：你可以选择一项", [choiceList, "textbutton"]],
            list2,
            list,
            filterButton(button) {
              const link = button.link;
              const { list: list3, list2: list22 } = get.event();
              if (link == "sha") {
                return list22.length > 0;
              }
              return list3.length > 0;
            },
            filterTarget(card, player3, target2) {
              if (!ui.selected.buttons.length) {
                return false;
              }
              const link = ui.selected.buttons[0].link;
              const { list: list3, list2: list22 } = get.event();
              if (link == "sha") {
                return list22.includes(target2);
              }
              return list3.includes(target2);
            },
            selectTarget: [1, Infinity],
            complexSelect: true,
            ai1(button) {
              const { player: player3, list: list3, list2: list22 } = get.event();
              const link = button.link;
              const eff1 = list22.reduce((acc, target2) => {
                const eff = get.effect(target2, { name: "sha" }, player3, player3);
                if (eff > 0) {
                  return acc + eff;
                }
                return acc;
              }, 0), eff2 = list3.reduce((acc, target2) => {
                const eff = get.effect(target2, { name: "draw" }, player3, player3);
                if (eff > 0) {
                  return acc + eff;
                }
                return acc;
              }, 0);
              if (eff2 > eff1 && link == "draw") {
                return 2;
              }
              if (eff1 > 0 && link == "sha") {
                return 1;
              }
              return 0;
            },
            ai2(target2) {
              const link = ui.selected.buttons[0]?.link, player3 = get.player();
              get.attitude(player3, target2);
              if (!link) {
                return 0;
              }
              return get.effect(target2, { name: link }, player3, player3);
            }
          }).forResult();
          event2.result = {
            bool: result.bool,
            targets: result.targets,
            cost_data: result.links
          };
        },
        async content(event2, trigger, player2) {
          const goon = event2.cost_data[0] === "sha";
          const targets = event2.targets.sortBySeat();
          player2.line(targets);
          if (goon) {
            const sha = new lib.element.VCard({ name: "sha", isCard: true });
            for (const target of targets) {
              if (!target.isIn() || !player2.canUse(sha, target, false)) {
                continue;
              }
              await player2.useCard(sha, target, false);
            }
          } else {
            await game.asyncDraw(targets, 2);
            await game.delayx();
          }
        }
      }
    }
  }

tw:twluannian.code:
{
    audio: 2,
    global: "twluannian_global",
    zhuSkill: true,
    subSkill: {
      global: {
        audio: "twluannian",
        enable: "phaseUse",
        usable: 1,
        forceaudio: true,
        onChooseToUse(event2) {
          if (!game.online) {
            var num = 1;
            game.countPlayer2((current) => {
              var history = current.actionHistory;
              for (var i = history.length - 1; i >= 0; i--) {
                for (var evt of history[i].useSkill) {
                  if (evt.skill == "twluannian_global") {
                    num++;
                  }
                }
                if (history[i].isRound) {
                  break;
                }
              }
            });
            event2.set("twluannian_num", num);
          }
        },
        filter(event2, player2) {
          if (!event2.twluannian_num) {
            return false;
          }
          return player2.group == "qun" && player2.countCards("he") >= event2.twluannian_num && game.hasPlayer(function(current) {
            var target = current.storage.twxiongzheng_target;
            return target && target.isIn() && current != player2 && current.hasZhuSkill("twluannian", player2);
          });
        },
        filterCard: true,
        position: "he",
        prompt() {
          var player2 = _status.event.player;
          var num = _status.event.twluannian_num;
          var list = game.filterPlayer(function(current) {
            return current.hasZhuSkill("twluannian", player2);
          }).map((i) => i.storage.twxiongzheng_target).sortBySeat();
          return "弃置" + get.cnNumber(num) + "张牌，对" + get.translation(list) + (list.length > 1 ? "中的一人" : "") + "造成1点伤害";
        },
        selectCard() {
          return _status.event.twluannian_num;
        },
        complexSelect: true,
        complexCard: true,
        filterTarget(card, player2, target) {
          return game.filterPlayer(function(current) {
            return current.hasZhuSkill("twluannian", player2);
          }).map((i) => i.storage.twxiongzheng_target).includes(target);
