{
    audio: 2,
    enable: "phaseUse",
    filterTarget(card, player2, target) {
      return target.countCards("h") && target !== player2;
    },
    usable: 1,
    async content(event2, trigger, player2) {
      let source = event2.target;
      let cards2 = source.getCards("h", { name: "sha" });
      if (!cards2.length) {
        game.log("但", source, "没有", "#y杀", "！");
        return;
      }
      let togive = source.getNext();
      let gained;
      while (true) {
        let card = source.getCards("h", { name: "sha" }).randomGet();
        if (togive == gained) {
          break;
        }
        if (togive.isIn()) {
          await source.give(card, togive);
          gained = togive;
        }
        let num2 = togive == source ? 1 : 0;
        if (source.countCards("h", { name: "sha" }) > num2) {
          togive = togive.getNext();
        } else {
          break;
        }
      }
      source.line(togive);
      let num = togive.countCards("h", { name: "sha" });
      if (num) {
        await togive.damage(Math.min(2, num), source);
      }
    },
    ai: {
      order: 10,
      result: {
        player(player2, target) {
          var numx = target.countCards("h", { name: "sha" }), targetx = target, map = {};
          for (var i = 0; i < numx; i++) {
            targetx = targetx.getNext();
            map[targetx.playerid] ??= 0;
            map[targetx.playerid]++;
          }
          var att = get.damageEffect(targetx, player2, player2);
          return att * numx * Math.min(2, targetx.countCards("h", { name: "sha" }) + map[targetx.playerid]);
        }
      }
    }
  }

