        filterTarget: (card, player3, target) => target !== player3 && player3.canUse("sha", target, false, false),
        ai: (target) => {
          const player3 = _status.event.player;
          if (player3.hp + player3.countCards("hs", { name: ["tao", "jiu"] }) <= 1) {
            return -1;
          }
          let num = 1;
          if ((!target.mayHaveShan(player3, "use") || player3.hasSkillTag(
            "directHit_ai",
            true,
            {
              target,
              card: { name: "sha" }
            },
            true
          )) && !target.hasSkillTag("filterDamage", null, {
            player: player3,
            card: { name: "sha" }
          })) {
            num = 1.3;
          }
          return get.effect(target, { name: "sha" }, player3, player3) * num;
        }
      }).forResult();
      event2.result = {
        bool: result.bool,
        targets: result.targets,
        cost_data: addDamage
      };
    },
    async content(event2, trigger, player2) {
      const target = event2.targets[0];
      const loseHpEvent = player2.loseHp();
      let num = 1;
      if (event2.cost_data) {
        num = 2;
        game.log("#y杀", "的伤害基数+1");
      }
      const useCardEvent = player2.useCard({
        card: { name: "sha", isCard: true },
        targets: [target],
        addCount: false
      });
      useCardEvent.baseDamage = num;
      await loseHpEvent;
      await useCardEvent;
    }
  }

tw:twfupan.code:
{
    audio: 3,
    logAudio: (index) => typeof index == "number" ? `twfupan${index}.mp3` : 1,
    frequent: true,
    trigger: {
      player: "damageEnd",
      source: "damageSource"
    },
    onremove: true,
    async content(event2, trigger, player2) {
      player2.storage.twfupan ??= {};
      await player2.draw(trigger.num);
      if (!player2.countCards("he") || !game.hasPlayer((current) => {
        return !(player2.storage.twfupan[current.playerid] >= 2) && player2 != current;
      })) {
        return;
      }
      const next = player2.chooseCardTarget({
        filterCard: true,
        position: "he",
        forced: true,
        filterTarget(card, player3, target) {
          return !(player3.storage.twfupan[target.playerid] >= 2) && player3 != target;
        },
        ai1(card) {
          const player3 = get.player();
          if (get.value(card, false, "raw") < 0) {
            return 20 * get.value(card);
          }
          if (player3 == _status.currentPhase) {
            return 20 - player3.getUseValue(card);
          }
          return 20 - get.value(card);
        },
        ai2(target) {
          const player3 = get.player();
          const att = get.attitude(player3, target);
          if (ui.selected.cards.length && get.value(ui.selected.cards[0], false, "raw") < 0) {
            return -0.1 - att;
          }
          if (player3.storage.twfupan[target.playerid] === void 0) {
            return 5;
          } else if (player3.storage.twfupan[target.playerid] === 1) {
            return get.damageEffect(target, player3, player3);
          }
          return 1;
        },
        prompt: "请选择要交出的卡牌和目标角色"
      });
      next.set(
        "targetprompt2",
        next.targetprompt2.concat([
          (target) => {
            const evt = get.event();
            if (!target.isIn() || !evt.filterTarget(null, evt.player, target)) {
              return;
            }
            return !evt.player.storage.twfupan[target.playerid] ? "你摸两张牌" : "可对其<br>造成伤害";
          }
        ])
      );
      const result = await next.forResult();
      if (result?.cards?.length && result.targets?.length) {
        const {
          cards: cards2,
          targets: [target]
        } = result;
        player2.line(target, "green");
        await player2.give(cards2, target);
        if (!player2.storage.twfupan[target.playerid]) {
          player2.logSkill(event2.name, [target], null, null, [2]);
          player2.storage.twfupan[target.playerid] = 1;
          await player2.draw(2);
        } else {
          const result2 = await player2.chooseBool(`复叛：是否对${get.translation(target)}造成1点伤害？`, "然后你不能再因此技能交给其牌").set("ai", () => _status.event.bool).set("bool", get.damageEffect(target, player2, player2) > 0).forResult();
          if (result2?.bool) {
            player2.logSkill(event2.name, [target], null, null, [3]);
            player2.storage.twfupan[target.playerid]++;
            player2.line(target, "fire");
            await target.damage();
          }
        }
      }
    },
    ai: {
      maixie: true,
      maixie_hp: true,
      threaten: 0.9
    }
  }

