      for (var type of event2.player.getStorage("twjiaohua_gained")) {
        if (list.includes(type)) {
          list.remove(type);
        }
      }
      return list.length > 0;
    },
    check(event2, player2) {
      return get.attitude(player2, event2.player) > 0;
    },
    prompt2(event2, player2) {
      var cards2 = event2.cards, list = ["basic", "trick", "equip"];
      for (var card of cards2) {
        if (list.includes(get.type2(card))) {
          list.remove(get.type2(card));
        }
      }
      for (var type of event2.player.getStorage("twjiaohua_gained")) {
        if (list.includes(type)) {
          list.remove(type);
        }
      }
      var name = event2.player == player2 ? "你" : get.translation(event2.player);
      return "令" + name + "从牌堆或弃牌堆中获得一张" + (event2.player.isUnderControl(true) ? list.map((i) => get.translation(i) + "牌").join("、").replace(/(.*)、/, "$1或") : "本次未获得的类别的牌");
    },
    logTarget: "player",
    async content(event2, trigger, player2) {
      trigger.player.addTempSkill("twjiaohua_gained");
