tw:twkujian.code:
{
    audio: 3,
    enable: "phaseUse",
    filterCard: true,
    selectCard: [1, 3],
    usable: 1,
    discard: false,
    lose: false,
    delay: false,
    filterTarget: lib.filter.notMe,
    global: "twkujian_ai",
    check(card) {
      if (ui.selected.cards.length && ui.selected.cards[0].name == "du") {
        return 0;
      }
      if (!ui.selected.cards.length && card.name == "du") {
        return 20;
      }
      var player2 = get.owner(card);
      if (ui.selected.cards.length >= Math.max(2, player2.countCards("h") - player2.hp)) {
        return 0;
      }
      if (player2.hp == player2.maxHp || player2.storage.jsprende < 0 || player2.countCards("h") <= 1) {
        var players = game.filterPlayer();
        for (var i = 0; i < players.length; i++) {
          if (players[i].hasSkill("haoshi") && !players[i].isTurnedOver() && !players[i].hasJudge("lebu") && get.attitude(player2, players[i]) >= 3 && get.attitude(players[i], player2) >= 3) {
            return 11 - get.value(card);
          }
        }
        if (player2.countCards("h") > player2.hp) {
          return 10 - get.value(card);
        }
        if (player2.countCards("h") > 2) {
          return 6 - get.value(card);
        }
        return -1;
      }
      return 10 - get.value(card);
    },
    logAudio: () => 1,
    async content(event2, trigger, player2) {
      const { target, cards: cards2 } = event2;
      player2.give(cards2, target).gaintag.add("twkujianx");
      player2.addSkill("twkujian_draw");
      player2.addSkill("twkujian_discard");
    },
    ai: {
      expose: 0.2,
      order: 7,
      result: {
        target(player2, target) {
          if (target.hasSkillTag("nogain")) {
            return 0;
          }
          if (ui.selected.cards.length && ui.selected.cards[0].name == "du") {
            if (target.hasSkillTag("nodu")) {
              return 0;
            }
            return -10;
          }
          if (target.hasJudge("lebu")) {
            return 0;
          }
          var nh = target.countCards("h");
          var np = player2.countCards("h");
          if (player2.hp == player2.maxHp || player2.storage.jsprende < 0 || player2.countCards("h") <= 1) {
            if (nh >= np - 1 && np <= player2.hp && !target.hasSkill("haoshi")) {
              return 0;
            }
          }
          return Math.max(1, 5 - nh);
        }
      },
      effect: {
        target_use(card, player2, target) {
          if (player2 == target && get.type(card) == "equip") {
            if (player2.countCards("e", { subtype: get.subtype(card) })) {
              if (game.hasPlayer(function(current) {
                return current != player2 && get.attitude(player2, current) > 0;
              })) {
                return 0;
              }
            }
          }
        }
      }
    },
    subSkill: {
      draw: {
        audio: "twkujian2.mp3",
