{
    audio: 2,
    trigger: { player: "phaseZhunbeiBegin" },
    filter(event2, player2) {
      if (!player2.getEquips(1).length) {
        return false;
      }
      return game.hasPlayer((current) => player2.inRange(current) && player2.canCompare(current));
    },
    pindianCheck(player2, target) {
      const hs = player2.getCards("h").sort((a, b) => b.number - a.number);
      const ts = target.getCards("h").sort((a, b) => b.number - a.number);
      if (!hs.length || !ts.length) {
        return 0;
      }
      return Math.min(13, hs[0].number + player2.getAttackRange()) > ts[0].number || ts[0].number > 9 && get.value(ts[0]) <= 5 || target.hasCards("j");
    },
    locked: false,
    group: ["twjianwei_pindian", "twjianwei_zhaocha"],
    async cost(event2, trigger, player2) {
      event2.result = await player2.chooseTarget({
        prompt: get.prompt(event2.skill),
        prompt2: "与攻击范围内的一名角色拼点。若你赢，你获得其每个区域里的一张牌；若其赢，其获得你装备区里的武器牌",
        filterTarget: (card, player3, target) => player3.inRange(target) && player3.canCompare(target),
        ai(target) {
          if (lib.skill.twjianwei.pindianCheck(player2, target)) {
            return -5 * get.attitude(player2, target);
          }
          return -get.attitude(player2, target);
        }
      }).forResult();
    },
    async content(event2, trigger, player2) {
      const [target] = event2.targets;
      const result = await player2.chooseToCompare(target).forResult();
      if (result.bool) {
        const num = ["h", "e", "j"].filter((position) => target.hasCards(position)).length;
        if (num) {
          await player2.gainPlayerCard({
            target,
            selectButton: num,
            position: "hej",
            forced: true,
            filterButton: (button) => {
              return ui.selected.buttons.every((selected) => get.position(button.link) !== get.position(selected.link));
            }
          });
        }
      } else if (!result.tie) {
        const cards2 = player2.getEquips(1);
        if (cards2.length) {
          await target.gain({
            cards: cards2,
            source: player2,
            animate: "give"
          });
        }
      }
    },
    mod: {
      aiValue(player2, card, num) {
        if (card.name === "qinggang" || card.name === "qibaodao") {
          return num / 5;
        }
      }
    },
    ai: {
      unequip: true,
      unequip_ai: true,
      skillTagFilter(player2, tag, arg) {
        if (!arg || !arg.card || arg.card.name !== "sha" || !player2.getEquip(1)) {
          return false;
        }
      }
    },
    subSkill: {
      pindian: {
        audio: "twjianwei",
        trigger: { player: "compare", target: "compare" },
        filter(event2, player2) {
          if (!player2.getEquips(1).length || player2.getAttackRange() <= 0) {
            return false;
          }
          if (event2.player === player2) {
            return !event2.iwhile;
          }
          return true;
        },
        forced: true,
        locked: false,
        async content(event2, trigger, player2) {
          const num = player2.getAttackRange();
          if (player2 === trigger.player) {
            trigger.num1 = Math.min(13, trigger.num1 + num);
          } else {
            trigger.num2 = Math.min(13, trigger.num2 + num);
          }
          game.log(player2, `的拼点牌点数+${num}`);
        }
      },
      //你是故意找茬是不是
      zhaocha: {
        trigger: { global: "phaseZhunbeiBegin" },
        filter(event2, player2) {
          if (event2.player === player2) {
            return false;
          }
          return event2.player.canCompare(player2);
        },
        direct: true,
        async content(event2, trigger, player2) {
          const choice = get.attitude(trigger.player, player2) < 0 && !lib.skill.twjianwei.pindianCheck(player2, trigger.player);
          const boolResult = await trigger.player.chooseBool({
            prompt: `剑威：是否与${get.translation(player2)}拼点？`,
            prompt2: "若你赢，你获得其装备区里的武器牌；若其赢，其获得你每个区域里的一张牌",
            choice,
            ai: () => get.event().choice
          }).forResult();
          if (!boolResult.bool) {
            return;
          }
          trigger.player.logSkill("twjianwei", player2);
          const result = await trigger.player.chooseToCompare(player2).forResult();
          if (result.tie) {
            return;
          }
          if (result.bool) {
            const cards2 = player2.getEquips(1);
            if (cards2.length) {
              await trigger.player.gain({
                cards: cards2,
                source: player2,
                animate: "give"
              });
            }
            return;
          }
          const num = ["h", "e", "j"].filter((position) => trigger.player.hasCards(position)).length;
          if (num) {
            await player2.gainPlayerCard({
              target: trigger.player,
              selectButton: num,
              position: "hej",
              forced: true,
              filterButton: (button) => {
                return ui.selected.buttons.every((selected) => get.position(button.link) !== get.position(selected.link));
              }
            });
          }
        }
      }
    }
  }

