tw:twtanfeng.code:
{
    audio: 2,
    trigger: { player: "phaseZhunbeiBegin" },
    filter(event2, player2) {
      return game.hasPlayer((current) => current !== player2 && current.hasDiscardableCards(player2, "hej"));
    },
    async cost(event2, trigger, player2) {
      event2.result = await player2.chooseTarget({
        prompt: get.prompt2(event2.skill),
        filterTarget: (card, player3, target) => target !== player3 && target.hasDiscardableCards(player3, "hej"),
        ai: (target) => {
          const player3 = _status.event.player;
          let num = 1;
          if (get.attitude(player3, target) > 0) {
            num = 3;
          } else if (!target.hasCards("he") || !target.canUse("sha", player3)) {
            if (target.hp + target.countCards("hs", { name: ["tao", "jiu"] }) <= 1) {
              num = 2;
            } else {
              num = 1.2;
            }
          }
          return get.effect(target, { name: "guohe" }, player3, player3) * num * (player3.hp <= 1 && get.attitude(player3, target) <= 0 ? 0 : 1);
        }
      }).setHiddenSkill(event2.skill).forResult();
    },
    async content(event2, trigger, player2) {
      const target = event2.targets[0];
      await player2.discardPlayerCard({ target, position: "hej", forced: true });
      const useResult = await target.chooseCardTarget({
        position: "hes",
        prompt: `选择一张牌当做【杀】对${get.translation(player2)}使用`,
        prompt2: "或点击“取消”，受到其造成的1点火焰伤害，并令其跳过本回合的一个阶段（准备阶段和结束阶段除外）",
        filterCard(card, player3) {
          return player3.canUse(get.autoViewAs({ name: "sha" }, [card]), _status.event.getParent().player, false);
        },
        filterTarget(card, player3, target2) {
          const source = _status.event.getParent().player;
          if (target2 !== source && !ui.selected.targets.includes(source)) {
            return false;
          }
          card = get.autoViewAs({ name: "sha" }, [card]);
          return lib.filter.filterTarget.apply(this, arguments);
        },
        selectTarget() {
          let card = get.card();
          const player3 = get.player();
          if (!card) {
            return;
          }
          card = get.autoViewAs({ name: "sha" }, [card]);
          const range = [1, 1];
          game.checkMod(card, player3, range, "selectTarget", player3);
          return range;
        },
        ai1(card) {
          const player3 = _status.event.player;
          const target2 = _status.event.getParent().player;
          const eff = get.effect(target2, get.autoViewAs({ name: "sha" }, [card]), player3, player3);
          const eff2 = get.damageEffect(player3, target2, player3, "fire");
          if (eff < 0 || eff2 > 0 || eff2 > eff || get.tag(card, "recover")) {
            return 0;
          }
          return (player3.hp === 1 ? 10 : 6) - get.value(card);
        },
        ai2(target2) {
          if (target2 === _status.event.getParent().player) {
            return 100;
          }
          return get.effect(target2, { name: "sha" }, _status.event.player);
        }
      }).forResult();
      if (useResult.bool) {
        const card = get.autoViewAs({ name: "sha" }, useResult.cards);
        await target.useCard({ card, cards: useResult.cards, targets: useResult.targets, addCount: false });
        return;
      }
      player2.line(target, "fire");
      await target.damage({ num: 1, nature: "fire" });
      if (!target.isIn()) {
        return;
      }
      const list = [];
      const list2 = [];
      const phaseMap = {
        phaseJudge: "判定阶段",
        phaseDraw: "摸牌阶段",
        phaseUse: "出牌阶段",
        phaseDiscard: "弃牌阶段"
      };
      for (const phase of ["phaseJudge", "phaseDraw", "phaseUse", "phaseDiscard"]) {
        if (player2.skipList.includes(phase)) {
          continue;
        }
        const phaseName = phaseMap[phase];
        list.push(phaseName);
        if (phaseName !== "判定阶段" && phaseName !== "弃牌阶段") {
          list2.push(phaseName);
        }
      }
      const attitude = get.attitude(target, player2);
      let choice;
      if (attitude > 0) {
        choice = list.includes("判定阶段") && player2.hasCards("j") ? "判定阶段" : "弃牌阶段";
      } else if (list.includes("摸牌阶段") && player2.hasJudge("lebu")) {
        choice = "摸牌阶段";
      } else if (list.includes("出牌阶段") && player2.hasJudge("bingliang") || player2.needsToDiscard() > 0) {
        choice = "出牌阶段";
      } else {
        choice = list2.randomGet();
      }
      const controlResult = await target.chooseControl({
        controls: list,
        prompt: `探锋：令${get.translation(player2)}跳过一个阶段`,
        ai: () => _status.event.choice
      }).set("choice", choice).forResult();
      for (const phase in phaseMap) {
        if (phaseMap[phase] === controlResult.control) {
          player2.skip(phase);
        }
      }
      target.popup(controlResult.control);
      target.line(player2);
      game.log(player2, "跳过了", `#y${controlResult.control}`);
    }
  }

