tw:twgongge.code:
{
    audio: 3,
    trigger: { player: "useCardToPlayered" },
    filter(event2, player2) {
      if (!event2.isFirstTarget || !event2.targets) {
        return false;
      }
      return get.tag(event2.card, "damage");
    },
    usable: 1,
    async cost(event2, trigger, player2) {
      event2.result = await player2.chooseTarget(get.prompt2(event2.name.slice(0, -5)), (card, player3, target) => {
        const trigger2 = _status.event.getTrigger();
        return trigger2.targets.includes(target);
      }).set("ai", (target) => {
        var player3 = _status.event.player;
        var trigger2 = _status.event.getTrigger();
        get.attitude(player3, target);
        var damageNum = trigger2.getParent().baseDamage;
        var map = trigger2.getParent().customArgs, id = target.playerid;
        if (map[id]) {
          if (typeof map[id].baseDamage == "number") {
            damageNum = map[id].baseDamage;
          }
          if (typeof map[id].extraDamage == "number") {
            damageNum += map[id].extraDamage;
          }
        }
        if (target.hasSkillTag("filterDamage", null, {
          player: trigger2.player,
          card: trigger2.card
        })) {
          damageNum = 1;
        }
        var num = target.getSkills(null, false, false).filter(function(skill) {
          var info = get.info(skill);
          return info && !info.charlotte;
        }).length + 1;
        var list = [0, 0, 0];
        var player3 = _status.event.player;
        list[0] = num;
        list[1] = get.effect(target, { name: "guohe_copy2" }, player3, player3) > 0 ? target.hp - damageNum < player3.hp ? num : num - Math.min(player3.getCards("he"), num - 1) : 0;
        if (_status.event.yimie(trigger2, player3, target, damageNum)) {
          list[2] = (get.recoverEffect(target, player3, player3) > get.damageEffect(target, player3, player3) ? Math.min(num - 1, target.getDamagedHp()) : num - 1) * 2;
        }
        return Math.max.apply(Math, list);
      }).set("yimie", (trigger2, player3, target, damageNum) => {
        var hit = true;
        var att = get.attitude(player3, target);
        if (get.type(trigger2.card) == "trick" && trigger2.player.countCards("hs", { name: "wuxie" })) {
          hit = false;
        }
        if (trigger2.card.name == "huogong" && trigger2.player.countCards("h", (card) => {
          var list = [];
          for (var i of player3.getCards("h")) {
            list.push(get.suit(i));
          }
          return !list.includes(get.suit(card));
        })) {
          hit = false;
        }
        var key;
        switch (trigger2.card.name) {
          case "sha":
          case "wanjian":
            key = ["shan"];
            break;
          case "juedou":
          case "nanman":
          case "jiedao":
            key = ["sha"];
            break;
          default:
            key = [];
            break;
        }
        if (get.type(trigger2.card) == "trick") {
          key.push("wuxie");
        }
        key.push("caochuan");
        get.recoverEffect(target, player3, player3) > 0 ? 1 : -1;
        att > 0 && !hit || target.countCards("hs", { name: key }) && !trigger2.getParent().directHit.includes(target) ? 1 : -1;
        if (att <= 0 && target.hp - damageNum > 0) {
          return false;
        }
        return att != 0;
      }).forResult();
    },
    async content(event2, trigger, player2) {
      const {
        targets: [target]
      } = event2;
      const num = target.getSkills(null, false, false).filter((skill) => {
        const info = get.info(skill);
        return info && !info.charlotte;
      }).length + 1;
      event2.num = num;
      const list = [];
      const choiceList = [`摸${get.cnNumber(num)}张牌，若${get.translation(target)}响应此牌，则你跳过下个摸牌阶段`, `弃置${get.translation(target)}${get.cnNumber(num)}张牌，此牌结算完毕后，若${get.translation(target)}的体力值不小于你，你交给其${get.cnNumber(num - 1)}张牌`, `令此牌对${get.translation(target)}造成的伤害+${num - 1}，此伤害结算完成后，其回复等量的体力值`];
      list.push("摸牌");
      if (target.countDiscardableCards(player2, "he")) {
        list.push("拆牌");
      } else {
        choiceList[1] = '<span style="opacity:0.5">' + choiceList[1] + "</span>";
      }
      list.push("加伤");
      const { control } = await player2.chooseControl(list).set("prompt", "攻阁：请选择一项（" + get.translation(target) + "对应X值：" + (num - 1) + "）").set("ai", () => _status.event.choice).set(
        "choice",
        (function() {
          var att = get.attitude(player2, target);
          var damageNum = trigger.getParent().baseDamage;
          var map = trigger.getParent().customArgs, id = target.playerid;
          if (map[id]) {
            if (typeof map[id].baseDamage == "number") {
              damageNum = map[id].baseDamage;
            }
            if (typeof map[id].extraDamage == "number") {
              damageNum += map[id].extraDamage;
            }
          }
          if (target.hasSkillTag("filterDamage", null, {
            player: trigger.player,
            card: trigger.card
          })) {
            damageNum = 1;
          }
          var yimie = function() {
            if (damageNum == 1) {
              return false;
            }
            var hit = true;
            if (get.type(trigger.card) == "trick" && trigger.player.countCards("hs", { name: "wuxie" })) {
              hit = false;
            }
            if (trigger.card.name == "huogong" && trigger.player.countCards("h", function(card) {
              var list2 = [];
              for (var i of player2.getCards("h")) {
                list2.push(get.suit(i));
              }
              return !list2.includes(get.suit(card));
            })) {
              hit = false;
            }
            var key;
            switch (trigger.card.name) {
              case "sha":
              case "wanjian":
                key = ["shan"];
                break;
              case "juedou":
              case "nanman":
              case "jiedao":
                key = ["sha"];
                break;
              default:
                key = [];
                break;
            }
            key.push("caochuan");
            get.recoverEffect(target, player2, player2) > 0 ? 1 : -1;
            att > 0 && !hit || target.countCards("hs", { name: key }) && !trigger.getParent().directHit.includes(target) ? 1 : -1;
            if (att <= 0 && target.hp - damageNum > 0) {
              return false;
            }
            return att != 0;
          };
          if (yimie()) {
            return "加伤";
          }
          if (list.includes("拆牌") && get.effect(target, { name: "guohe_copy2" }, player2, player2) > 0 && target.hp - damageNum < player2.hp) {
            return "拆牌";
          }
          return "摸牌";
        })()
      ).set("choiceList", choiceList).forResult();
      game.log(player2, "选择了", "#y" + control);
      switch (control) {
        case "摸牌": {
