tw:twtuidao.code:
{
    audio: 2,
    trigger: { player: "phaseZhunbeiBegin" },
    filter(event2, player2) {
      const targets = player2.getStorage("twsuizheng");
      if (!targets.length) {
        return false;
      }
      return targets.some((target) => target.hp <= 2 || !target.isIn());
    },
    check(event2, player2) {
      const targets = player2.getStorage("twsuizheng");
      let val = 0;
      for (const target of targets) {
        if (target.hp <= 2 && target.isIn()) {
          val -= get.attitude(player2, target);
        } else if (!target.isIn()) {
          val += 6;
        }
      }
      return val > 0;
    },
    limited: true,
    skillAnimation: true,
    animationColor: "thunder",
    async content(event2, trigger, player2) {
      player2.awakenSkill(event2.name);
      const list1 = ["equip3", "equip4"].map((i) => get.translation(i));
      const list2 = ["basic", "trick", "equip"].map((i) => get.translation(i));
      const currentTargets = player2.getStorage("twsuizheng");
      const translatedTargets = get.translation(currentTargets);
      const targetText = currentTargets.length ? `与${translatedTargets}` : translatedTargets;
      const buttonResult = await player2.chooseButton({
        selectButton: 2,
        forced: true,
        createDialog: [`颓盗：废除你${targetText}的一个坐骑栏废除并选择一个类别`, "坐骑栏", [list1, "tdnodes"], "类别", [list2, "tdnodes"]],
        filterButton: (button) => {
          const list = _status.event.list;
          const link = button.link;
          if (ui.selected.buttons.length) {
            const selectedLink = ui.selected.buttons[0].link;
            if (list.includes(selectedLink) === list.includes(link)) {
              return false;
            }
          }
          return true;
        },
        ai: (button) => {
          const currentPlayer = _status.event.player;
          const list = _status.event.list;
          const link = button.link;
          if (list.includes(link)) {
            if (currentPlayer.hasDisabledSlot(4)) {
              return "攻击马";
            }
            if (currentPlayer.hasDisabledSlot(3)) {
              return "防御马";
            }
            return "攻击马";
          }
          const targets2 = currentPlayer.getStorage("twsuizheng");
          for (const target2 of targets2) {
            if (!target2.isIn()) {
              continue;
            }
            const counts = [0, 0, 0];
            const types = ["basic", "trick", "equip"].map((i) => get.translation(i));
            for (const card of target2.getCards("he")) {
              counts[types.indexOf(get.translation(get.type2(card)))]++;
            }
            return types[counts.indexOf(Math.max(...counts))];
          }
          return 1 + Math.random();
        }
      }).set("list", list1).forResult();
      if (!buttonResult.links[0].includes("马")) {
        buttonResult.links.reverse();
      }
      const subtype = buttonResult.links[0] === "防御马" ? "equip3" : "equip4";
      const type = { 基本: "basic", 锦囊: "trick", 装备: "equip" }[buttonResult.links[1]];
      await player2.disableEquip({ slots: [subtype] });
      const targets = player2.getStorage("twsuizheng");
      for (const target2 of targets) {
        if (target2?.isIn()) {
          await target2.disableEquip({ slots: [subtype] });
          const cards3 = target2.getCards("he", (card) => get.type2(card) === type);
          event2.gainners = cards3;
          await player2.gain({ cards: cards3, source: target2, animate: "give" });
          continue;
        }
        const cards2 = [];
        for (let i = 0; i < 2; i++) {
          const card = get.cardPile2((card2) => !cards2.includes(card2) && get.type2(card2) === type);
          if (!card) {
            break;
          }
          cards2.push(card);
        }
        event2.gainners = cards2;
        await player2.gain({ cards: cards2, animate: "gain2" });
      }
      const targetResult = await player2.chooseTarget({
        prompt: "请重新选择【随征】目标",
        forced: true,
        filterTarget: (_card, player3, target2) => !player3.getStorage("twsuizheng").includes(target2),
        ai: (target2) => {
          const player3 = _status.event.player;
          return Math.max(1 + get.attitude(player3, target2) * get.threaten(target2), Math.random());
        }
      }).forResult();
      if (!targetResult.bool) {
        return;
      }
      const target = targetResult.targets[0];
      player2.line(target);
      game.log(player2, "选择了", target, "作为", "“随征”角色");
      delete player2.storage.twsuizheng;
      player2.markAuto("twsuizheng", [target]);
    },
    ai: { combo: "twsuizheng" }
  }

