        player3.logSkill("twyulong");
        if (bool) {
          if (trigger2.addCount !== false) {
            trigger2.addCount = false;
            const stat = player3.getStat("card"), name = trigger2.card.name;
            if (typeof stat[name] == "number" && stat[name] > 0) {
