tw:twzhenhu.code:
{
    audio: 2,
    trigger: { player: "useCardToPlayer" },
    filter(event2, player2) {
      if (!event2.isFirstTarget || !get.is.damageCard(event2.card)) {
        return false;
      }
      return !player2.hasSkillTag("noCompareSource") && game.hasPlayer((target) => player2.canCompare(target, true));
    },
    direct: true,
    async content(event2, trigger, player2) {
      const result = await player2.chooseTarget({
        prompt: get.prompt2("twzhenhu"),
        selectTarget: [1, 3],
        filterTarget: (_card, player3, target) => player3.canCompare(target, true),
        ai: (target) => {
          const player3 = _status.event.player;
          const targets2 = _status.event.getTrigger().targets;
          let num = 0;
          if (player3.hasSkill("twlvren")) {
            num += 2 * (ui.selected.targets.length + 1);
          }
          if (player3.hasSkill("twchuanshu_effect")) {
            num += 3;
          }
          const hs = player3.getCards("h").sort((a, b) => get.number(b) - get.number(a));
          if (!hs.length) {
            return -1;
          }
          const ts = target.getCards("h").sort((a, b) => get.number(b) - get.number(a));
          if (Math.min(13, get.number(hs[0]) + num) <= get.number(ts[0])) {
            return -1;
          }
          return get.effect(target, { name: "guohe_copy2" }, player3, player3) / 2 + (targets2.includes(target) ? get.damageEffect(target, player3, player3) : 0);
        }
      }).forResult();
      if (!result.bool) {
        return;
      }
      const targets = result.targets.sortBySeat();
      event2.targets = targets;
      player2.logSkill("twzhenhu", targets);
      await player2.draw();
      const compareResult = await player2.chooseToCompare(targets, (card) => get.number(card)).setContent("chooseToCompareMeanwhile").forResult();
      if (compareResult.winner === player2) {
        targets.remove(compareResult.winner);
        player2.line(targets, trigger.card.nature);
        player2.addTempSkill("twzhenhu_add");
        if (!trigger.card.storage) {
          trigger.card.storage = {};
        }
        trigger.card.storage.twzhenhu = targets;
        return;
      }
      await player2.loseHp();
    },
    subSkill: {
      add: {
        charlotte: true,
        onremove: true,
        forced: true,
        popup: false,
        trigger: { global: "damageBegin1" },
        filter(event2, player2) {
          if (!event2.card || !event2.card.storage) {
            return false;
          }
          const targets = event2.card.storage.twzhenhu;
          return targets && targets.includes(event2.player);
        },
        async content(event2, trigger, player2) {
          trigger.num++;
        }
      }
    }
  }

