        })) {
          switch (button.link[2]) {
            case "shan":
              return 5;
            case "sha":
              if (button.link[3] == "fire") {
                return 2.95;
              } else if (button.link[3] == "thunder" || button.link[3] == "ice") {
                return 2.92;
              } else {
                return 2.9;
              }
