          cardEnabled(card, player2) {
            const suits = [];
            game.countPlayer((current) => {
              const list = current.getStorage("twgongsun_shadow");
              if (!list?.length) {
                return false;
              }
              list.forEach((info) => {
                if (info[0] == player2 || current == player2) {
                  suits.add(info[1]);
                }
              });
            });
            const hs = player2.getCards("h", (card2) => suits.includes(get.suit(card2, player2))), cards2 = [card];
