tw:twmouli.code:
{
    audio: "mouli",
    enable: "chooseToUse",
    filter(event2, player2) {
      if (event2.type == "wuxie") {
        return false;
      }
      if (player2.hasSkill("twmouli_used")) {
        return false;
      }
      if (!Array.isArray(event2.twmouli)) {
        return false;
      }
      for (var card of event2.twmouli) {
        if (event2.filterCard(card, player2, event2)) {
          return true;
        }
      }
      return false;
    },
    onChooseToUse(event2) {
      if (game.online || !event2.player.hasSkill("twmouli")) {
        return;
      }
      var cards2 = [];
      for (var i = 0; i < ui.cardPile.childNodes.length; i++) {
        var card = ui.cardPile.childNodes[i];
        if (get.type(card, null, false) == "basic") {
          cards2.push(card);
        }
      }
      event2.set("twmouli", cards2);
    },
    chooseButton: {
      dialog(event2, player2) {
        var dialog = ui.create.dialog("谋立", "hidden");
        if (event2.twmouli && event2.twmouli.length) {
          dialog.add(event2.twmouli);
        } else {
          dialog.addText("牌堆里没有基本牌");
        }
        return dialog;
      },
      filter(button, player2) {
        var evt = _status.event.getParent(), card = button.link;
        if (evt && evt.filterCard) {
          return evt.filterCard(card, player2, evt);
        }
        return false;
      },
      check(button) {
        var player2 = _status.event.player, card = button.link;
        if (_status.event.type != "phase") {
          return 1;
        }
        if (_status.event.dying) {
          return get.attitude(player2, _status.event.dying);
        }
        if (card.name == "jiu") {
          return player2.getUseValue(card);
        }
        return player2.getUseValue(card) / 4;
      },
      backup(links, player2) {
        return {
          audio: "mouli",
          filterCard: () => false,
          selectCard: -1,
          viewAs: { name: links[0].name, isCard: true, cards: [links[0]] },
          popname: true,
          log: false,
          async precontent(event2, trigger, player3) {
            player3.logSkill("twmouli");
            player3.addTempSkill("twmouli_used");
            var name = event2.result.card.name;
            event2.result.cards = event2.result.card.cards;
            event2.result.card = get.autoViewAs(event2.result.cards[0]);
            event2.result.card.name = name;
            var next = game.createEvent("twmouli_update");
            event2.next.remove(next);
            event2.getParent().after.push(next);
            next.setContent(function() {
              game.updateRoundNumber();
            });
          }
        };
      },
