    trigger: { player: "equipEnd" },
    frequent: true,
    async content(event2, trigger, player2) {
      const card = get.cardPile((card2) => get.type2(card2) === "trick");
      if (card) {
        await player2.gain({
          cards: [card],
          animate: "gain2",
          gaintag: ["twqirang"]
        });
        player2.addTempSkill("twqirang_use");
        player2.addTempSkill("twqirang_clear", ["phaseZhunbeiAfter", "phaseDrawAfter", "phaseUseAfter", "phaseDiscardAfter", "phaseJieshuAfter", "phaseAfter"]);
      }
    },
    ai: {
      effect: {
        target(card, player2, target, current) {
          if (get.type(card) === "equip" && !get.cardtag(card, "gifts")) {
            return [1, 3];
          }
        }
      }
    },
    subSkill: {
      clear: {
        charlotte: true,
        onremove(player2) {
          player2.removeGaintag("twqirang");
        }
      },
      use: {
        audio: "qirang",
        trigger: { player: "useCard2" },
        forced: true,
        filter(event2, player2) {
          if (get.type2(event2.card) !== "trick") {
            return false;
          }
          return player2.hasHistory("lose", (evt) => {
            if ((evt.relatedEvent || evt.getParent()) !== event2) {
              return false;
            }
            return Object.values(evt.gaintag_map).some((gaintags) => gaintags.includes("twqirang"));
          });
        },
        async content(event2, trigger, player2) {
          game.log(trigger.card, "不可被响应");
          trigger.directHit.addArray(game.players);
          const info = get.info(trigger.card);
          if (info.allowMultiple === false || !trigger.targets) {
            return;
          }
          if (!info.multitarget && !game.hasPlayer((current) => !trigger.targets.includes(current) && lib.filter.targetEnabled2(trigger.card, player2, current))) {
            return;
          }
          const targetResult = await player2.chooseTarget({
            prompt: get.prompt("twqirang"),
            prompt2: `为${get.translation(trigger.card)}增加或减少一个目标`,
            filterTarget: (card, player3, target) => {
              if (trigger.targets.includes(target)) {
                return true;
              }
              return lib.filter.targetEnabled2(trigger.card, player3, target);
            },
            ai: (target) => get.effect(target, trigger.card, player2, player2) * (trigger.targets.includes(target) ? -1 : 1)
          }).forResult();
          if (!targetResult.bool) {
            return;
          }
          if (!event2.isMine() && !event2.isOnline()) {
            await game.delayx();
          }
          event2.targets = targetResult.targets;
          player2.line(event2.targets);
          if (trigger.targets.includes(event2.targets[0])) {
            trigger.targets.removeArray(event2.targets);
          } else {
            trigger.targets.addArray(event2.targets);
          }
        },
        mod: {
          targetInRange(card, player2, target) {
            if (!card.cards) {
              return;
            }
            for (const i of card.cards) {
              if (i.hasGaintag("twqirang")) {
                return true;
              }
            }
          }
        }
      }
    }
  }

