tw:twxingluan.code:
{
    audio: "xinfu_xingluan",
    trigger: { player: "phaseJieshuBegin" },
    frequent: true,
    async content(event2, trigger, player2) {
      const cards2 = game.cardsGotoOrdering(get.cards(6)).cards;
      const videoId = lib.status.videoId++;
      game.broadcastAll(
        (player3, id, cards3) => {
          const str = player3 === game.me && !_status.auto ? "兴乱：选择分配一种类别的牌" : "兴乱";
          const dialog = ui.create.dialog(str, cards3);
          dialog.videoId = id;
        },
        player2,
        videoId,
        cards2
      );
      const startTime = get.utc();
      game.addVideo("showCards", player2, ["兴乱", get.cardsInfo(cards2)]);
      game.addVideo("delay", null, 2);
      const typeList = ["basic", "trick", "equip"].filter((type) => cards2.some((card) => get.type2(card) === type));
      const friendlyPlayers = game.filterPlayer((i) => get.attitude(_status.event.player, i) > 0).sort((a, b) => {
        if (a === player2) {
          if (a.hp < b.hp) {
            return 1;
          }
          return -1;
        }
        if (b === player2) {
          if (b.hp < a.hp) {
            return -1;
          }
          return 1;
        }
        return b.hp - a.hp;
      });
      const enemyPlayers = game.filterPlayer((i) => get.attitude(_status.event.player, i) < 0).sort((a, b) => a.hp - b.hp);
      const types = typeList.map((type) => {
        let num2 = 0;
        for (const card of cards2) {
          if (get.type2(card) === type) {
            num2++;
          }
        }
        return [type, num2];
      }).sort((a, b) => b[1] - a[1]);
      const tempCache = {
        max: -Infinity,
        tars: []
      };
      for (const [typeName, typeCount] of types) {
        let friendlyScore;
        let targets = [];
        if (enemyPlayers.length * 3 >= typeCount) {
          let enemyScore = -typeCount;
          for (let index = 0; index < enemyPlayers.length && index < typeCount; index++) {
            enemyScore += 10 / (2 + enemyPlayers[index].hp);
            targets.push(enemyPlayers[index]);
          }
          if (enemyScore > tempCache.max) {
            tempCache.type = typeName;
            tempCache.max = enemyScore;
            tempCache.tars = targets.slice(0);
            delete tempCache.more;
          }
        }
        if (friendlyPlayers.length * 3 >= typeCount) {
          targets = [];
          friendlyScore = typeCount - 10 / (2 + friendlyPlayers[0].hp);
          let remaining = typeCount - Math.max(3, typeCount);
          if (remaining) {
            if (friendlyPlayers.length < 3) {
              targets.push(friendlyPlayers[1]);
              if (remaining >= 3) {
                friendlyScore -= 10 / (2 + friendlyPlayers[1].hp);
              }
            } else {
              if (player2 !== friendlyPlayers[0]) {
                targets.push(player2);
                remaining -= Math.max(2, remaining);
              }
              if (remaining) {
                targets.addArray(
                  friendlyPlayers.filter((current) => friendlyPlayers[0] !== current && player2 !== current).sort((a, b) => get.attitude(_status.event.player, b) - get.attitude(_status.event.player, a)).slice(remaining < 3 ? -1 : -2)
                );
              }
            }
          }
          if (friendlyScore > tempCache.max) {
            tempCache.type = typeName;
            tempCache.max = friendlyScore;
            tempCache.more = friendlyPlayers[0];
            tempCache.tars = targets.slice(0);
          }
        }
      }
      const controlResult = await player2.chooseControl({
        controls: typeList,
        ai: (event3) => event3.type
      }).set("type", tempCache.type).forResult();
      game.broadcastAll("closeDialog", videoId);
      const cardsToGive = cards2.filter((card) => controlResult.control === get.type2(card));
      const time = 1e3 - (get.utc() - startTime);
      if (time > 0) {
        await game.delay(0, time);
      }
      player2.$gain2(cardsToGive, false);
      await game.delayx();
      if (_status.connectMode) {
        game.broadcastAll(() => {
          _status.noclearcountdown = true;
        });
      }
      const givenMap = {};
      let num = 0;
      while (cardsToGive.length) {
        let cardResult;
        if (cardsToGive.length === 1) {
          cardResult = { links: cardsToGive.slice(0), bool: true };
        } else {
          cardResult = await player2.chooseCardButton({
            prompt: "兴乱：请选择要分配的牌",
            forced: true,
            cards: cardsToGive,
            select: [1, Math.min(3, cardsToGive.length)],
            ai: (button) => ui.selected.buttons.length === 0 ? get.buttonValue(button) : 0
          }).forResult();
        }
        if (!cardResult.bool) {
          continue;
        }
        const selectedCards = cardResult.links;
        const targetResult = await player2.chooseTarget({
          prompt: `选择获得${get.translation(selectedCards)}的角色`,
          forced: cardsToGive.length === 1,
          filterTarget: (card, player3, target) => (givenMap[target.playerid] || []).length + selectedCards.length <= 3,
          ai: (target) => {
            const targets = _status.event.targets;
            const attitude = get.attitude(_status.event.player, target);
            if (!targets.length) {
              return attitude * _status.event.value;
            }
            return targets.includes(target) ? Math.max(1, attitude * _status.event.value) : 0;
          }
        }).set(
          "value",
          selectedCards.reduce((sum, card) => sum + get.value(card, player2, "raw"), 0)
        ).set("more", tempCache.more).set(
          "targets",
          (() => {
            const unusedTargets = [];
            const usedTargets = [];
            if (tempCache.more && (givenMap[tempCache.more.playerid] || []).length + selectedCards.length <= 3) {
              return [tempCache.more];
            }
            for (const current of tempCache.tars) {
              const givenCount = (givenMap[current.playerid] || []).length;
              if (givenCount + selectedCards.length > 3) {
                continue;
              }
              if (givenCount) {
                usedTargets.push(current);
              } else {
                unusedTargets.push(current);
              }
            }
            return unusedTargets.length ? unusedTargets : usedTargets;
          })()
        ).forResult();
        if (!targetResult.bool) {
          continue;
        }
        cardsToGive.removeArray(selectedCards);
        if (targetResult.targets.length) {
          const id = targetResult.targets[0].playerid;
          if (!givenMap[id]) {
            givenMap[id] = [];
          }
          givenMap[id].addArray(selectedCards);
        }
      }
      if (_status.connectMode) {
        game.broadcastAll(() => {
          delete _status.noclearcountdown;
          game.stopCountChoose();
        });
      }
      const gainList = [];
      for (const [id, givenCards] of Object.entries(givenMap)) {
        const source = (_status.connectMode ? lib.playerOL : game.playerMap)[id];
        if (player2 === source) {
          num += givenCards.length;
        }
        player2.line(source, "green");
        game.log(source, "获得了", givenCards);
        gainList.push([source, givenCards]);
      }
      await game.loseAsync({
        gain_list: gainList,
        giver: player2,
        animate: "gain2"
      }).setContent("gaincardMultiple");
      const loseHpList = [];
      for (const [id, givenCards] of Object.entries(givenMap)) {
        const source = (_status.connectMode ? lib.playerOL : game.playerMap)[id];
        if (givenCards.length >= num) {
          loseHpList.push(source);
        }
      }
      loseHpList.sortBySeat();
      player2.line(loseHpList);
      for (const target of loseHpList) {
        await target.loseHp();
      }
    }
  }

