tw:twejian.code:
{
    audio: "ejian",
    trigger: {
      global: ["gainAfter", "loseAsyncAfter"]
    },
    filter(event2, player2) {
      if (event2.name === "gain") {
        const cards3 = event2.getg(event2.player);
        if (!cards3.length) {
          return false;
        }
        const lostCards = event2.getl(player2).cards2;
        for (const card of lostCards) {
          if (cards3.includes(card) && event2.player.hasCards("he", (current) => current !== card && get.type2(current) === get.type2(card))) {
            return true;
          }
        }
        return false;
      }
      if (event2.type !== "gain") {
        return false;
      }
      const cards2 = event2.getl(player2).cards2;
      if (!cards2.length) {
        return false;
      }
      return game.hasPlayer((current) => {
        if (current === player2) {
          return false;
        }
        const gainedCards = event2.getg(current);
        for (const card of gainedCards) {
          if (cards2.includes(card) && current.hasCards("he", (currentCard) => currentCard !== card && get.type2(currentCard) === get.type2(card))) {
            return true;
          }
        }
        return false;
      });
    },
    logTarget(event2, player2) {
      if (event2.name === "gain") {
        return event2.player;
      }
      const cards2 = event2.getl(player2).cards2;
      return game.filterPlayer((current) => {
        if (current === player2) {
          return false;
        }
        const gainedCards = event2.getg(current);
        for (const card of gainedCards) {
          if (cards2.includes(card) && current.hasCards("he", (currentCard) => currentCard !== card && get.type2(currentCard) === get.type2(card))) {
            return true;
          }
        }
        return false;
      });
    },
    direct: true,
    async content(event2, trigger, player2) {
      let targets;
      if (trigger.name === "gain") {
        targets = [trigger.player];
      } else {
        const cards2 = trigger.getl(player2).cards2;
        targets = game.filterPlayer((current) => {
          if (current === player2) {
            return false;
          }
          const gainedCards = trigger.getg(current);
          for (const card of gainedCards) {
            if (cards2.includes(card) && current.hasCards("he", (currentCard) => currentCard !== card && get.type2(currentCard) === get.type2(card))) {
              return true;
            }
          }
          return false;
        });
      }
      for (const target of targets) {
        const activate = await player2.chooseBool({
          prompt: get.prompt("twejian", target),
          prompt2: "当其他角色得到你的牌后，若其有其他与此牌类型相同的牌，你可以令其选择一项：1.受到你造成的1点伤害；2.弃置这些牌",
          ai: () => get.attitude(player2, target) < 0
        }).forResult();
        if (!activate?.bool) {
          continue;
        }
        player2.logSkill("twejian", target);
        const gainedCards = trigger.getg(target);
        const cardTypes = [];
        for (const card of gainedCards) {
          cardTypes.add(get.type(card, "trick", target));
        }
        const controlResult = await target.chooseControl({
          controls: ["选项一", "选项二"],
          prompt: "恶荐：请选择一项",
          choiceList: ["受到1点伤害", `弃置所有除${get.translation(gainedCards)}外的${get.translation(cardTypes)}牌`],
          ai: () => {
            const player3 = _status.event.player;
            const types = _status.event.cardTypes;
            const cards3 = player3.getCards("he", (card) => types.includes(get.type2(card)));
            if (cards3.length === 1) {
              return "选项二";
            }
            if (cards3.length >= 2) {
              for (const card of cards3) {
                if (get.tag(card, "save")) {
                  return "选项一";
                }
              }
            }
            if (player3.hp === 1) {
              return "选项二";
            }
            for (const card of cards3) {
              if (get.value(card) >= 8) {
                return "选项一";
              }
            }
            if (cards3.length > 2 && player3.hp > 2) {
              return "选项一";
            }
            if (cards3.length > 3) {
              return "选项一";
            }
            return "选项二";
          }
        }).set("cardTypes", cardTypes).forResult();
        if (controlResult.control === "选项一") {
          await target.damage();
          continue;
        }
        const cards2 = target.getCards("he", (card) => cardTypes.includes(get.type2(card)) && !gainedCards.includes(card));
        await target.discard({ cards: cards2 });
      }
    },
    ai: {
      expose: 0.3
    }
  }

