tw:twjiexun.code:
{
    intro: { content: "已发动#次" },
    audio: "jiexun",
    trigger: { player: "phaseJieshuBegin" },
    onremove: true,
    derivation: ["twfunanx", "twjiexunx"],
    async cost(event2, trigger, player2) {
      const suits = {};
      for (const current of game.filterPlayer()) {
        for (const card of current.iterableGetCards("ej")) {
          if (typeof suits[get.suit(card)] !== "number") {
            suits[get.suit(card)] = 0;
          }
          suits[get.suit(card)]++;
        }
      }
      const choices = lib.suit.slice();
      choices.push("cancel2");
      const suitDescription = lib.suit.map((suit2) => `${get.translation(suit2)}：${get.cnNumber(suits[suit2] || 0)}张`).join("；");
      const controlResult = await player2.chooseControl({
        controls: choices,
        prompt: `${get.prompt(event2.skill)}（已发动过${get.cnNumber(player2.countMark("twjiexun"))}次）`,
        prompt2: `${get.skillInfoTranslation("twjiexun", player2, false)}<br>${suitDescription}`,
        ai: (event3, player3) => {
          const map = {};
          for (const current of game.filterPlayer()) {
            for (const card of current.iterableGetCards("ej")) {
              if (typeof map[get.suit(card)] !== "number") {
                map[get.suit(card)] = 0;
              }
              map[get.suit(card)]++;
            }
          }
          for (const suit2 of Object.keys(map)) {
            map[suit2] = Math.abs(map[suit2]);
          }
          const hasFriend = game.hasPlayer((current) => get.attitude(player3, current) > 0 && player3 !== current);
          const sortedSuits = lib.suit.slice().sort((a, b) => (hasFriend ? 1 : -1) * ((map[b] || 0) - (map[a] || 0)));
          if (hasFriend && map[sortedSuits[0]] > 0 || !hasFriend || player3.hasMark("twjiexun")) {
            return sortedSuits[0];
          }
          return "cancel2";
        }
      }).forResult();
      if (controlResult.control === "cancel2") {
        event2.result = { bool: false };
        return;
      }
      const suit = controlResult.control;
      const drawCount = game.countPlayer((current) => current.countCards("ej", { suit }));
      const discardCount = player2.countMark("twjiexun");
      let targetPrompt = `令一名其他角色摸${get.cnNumber(drawCount)}张牌`;
      if (discardCount) {
        targetPrompt += `，然后弃置${get.cnNumber(discardCount)}张牌`;
      }
      const effect = drawCount >= discardCount && drawCount > 0 ? 1 : -1;
      const targetResult = await player2.chooseTarget({
        prompt: "请选择【诫训】的目标",
        prompt2: targetPrompt,
        filterTarget: lib.filter.notMe,
        ai: (target) => {
          const attitude = get.attitude(player2, target);
          return effect * get.sgn(attitude) + attitude / 114514;
        }
      }).forResult();
      event2.result = {
        bool: targetResult.bool,
        targets: targetResult.targets,
        cost_data: { suit, drawCount, discardCount }
      };
    },
    async content(event2, trigger, player2) {
      const target = event2.targets[0];
      const { suit, drawCount, discardCount } = event2.cost_data;
      if (player2.hasMark("twjiexun") || drawCount) {
        player2.addExpose(0.2);
      }
      player2.popup(suit);
      game.log(player2, "选择了", `#y${get.translation(suit)}`);
      player2.addMark("twjiexun", 1, false);
      if (drawCount) {
        await target.draw(drawCount);
      }
      if (!discardCount) {
        return;
      }
      const discardResult = await target.chooseToDiscard({
        selectCard: discardCount,
        forced: true,
        position: "he"
      }).forResult();
      if (!(discardResult?.cards?.length > 0 && discardResult.autochoose && discardResult.cards.length === discardResult.rawcards?.length) || player2.hasSkill("funan_jiexun")) {
        return;
      }
      const optionResult = await player2.chooseControl({
        choiceList: [`摸${get.cnNumber(discardCount)}张牌，将【诫训】的发动次数归零`, "修改【复难】和【诫训】"],
        ai: (event3) => event3.choice,
        prompt: "诫训：选择一项",
        choice: discardCount >= 4 ? 0 : discardCount <= 1 ? 1 : [0, 1].randomGet()
      }).forResult();
      if (optionResult.index === 0) {
        const drawEvent = player2.draw(discardCount);
        player2.removeMark("twjiexun", player2.countMark("twjiexun"), false);
        game.log(player2, "归零了", "#g【诫训】", "的发动次数");
        await drawEvent;
      } else {
        game.log(player2, "修改了", "#g【复难】", "和", "#g【诫训】");
        player2.addSkill("funan_jiexun");
      }
    }
  }

