tw:twshangyi.code:
{
    audio: "spshangyi",
    enable: "phaseUse",
    usable: 1,
    filter(event2, player2) {
      return player2.countCards("he") && game.hasPlayer(function(current) {
        return current != player2 && current.countCards("h");
      });
    },
    filterTarget(card, player2, target) {
      return target != player2 && target.countCards("h");
    },
    filterCard: true,
    position: "he",
    async content(event2, trigger, player2) {
      const { target } = event2;
      await target.viewHandcards(player2);
      var chooseButton;
      if (player2.countCards("h")) {
        chooseButton = player2.chooseButton([1, 2], ['###尚义###<div class="text center">选择' + get.translation(target) + "的一张手牌以弃置，或选择你与其的各一张牌以交换</div>", '<div class="text center">' + get.translation(target) + "的手牌</div>", target.getCards("h"), '<div class="text center">你的手牌</div>', player2.getCards("h")], true);
      } else {
        chooseButton = player2.chooseButton(['###尚义###<div class="text center">弃置' + get.translation(target) + "的一张手牌</div>", '<div class="text center">' + get.translation(target) + "的手牌</div>", target.getCards("h")], true);
      }
      chooseButton.set("target", target);
      chooseButton.set("ai", function(button) {
        var player3 = _status.event.player, owner = get.owner(button.link), color = get.color(button.link, owner), value = get.value(button.link, owner);
        if (player3.countCards("h")) {
          if (!ui.selected.buttons.length) {
            if (player3.countCards("h", function(card) {
              return get.color(card, player3) == "red" && get.value(card) < 6;
            }) && color == "red" && value > 7) {
              return value * 3;
            }
            return value;
          } else {
            if (get.value(ui.selected.buttons[0].link) < 4) {
              return 0;
            }
            return 4 + (get.color(ui.selected.buttons[0].link, get.owner(ui.selected.buttons[0].link)) == "red" ? 3 : 1) - value;
          }
        } else {
          if (color == "black") {
            return value * 1.5;
          }
          return value;
        }
      });
      chooseButton.set("filterButton", function(button) {
        if (get.itemtype(button.link) != "card") {
          return false;
        }
        if (!ui.selected.buttons.length && get.owner(button.link) != _status.event.target) {
          return false;
        }
        if (ui.selected.buttons.length && get.owner(ui.selected.buttons[0].link) == get.owner(button.link)) {
          return false;
        }
        return true;
      });
      const result = await chooseButton.forResult();
      if (result.bool) {
        if (result.links.length == 1) {
          const cards2 = (await target.modedDiscard(result.links, player2).forResult()).cards;
          if (get.color(cards2[0], target) === "black") {
            await player2.draw();
          }
        } else {
          var links = result.links.slice();
          if (get.owner(links[0]) != player2) {
            links.reverse();
          }
          var card1 = links[0], card2 = links[1];
          await player2.swapHandcards(target, [card1], [card2]);
          if (get.color(card1, player2) === "red" && get.color(card2, target) === "red") {
            await player2.draw();
          }
        }
      }
    },
    ai: {
      order: 10,
      result: { target: -1 }
    }
  }

