tw:twbingyi.code:
{
    audio: "bingyi_xin_guyong",
    trigger: { player: "phaseJieshuBegin" },
    filter(event2, player2) {
      return player2.hasCards("h");
    },
    filterx(event2, player2) {
      const cards2 = player2.getCards("h");
      if (cards2.length === 1) {
        return true;
      }
      let color = get.color(cards2[0], player2);
      let type = get.type2(cards2[0], player2);
      for (const card of cards2.slice(1)) {
        if (color && get.color(card, player2) !== color) {
          color = false;
        }
        if (type && get.type2(card, player2) !== type) {
          type = false;
        }
        if (!color && !type) {
          return false;
        }
      }
      return true;
    },
    filtery(event2, player2) {
      const cards2 = player2.getCards("h");
      if (player2.countCards("h") <= 1) {
        return false;
      }
      const color = get.color(cards2[0], player2);
      const type = get.type2(cards2[0], player2);
      let colorx = true;
      let typex = true;
      for (const card of cards2.slice(1)) {
        if (color && get.color(card, player2) !== color) {
          colorx = false;
        }
        if (type && get.type2(card, player2) !== type) {
          typex = false;
        }
      }
      return colorx && typex;
    },
    async cost(event2, trigger, player2) {
      const boolx = lib.skill.twbingyi.filtery(trigger, player2);
      let result;
      if (lib.skill.twbingyi.filterx(trigger, player2)) {
        result = await player2.chooseTarget({
          prompt: get.prompt(event2.skill),
          prompt2: `选择至多${get.cnNumber(player2.countCards("h"))}名角色，你展示所有手牌，这些角色各摸一张牌${boolx ? "，然后你移去所有“慎”" : ""}`,
          selectTarget: [0, player2.countCards("h")],
          ai: (target) => get.attitude(_status.event.player, target)
        }).set("animate", false).forResult();
      } else {
        result = await player2.chooseBool({
          prompt: get.prompt(event2.skill),
          prompt2: "展示所有手牌",
          ai: () => false
        }).forResult();
      }
      event2.result = {
        bool: result.bool,
        targets: result.targets,
        cost_data: boolx
      };
    },
    async content(event2, trigger, player2) {
      await player2.showHandcards(`${get.translation(player2)}发动了【秉壹】`);
      const targets = event2.targets;
      if (targets && targets.length) {
        targets.sortBySeat();
        await game.asyncDraw(targets);
      }
      if (event2.cost_data) {
        player2.removeMark("twgyshenxing", player2.countMark("twgyshenxing"));
      }
    },
    ai: { expose: 0.1 }
  }

