tw:twfenming.code:
{
    audio: "fenming",
    trigger: { player: "phaseZhunbeiBegin" },
    filter(event2, player2) {
      return game.hasPlayer((target) => target !== player2 && (target.hasCards("he") || !target.isLinked()));
    },
    async cost(event2, trigger, player2) {
      event2.result = await player2.chooseTarget({
        prompt: get.prompt2(event2.skill),
        filterTarget: (card, player3, target) => target !== player3 && (target.hasCards("he") || !target.isLinked()),
        ai: (target) => get.damageEffect(target, player2, player2)
      }).forResult();
    },
    async content(event2, trigger, player2) {
      const [target] = event2.targets;
      const list = [];
      const choiceList = [`令${get.translation(target)}弃置一张牌`, `令${get.translation(target)}横置`, `背水！横置并依次令${get.translation(target)}执行上述所有选项`];
      const canDiscard = target.hasCards("he");
      const canLink = !target.isLinked();
      if (canDiscard) {
        list.push("选项一");
      } else {
        choiceList[0] = `<span style="opacity:0.5">${choiceList[0]}</span>`;
      }
      if (canLink) {
        list.push("选项二");
      } else {
        choiceList[1] = `<span style="opacity:0.5">${choiceList[1]}</span>`;
      }
      if (canDiscard && canLink && !player2.isLinked()) {
        list.push("背水！");
      } else {
        choiceList[2] = `<span style="opacity:0.5">${choiceList[2]}</span>`;
      }
      let control = list[0];
      if (list.length !== 1) {
        const controlResult = await player2.chooseControl({
          controls: list,
          choiceList,
          prompt: "奋命：请选择一项",
          ai: () => {
            const controls = _status.event.controls;
            if (controls.includes("背水！")) {
              return "背水！";
            }
            if (controls.includes("选项一")) {
              return "选项一";
            }
            return "选项二";
          }
        }).forResult();
        control = controlResult.control;
      }
      game.log(player2, "选择了", `#y${control}`);
      if (control !== "选项二") {
        await target.chooseToDiscard({
          position: "he",
          forced: true
        });
      }
      if (control !== "选项一" && !target.isLinked()) {
        await target.link(true);
      }
      if (control === "背水！" && !player2.isLinked()) {
        await player2.link(true);
      }
    }
  }

tw:twgongji.code:
{
    audio: "gongji",
    enable: "phaseUse",
    usable: 1,
    position: "he",
    filterCard: true,
    locked: false,
    filter(event2, player2) {
      return player2.hasCards("he");
    },
    check(card) {
      const player2 = _status.event.player;
      const suit = get.suit(card, player2);
      let base = 0;
      let added = false;
      let added2 = false;
      let added3;
      if (get.type(card) === "equip" && game.hasPlayer((target) => {
        const att = get.attitude(player2, target);
        return att < 0 && target.hasCards("he", (card2) => get.value(card2) > 5) ? -att : 0;
      })) {
        base += 6;
      }
      let hs = player2.getCards("h");
      const muniu = player2.getEquip("muniu");
      if (muniu && card !== muniu && muniu.cards) {
        hs = hs.concat(muniu.cards);
      }
      for (const i of hs) {
        if (i === card || get.name(i) !== "sha") {
          continue;
        }
        if (get.suit(i, player2) === suit) {
          if (player2.hasValueTarget(i, false)) {
            added3 = true;
            base += 5.5;
          }
        } else {
          if (player2.hasValueTarget(i, false)) {
            added2 = true;
          }
          if (!added && !player2.hasValueTarget(i, null, true) && player2.hasValueTarget(i, false, true)) {
            base += 4;
            added = true;
          }
        }
      }
      if (added3 && !added2) {
        base -= 4.5;
      }
      return base - get.value(card);
    },
    async content(event2, trigger, player2) {
      const cards2 = event2.cards;
      player2.addTempSkill("twgongji2");
      player2.markAuto("twgongji2", [get.suit(cards2[0], player2)]);
      if (get.type(cards2[0], null, cards2[0].original === "h" ? player2 : false) !== "equip") {
        event2.finish();
        return;
      }
      const result = await player2.chooseTarget({
        prompt: "是否弃置一名角色的一张牌？",
        filterTarget: (card, player3, target) => player3 !== target && target.hasCards("he"),
        ai: (target) => get.effect(target, { name: "guohe_copy2" }, player2, player2)
      }).forResult();
      if (result.bool) {
        player2.line(result.targets, "green");
        await player2.discardPlayerCard({
          target: result.targets[0],
          position: "he",
          forced: true
        });
      }
    },
    mod: {
      attackRangeBase() {
        return Infinity;
      }
    },
    ai: {
      order: 4.5,
      result: { player: 1 }
    }
  }

tw:twjiefan.code:
{
    skillAnimation: true,
    animationColor: "wood",
    audio: "jiefan",
    limited: true,
    enable: "phaseUse",
    filterTarget: true,
    async content(event2, trigger, player2) {
      const { target } = event2;
      player2.awakenSkill(event2.name);
      const players = game.filterPlayer((current) => current !== target && current.inRange(target));
      players.sortBySeat();
      for (const current of players) {
        current.addTempClass("target");
        player2.line(current, "green");
        let result = { bool: false };
        if (current.hasCards("he") && target.isIn()) {
          result = await current.chooseToDiscard({
