            position: "he",
            prompt: `解烦：弃置一张武器牌，或令${get.translation(target)}摸一张牌`,
            ai: (card) => {
              if (!target.isIn()) {
                return 0;
              }
              return get.attitude(current, target) < 0 ? 7 - get.value(card) : -1;
            }
          }).set("target", target).forResult();
        }
        if (!result.bool && target.isIn()) {
          await target.draw();
        }
      }
      player2.addSkill("twjiefan2");
      player2.markAuto("twjiefan2", [target]);
    },
    ai: {
      order: 5,
      result: {
        target(player2, target) {
          if (player2.hp > 2 && game.phaseNumber < game.players.length * 2) {
            return 0;
          }
          const players = game.filterPlayer();
          let num = 0;
          for (const current of players) {
            if (current !== target && current.inRange(target)) {
              num++;
            }
          }
          return num;
        }
      }
    }
  }

tw:twshuangren.code:
{
    audio: "shuangren",
    trigger: { player: "phaseUseBegin" },
    filter(event2, player2, name) {
      if (!player2.hasCards("h")) {
        return false;
      }
      if (name === "phaseUseEnd") {
        return !player2.hasHistory("sourceDamage", (evt) => {
          return evt.card.name === "sha" && event2.getParent("phaseUse") === evt;
        });
      }
      return true;
    },
    direct: true,
    group: "twshuangren_end",
    preHidden: true,
    async content(event2, trigger, player2) {
      const forced = event2.getParent(2).name === "twshuangren_end" && game.hasPlayer((current) => player2.canCompare(current));
      const goon = event2.triggername !== "phaseUseBegin" || player2.hasCards("hs", "sha") && player2.hasValueTarget({ name: "sha" });
      const targetResult = await player2.chooseTarget({
        prompt: forced ? "双刃：选择一名角色" : get.prompt("twshuangren"),
        prompt2: "与一名角色拼点，若你：赢，你可以视为对至多两名至其的距离不大于1的角色使用一张【杀】；没赢，其可以视为对你使用一张【杀】",
        forced,
        filterTarget: (card, player3, target2) => player3.canCompare(target2),
        ai: (target2) => {
          if (_status.event.goon) {
            return get.effect(target2, { name: "sha" }, _status.event.player);
          }
          return 0;
        }
      }).set("goon", goon).forResult();
      if (!targetResult.bool) {
        return;
      }
      const target = targetResult.targets[0];
      player2.logSkill("twshuangren", target);
      if (!player2.canCompare(target)) {
        return;
      }
      const compareResult = await player2.chooseToCompare(target).forResult();
      if (compareResult.bool) {
        const shaResult2 = await player2.chooseTarget({
          selectTarget: [1, 2],
          prompt: "请选择【杀】的目标",
          forced: true,
          filterTarget: (card, player3, current) => {
            if (!player3.canUse("sha", current, false, false)) {
              return false;
            }
            return get.distance(current, target) <= 1;
          },
          ai: (current) => get.effect(current, { name: "sha" }, player2, player2)
        }).forResult();
        if (!shaResult2.bool) {
          return;
        }
        shaResult2.targets.sortBySeat();
        for (const current of shaResult2.targets) {
          await player2.useCard({
            card: { name: "sha", isCard: true },
            targets: [current],
            addCount: false
          });
        }
        return;
      }
      const shaResult = await target.chooseBool({
        prompt: `双刃：是否视为对${get.translation(player2)}使用一张杀？`,
        choice: get.effect(player2, { name: "sha" }, target, target) > 0
      }).forResult();
      if (shaResult.bool) {
        await target.useCard({
          card: { name: "sha", isCard: true },
          targets: [player2],
          addCount: false
        });
      }
    },
    subSkill: {
      end: {
        audio: "shuangren",
        trigger: { player: "phaseUseEnd" },
        filter(event2, player2, name) {
          if (!player2.hasCards("h")) {
            return false;
          }
          return !player2.hasHistory("useSkill", (evt) => {
            return evt.skill === "twshuangren";
          }) && !player2.hasHistory("sourceDamage", (evt) => {
            return evt.card && evt.card.name === "sha";
          });
        },
        direct: true,
        preHidden: true,
        async content(event2, trigger, player2) {
          const goon = player2.hasCard((card) => {
            if (player2.needsToDiscard() > 1) {
              return card.number > 10 && get.value(card) <= 5;
            }
            return card.number >= 9 && get.value(card) <= 5 || get.value(card) <= 3;
          });
          const result = await player2.chooseToDiscard({
            prompt: get.prompt("twshuangren"),
            prompt2: "弃置一张牌发动〖双刃〗",
            position: "he",
            ai: (card) => {
              if (_status.event.goon) {
                return 5 - get.value(card);
              }
              return 0;
            }
          }).set("goon", goon).setHiddenSkill("twshuangren").set("logSkill", "twshuangren").forResult();
          if (result.bool) {
            await player2.useSkill({ skill: "twshuangren" });
          }
        }
      }
    }
  }

