{
    audio: "xuanhuo",
    trigger: { player: "phaseDrawEnd" },
    filter(event2, player2) {
      return player2.countCards("he") > 1 && game.countPlayer() > 2;
    },
    async cost(event2, trigger, player2) {
      const targetAi = (target) => {
        if (get.attitude(player2, target) <= 0) {
          return 0;
        }
        const cardNames = ["sha", "juedou"];
        let num = Math.max(...cardNames.map((name) => target.getUseValue({ name, isCard: true }, false)));
        if (target.hasSkillTag("nogain")) {
          num /= 4;
        }
        return num;
      };
      const shouldGive = game.hasPlayer((current) => current !== player2 && targetAi(player2) > 0);
      event2.result = await player2.chooseCardTarget({
        prompt: get.prompt2(event2.skill),
        filterCard: true,
        selectCard: 2,
        position: "he",
        filterTarget: lib.filter.notMe,
        ai1: (card) => {
          if (!shouldGive) {
            return 0;
          }
          return 7 - get.value(card);
        },
        ai2: targetAi
      }).forResult();
    },
    async content(event2, trigger, player2) {
      const target = event2.targets[0];
      await player2.give(event2.cards, target);
      if (!game.hasPlayer((current) => current !== player2 && current !== target)) {
        return;
      }
      const secondTargetResult = await player2.chooseTarget({
        prompt: `选择${get.translation(target)}使用【杀】或【决斗】的目标`,
        forced: true,
        filterTarget: (card, player3, current) => current !== player3 && current !== target,
        ai: (current) => {
          const cardNames = ["sha", "juedou"];
          return Math.max(
            ...cardNames.map((name) => {
              const card = { name, isCard: true };
              if (!target.canUse(card, current, false)) {
                return 0;
              }
