        controls: [...list, "cancel2"],
        prompt: get.prompt(event2.skill, source),
        choiceList,
        ai: () => choice
      }).forResult();
      event2.result = {
        bool: result.control !== "cancel2",
        targets: [source],
        cost_data: { num, control: result.control }
      };
