          selectCard: num,
          forced: true,
          allowChooseAll: true
        });
      }
      if (control !== "选项一") {
        await player2.discardPlayerCard({
          target: source,
          position: "he",
          forced: true
        });
      }
      if (control === "背水！") {
        await player2.chooseToDiscard({
          position: "he",
          filterCard: { type: "equip" },
          forced: true
        });
      }
    }
  }

