tw:twzhibian.code:
{
    audio: "zhibian",
    trigger: { player: "phaseUseBegin" },
    filter(event2, player2) {
      return game.hasPlayer((current) => current !== player2 && player2.canCompare(current));
    },
    async cost(event2, trigger, player2) {
      const canInitiate = player2.hasCard((card) => card.number >= 14 - player2.hp && get.value(card) <= 5);
      event2.result = await player2.chooseTarget({
        prompt: get.prompt(event2.skill),
        prompt2: "与一名其他角色拼点",
        filterTarget: (card, player3, target) => target !== player3 && player3.canCompare(target),
        ai: (target) => {
          if (!canInitiate) {
            return false;
          }
          const attitude = get.attitude(player2, target);
          if (attitude < 0 && (target.countCards("h") > 1 || target.hasCards("e", (card) => player2.canEquip(card) && get.effect(player2, card, target, player2) > 0))) {
            return -attitude / Math.sqrt(target.countCards("h"));
          }
          if (!player2.isDamaged()) {
            return false;
          }
          if (attitude <= 0) {
            return (1 - attitude) / Math.sqrt(target.countCards("h"));
          }
          return Math.sqrt(2 / attitude * Math.sqrt(target.countCards("h")));
        }
      }).forResult();
    },
    async content(event2, trigger, player2) {
      const target = event2.targets[0];
      const compareResult = await player2.chooseToCompare(target).forResult();
      if (!compareResult.bool) {
        await player2.loseHp();
        return;
      }
      const controls = [];
      const choiceList = [`将${get.translation(target)}区域中的一张牌移动到你的区域内`, "回复1点体力", "背水！弃置一张非基本牌，并依次执行上述所有选项"];
      if (target.hasCards("h") || target.hasCard((card) => player2.canEquip(card), "e") || target.hasCard((card) => player2.canAddJudge(card), "j")) {
        controls.push("选项一");
      } else {
        choiceList[0] = `<span style="opacity:0.5">${choiceList[0]}</span>`;
      }
      if (player2.isDamaged()) {
        controls.push("选项二");
      } else {
        choiceList[1] = `<span style="opacity:0.5">${choiceList[1]}</span>`;
      }
      if (!controls.length) {
        return;
      }
      if (player2.hasCards("he", (card) => get.type(card) !== "basic")) {
        controls.push("背水！");
      } else {
        choiceList[2] = `<span style="opacity:0.5">${choiceList[2]}</span>`;
      }
      controls.push("cancel2");
      const controlResult = await player2.chooseControl({
        controls,
        prompt: "直辩：选择一项",
        choiceList,
        ai: (event3) => {
          if (event3.controls.includes("背水！") && player2.isDamaged() && (target.hasCards("h") || target.hasCards("e", (card) => player2.canEquip(card) && get.value(card, target) >= 4 + player2.getDamagedHp()))) {
            return 2;
          }
          if (player2.isDamaged() && (player2.hp <= 2 || !target.hasCards("h") && !target.hasCards("e", (card) => player2.canEquip(card) && get.value(card, target) >= 4 + player2.getDamagedHp()))) {
            return 1;
          }
          return 0;
        }
      }).forResult();
      const control = controlResult.control;
      if (control === "cancel2") {
        return;
      }
      if (control === "背水！" && player2.hasCards("he", (card) => get.type(card) !== "basic")) {
        await player2.chooseToDiscard({
          position: "he",
          forced: true,
          filterCard: (card) => get.type(card) !== "basic"
        });
      }
      if (control === "选项一" || control === "背水！") {
        const cardResult = await player2.choosePlayerCard({
          target,
          position: "hej",
          forced: true,
          ai: get.buttonValue
        }).forResult();
        if (cardResult.bool) {
          const card = cardResult.cards[0];
          switch (get.position(card)) {
            case "h":
              await player2.gain({ cards: [card], source: target, animate: "giveAuto" });
              break;
            case "e":
              target.$give(card, player2, false);
              await player2.equip(card);
              break;
            case "j":
              target.$give(card, player2, false);
              await player2.addJudge(card);
              break;
          }
        }
      }
      if (control === "选项二" || control === "背水！") {
        await player2.recover();
      }
    }
  }

