    filter(event2, player2) {
      return event2.card.name === "sha" && event2.card.isCard && player2.hp < event2.player.hp;
    },
    forced: true,
    logTarget: "player",
    async content(event2, trigger, player2) {
      const num = get.number(trigger.card);
      const str = typeof num === "number" ? `点数大于${get.cnNumber(num)}的` : "非基本";
      const mayHaveCard = (card) => {
        if (_status.connectMode && get.position(card) === "h") {
          return true;
        }
        return typeof num === "number" ? get.number(card) > num : get.type(card) !== "basic";
      };
      let result;
      if (typeof num === "number" && num >= 13 || !trigger.player.hasCard(mayHaveCard, "he")) {
        result = { bool: false };
      } else {
        result = await trigger.player.chooseCard({
          position: "he",
          filterCard: (card) => typeof num === "number" ? get.number(card) > num : get.type(card) !== "basic",
          prompt: `交给${get.translation(player2)}一张${str}牌，或取消${get.translation(trigger.card)}对其的目标`,
          ai: (card) => {
            if (card.name === "shan" || card.name === "tao" || card.name === "jiu") {
              return false;
            }
            return 6 - get.value(card);
          }
        }).forResult();
      }
      if (result.bool) {
        await trigger.player.give(result.cards, player2);
      } else {
        trigger.targets.remove(player2);
        trigger.getParent().triggeredTargets2.remove(player2);
        trigger.untrigger();
      }
    },
    ai: {
      effect: {
        target_use(card, player2, target, current) {
          if (card.name === "sha" && player2.hp > target.hp && get.attitude(player2, target) < 0) {
            const num = get.number(card);
            const bs = player2.getCards("h", (cardx) => (typeof num === "number" ? get.number(cardx) > num : get.type(cardx) !== "basic") && !["", "", ""].includes(cardx.name));
            if (bs.length < 2) {
              return 0;
            }
            if (player2.hasSkill("jiu") || player2.hasSkill("tianxianjiu")) {
              return;
            }
            if (bs.length <= 2) {
              for (const cardx of bs) {
                if (get.value(cardx) < 6) {
                  return [1, 0, 1, -0.5];
                }
              }
              return 0;
            }
            return [1, 0, 1, -0.5];
          }
        }
      }
    }
  }

