{
    audio: "zhangming",
    trigger: { player: "useCardToTargeted" },
    filter(event2, player2) {
      if (event2.target === player2 || event2.card.storage && event2.card.storage.twguoyi) {
        return false;
      }
      return (event2.card.name === "sha" || get.type(event2.card) === "trick") && (event2.target.isMaxHp() || event2.target.isMaxHandcard() || player2.countCards("h") <= player2.getDamagedHp() + 1);
    },
    check(event2, player2) {
      return get.attitude(player2, event2.target) <= 0;
    },
    logTarget: "target",
    group: "twguoyi_reuse",
    async content(event2, trigger, player2) {
      const bool1 = trigger.target.isMaxHp() || trigger.target.isMaxHandcard();
      const bool2 = player2.countCards("h") <= player2.getDamagedHp() + 1;
      let result;
      if (!trigger.target.hasCards("he")) {
        result = { index: 0 };
      } else {
        result = await trigger.target.chooseControl({
          choiceList: ["本回合不能使用或打出手牌", `弃置${get.cnNumber(player2.getDamagedHp() + 1)}张牌`],
          ai(_event, player3) {
            if (player3.countCards("h") <= player3.getHandcardLimit()) {
              return 0;
            }
            return 1;
          }
        }).forResult();
      }
      player2.addTempSkill(`twguoyi_${result.index}`);
      if (result.index === 0) {
        trigger.target.addTempSkill("twguoyi_hand");
      } else {
        await trigger.target.chooseToDiscard({
          position: "he",
          selectCard: player2.getDamagedHp() + 1,
          forced: true
        });
      }
      if (bool1 && bool2 || player2.hasSkill("twguoyi_0") && player2.hasSkill("twguoyi_1")) {
        if (!trigger.getParent().twguoyi_reuse) {
          trigger.getParent().twguoyi_reuse = {
            name: trigger.card.name,
            nature: trigger.card.nature,
            isCard: true,
            storage: { twguoyi: true }
          };
        }
      }
    },
    subSkill: {
      0: { charlotte: true },
      1: { charlotte: true },
      hand: {
        charlotte: true,
        mark: true,
        intro: { content: "不能使用或打出手牌" },
        mod: {
          cardEnabled2(card) {
            if (get.position(card) === "h") {
              return false;
            }
          }
        }
      },
      reuse: {
        charlotte: true,
        trigger: { player: "useCardAfter" },
        filter(event2, player2) {
          return event2.twguoyi_reuse;
        },
        direct: true,
        async content(event2, trigger, player2) {
          const card = trigger.twguoyi_reuse;
          for (const target of trigger.targets) {
            if (!target.isIn() || !player2.canUse(card, target, false)) {
              return;
            }
          }
          if (trigger.addedTarget && !trigger.addedTarget.isIn()) {
            return;
          }
          if (trigger.addedTargets && trigger.addedTargets.length) {
            for (const target of trigger.addedTargets) {
              if (!target.isIn()) {
                return;
              }
            }
          }
          const next = player2.useCard({
            card: get.copy(card),
            targets: trigger.targets,
            addCount: false
          });
          if (trigger.addedTarget) {
            next.addedTarget = trigger.addedTarget;
          }
          if (trigger.addedTargets && trigger.addedTargets.length) {
            next.addedTargets = trigger.addedTargets.slice(0);
          }
          await next;
        }
      }
    }
  }

