            prompt2 += "选择一名合法的其他角色，以增加其为目标；或";
          }
          prompt2 += `选择目标角色（${get.translation(trigger.target)}）和另一名合法的角色，以取消前者为目标并增加后者为目标`;
          const result = await player2.chooseTarget({
            prompt: `遗珠：是否${enable ? "增加或" : ""}修改目标？`,
            prompt2,
            selectTarget: [enable ? 1 : 2, 2],
            filterTarget: (_card, player3, target) => {
              const evt = get.event().getTrigger();
              const card = evt.card;
              if (target === evt.target) {
                return true;
              }
              if (ui.selected.targets.length && ui.selected.targets[0] !== evt.target) {
                return false;
              }
              return lib.filter.targetEnabled2(card, evt.player, target);
            },
            ai(target) {
              const evt = get.event().getTrigger();
              const card = evt.card;
              const player3 = get.event().player;
              if (target === evt.target && get.effect(evt.target, card, evt.player, player3) < 0) {
                return 100;
              }
              if (target === evt.target) {
                return -100;
              }
              return get.effect(target, card, evt.player, player3);
            }
          }).set("targetprompt", (target) => target === get.event().targetx ? "取消目标" : "增加目标").set("filterOk", () => {
            if (ui.selected.targets.length === 1 && ui.selected.targets[0] === get.event().targetx) {
              return false;
            }
            return true;
          }).set("targetx", trigger.target).set("card", trigger.card).forResult();
          if (result.bool) {
            const target = result.targets[result.targets[0] === trigger.target ? 1 : 0];
            if (result.targets.length > 1) {
              player2.line2([trigger.target, target]);
              trigger.targets.remove(trigger.target);
              trigger.getParent().triggeredTargets1.remove(trigger.target);
              trigger.untrigger();
            } else {
              player2.line(target);
            }
            trigger.targets.push(target);
          }
          const cards2 = trigger.cards.filter((card) => player2.getStorage("twyizhu").includes(card));
          player2.unmarkAuto("twyizhu", cards2);
          await player2.draw();
          await game.delayx();
        }
      },
      discard: {
        trigger: {
          global: ["loseAfter", "cardsDiscardAfter", "loseAsyncAfter", "equipAfter"]
        },
        silent: true,
        forced: true,
        locked: false,
        filter(event2, player2) {
          return player2.getStorage("twyizhu").length && event2.getd().some((card) => player2.getStorage("twyizhu").includes(card));
        },
        async content(event2, trigger, player2) {
          const cards2 = trigger.getd().filter((card) => player2.getStorage("twyizhu").includes(card));
          player2.unmarkAuto("twyizhu", cards2);
        }
      }
    }
  }

