tw:twyuejian.code:
{
    audio: "spyuejian",
    enable: "phaseUse",
    filterCard: true,
    selectCard() {
      var player2 = _status.event.player;
      var num = Math.max(1, player2.countCards("h") - player2.getHandcardLimit());
      return [1, num];
    },
    complexCard: true,
    discard: false,
    lose: false,
    delay: false,
    position: "he",
    usable: 1,
    check(card) {
      if (ui.selected.cards.length >= 3) {
        return 0;
      }
      var player2 = _status.event.player;
      var num = Math.max(1, player2.countCards("h") - player2.getHandcardLimit());
      if (num >= 3) {
        return 5 - get.value(card);
      }
      if (num >= 2 && player2.isDamaged() && ui.selected.cards.length < 1) {
        return 7 - get.value(card);
      }
      if (num >= 1 && player2.isDamaged() && !ui.selected.cards.length) {
        return 6 - get.value(card);
      }
      return 0;
    },
    async content(event2, trigger, player2) {
      const { cards: cards2 } = event2;
      const next = player2.chooseToMove();
      next.set("list", [["牌堆顶", cards2], ["牌堆底"]]);
      next.set("prompt", "约俭：将这些牌置于牌堆顶或牌堆底");
      next.set("processAI", function(list) {
        var cards3 = list[0][1].slice(0), player3 = _status.event.player;
        var target = player3.next;
        var att = get.sgn(get.attitude(player3, target));
        var top = [];
        var judges = target.getCards("j");
        var stopped = false;
        if (player3 != target || !target.hasWuxie()) {
          for (var i = 0; i < judges.length; i++) {
            var judge = get.judge(judges[i]);
            cards3.sort(function(a, b) {
              return (judge(b) - judge(a)) * att;
            });
            if (judge(cards3[0]) * att < 0) {
              stopped = true;
              break;
            } else {
              top.unshift(cards3.shift());
            }
          }
        }
        var bottom;
        if (!stopped) {
          cards3.sort(function(a, b) {
            return (get.value(b, player3) - get.value(a, player3)) * att;
          });
          while (cards3.length) {
            if (get.value(cards3[0], player3) <= 5 == att > 0) {
              break;
            }
            top.unshift(cards3.shift());
          }
        }
        bottom = cards3.sort(function(a, b) {
          return player3.getUseValue(a) - player3.getUseValue(b);
        });
        return [top, bottom];
      });
      const result = await next.forResult();
      if (result.moved?.length) {
        const {
          moved: [top, bottom]
        } = result;
        top.reverse();
        player2.$throw(cards2.length, 1e3);
        player2.popup(get.cnNumber(top.length) + "上" + get.cnNumber(bottom.length) + "下");
        game.log(player2, `将${get.cnNumber(top.length)}张牌置于牌堆顶`);
        game.log(player2, `将${get.cnNumber(bottom.length)}张牌置于牌堆底`);
        await player2.lose(top.concat(bottom), ui.cardPile).set("top_cards", top).set("insert_index", (event3, card) => {
          if (event3.top_cards.includes(card)) {
            return ui.cardPile.firstChild;
          }
          return null;
        });
        await game.delayx();
      }
      if (cards2.length >= 3) {
        await player2.gainMaxHp();
      }
      if (cards2.length >= 2) {
        await player2.recover();
      }
      if (cards2.length >= 1) {
        player2.addSkill("twyuejian_effect");
        player2.addMark("twyuejian_effect", 1, false);
      }
    },
    ai: {
      order: 5,
      result: { player: 1 }
    },
    subSkill: {
      effect: {
        charlotte: true,
        onremove: true,
        marktext: "俭",
        intro: {
          content: "手牌上限+#"
        },
        mod: {
          maxHandcard(player2, num) {
            return num + player2.countMark("twyuejian_effect");
          }
        }
      }
    }
  }

