tw:twzhenxi.code:
{
    audio: 2,
    trigger: {
      player: "useCardToPlayered"
    },
    filter(event2, player2) {
      const { target } = event2;
      return event2.card.name == "sha" && (target.countDiscardableCards(player2, "h") || player2.canMoveCard(
        null,
        true,
        target,
        game.filterPlayer((i) => i != target)
      ));
    },
    usable: 1,
    async cost(event2, trigger, player2) {
      const { target } = trigger;
      const str = get.translation(target);
      const list = [`弃置${str}${get.cnNumber(get.distance(player2, target))}张手牌`, `将${str}装备区或判定区内的一张牌移动到另一名角色的对应区域内`];
      const choices = [];
      if (target.countDiscardableCards(player2, "h")) {
        choices.push("选项一");
      } else {
        list[0] = '<span style="opacity:0.5">' + list[0] + "</span>";
      }
      if (player2.canMoveCard(
        null,
        true,
        target,
        game.filterPlayer((i) => i != target)
      )) {
        choices.push("选项二");
      } else {
        list[1] = '<span style="opacity:0.5">' + list[1] + "</span>";
      }
      if (choices.length == 2 && (target.hp > player2.hp || target.isMaxHp())) {
        list.push("背水！依次执行以上两项");
        choices.push("背水！");
      }
      choices.push("cancel2");
      const { control } = await player2.chooseControl(choices).set("choiceList", list).set("prompt", get.prompt(event2.skill, target)).set("ai", () => {
        const player3 = _status.event.player, target2 = _status.event.getTrigger().target;
        let eff1 = 0, eff2 = 0;
        var choices2 = _status.event.controls.slice(0);
        if (choices2.includes("选项一")) {
          eff1 = -get.distance(player3, target2) * get.attitude(player3, target2);
        }
        if (choices2.includes("选项二")) {
          var equip = 0, judge = 0, att = get.attitude(player3, target2);
          var es = target2.getCards("e"), js = target2.getCards("j");
          for (var i of es) {
            var val = get.value(i);
            if (att > 0) {
              if (val <= Math.min(0, equip) && game.hasPlayer(function(current) {
                return current != target2 && current.canEquip(i) && get.effect(current, i, player3, player3) > 0;
              })) {
                equip = val;
              }
            } else {
              if (val > Math.max(0, equip) && game.hasPlayer(function(current) {
                return current != target2 && current.canEquip(i) && get.effect(current, i, player3, player3) > 0;
              })) {
                equip = val;
              }
            }
          }
          for (var i of js) {
            var card = { name: i.viewAs || i.name };
            var effect = get.effect(target2, card, player3, player3);
            if (effect < 0) {
              game.countPlayer(function(current) {
                if (current != target2 && current.canAddJudge(i)) {
                  var eff = get.effect(current, card, player3, player3);
                  judge = Math.max(eff, judge);
                }
              });
            }
          }
          eff2 = Math.max(-equip * att, judge);
        }
        if (eff1 > 0) {
          if (eff2 > 0) {
            if (choices2.includes("背水！")) {
              return "背水！";
            } else if (eff2 >= eff1) {
              return "选项二";
            }
          }
          return "选项一";
        } else if (eff2 > 0) {
          return "选项二";
        }
        return "cancel2";
      }).forResult();
      event2.result = {
        bool: control !== "cancel2",
        cost_data: control
      };
    },
    logTarget: "target",
    async content(event2, trigger, player2) {
      const { target } = trigger, { cost_data: control } = event2;
      if (control != "选项二" && target.countDiscardableCards(player2, "h")) {
        await player2.discardPlayerCard(target, true, "h", get.distance(player2, target));
      }
      if (control == "选项一") {
        return;
      }
      if (control != "选项一" && player2.canMoveCard(
        null,
        true,
        target,
        game.filterPlayer((i) => i != target)
      )) {
        await player2.moveCard(
          true,
          target,
          game.filterPlayer((i) => i != target)
        );
      }
    },
    ai: {
      unequip_ai: true,
      skillTagFilter(player2, tag, arg) {
        if (!arg || !arg.name || arg.name != "sha") {
