tw:zhenshan.code:
{
    audio: 2,
    enable: ["chooseToUse", "chooseToRespond"],
    filter(event2, player2) {
      if (event2.type == "wuxie" || player2.hasSkill("zhenshan_used")) {
        return false;
      }
      const nh = player2.countCards("h");
      if (!game.hasPlayer(function(current) {
        return current != player2 && current.countCards("h") < nh;
      })) {
        return false;
      }
      for (const i of lib.inpile) {
        if (get.type(i) != "basic") {
          continue;
        }
        const card = { name: i, isCard: true };
        if (event2.filterCard(card, player2, event2)) {
          return true;
        }
        if (i == "sha") {
          for (const j of lib.inpile_nature) {
            card.nature = j;
            if (event2.filterCard(card, player2, event2)) {
              return true;
            }
          }
        }
      }
      return false;
    },
    chooseButton: {
      dialog(event2, player2) {
        const list = [];
        for (const i of lib.inpile) {
          if (get.type(i) != "basic") {
            continue;
          }
          const card = { name: i, isCard: true };
          if (event2.filterCard(card, player2, event2)) {
            list.push(["基本", "", i]);
          }
          if (i == "sha") {
            for (const j of lib.inpile_nature) {
              card.nature = j;
              if (event2.filterCard(card, player2, event2)) {
                list.push(["基本", "", i, j]);
              }
            }
          }
        }
        return ui.create.dialog("振赡", [list, "vcard"], "hidden");
      },
      check(button) {
        const player2 = _status.event.player;
        const card = { name: button.link[2], nature: button.link[3] };
        if (card.name == "jiu") {
          return 0;
        }
        if (game.hasPlayer(function(current) {
          return get.effect(current, card, player2, player2) > 0;
        })) {
          if (card.name == "sha") {
            const eff = player2.getUseValue(card);
            if (eff > 0) {
              return 2.9 + eff / 10;
            }
            return 0;
          } else if (card.name == "tao" || card.name == "shan") {
            return 4;
          }
        }
        return 0;
      },
      backup(links, player2) {
        return {
          filterCard: () => false,
          viewAs: {
            name: links[0][2],
            nature: links[0][3],
            isCard: true
          },
          selectCard: -1,
          log: false,
          async precontent(event2, trigger, player3) {
            const result = await player3.chooseTarget({
              prompt: "赈赡：选择一名手牌数小于你的角色交换手牌",
              filterTarget(card, player4, target) {
                return target != player4 && target.countCards("h") < player4.countCards("h");
              },
              forced: true,
              ai(target) {
                return get.attitude(get.player(), target) * Math.sqrt(target.countCards("h") + 1);
              }
            }).forResult();
            if (result?.bool) {
              player3.logSkill("zhenshan", result.targets);
              player3.addTempSkill("zhenshan_used");
              await player3.swapHandcards(result.targets[0]);
            } else {
              event2.result.cancel = true;
            }
            await game.delayx();
          }
        };
      },
      prompt(links, player2) {
        return "选择" + get.translation(links[0][3] || "") + "【" + get.translation(links[0][2]) + "】的目标";
      }
    },
    ai: {
      order() {
        const player2 = _status.event.player;
        const event2 = _status.event;
        const nh = player2.countCards("h");
        if (game.hasPlayer(function(current) {
          return get.attitude(player2, current) > 0 && current.countCards("h") < nh;
        })) {
          if (event2.type == "dying") {
            if (event2.filterCard({ name: "tao" }, player2, event2)) {
              return 0.5;
            }
          } else {
            if (event2.filterCard({ name: "tao" }, player2, event2) || event2.filterCard({ name: "shan" }, player2, event2)) {
              return 4;
            }
            if (event2.filterCard({ name: "sha" }, player2, event2)) {
              return 2.9;
            }
          }
        }
        return 0;
      },
      save: true,
      respondSha: true,
      respondShan: true,
      skillTagFilter(player2, tag, arg) {
        if (player2.getStat().skill.olzhenshan > 0) {
          return false;
        }
        const nh = player2.countCards("h");
        return game.hasPlayer(function(current) {
          return current != player2 && current.countCards("h") < nh;
        });
      },
      result: {
        player(player2) {
          if (_status.event.type == "dying") {
            return get.attitude(player2, _status.event.dying);
          }
          return 1;
        }
      }
    }
  }

