tw:twcongji.code:
{
    audio: "heji",
    trigger: {
      player: "loseAfter",
      global: "loseAsyncAfter"
    },
    filter(event2, player2) {
      if (player2 === _status.currentPhase || event2.type !== "discard" || event2.getlx === false || !game.hasPlayer((current) => current !== player2)) {
        return false;
      }
      const evt = event2.getl(player2);
      for (const card of evt.cards2) {
        if (get.color(card, player2) === "red" && get.position(card, true) === "d") {
          return true;
        }
      }
      return false;
    },
    async cost(event2, trigger, player2) {
      const cards2 = trigger.getl(player2).cards2.filter((card) => get.color(card, player2) === "red" && get.position(card, true) === "d");
      const goon = game.hasPlayer((current) => current !== player2 && get.attitude(player2, current) > 0);
      const buttonResult = await player2.chooseButton({
        createDialog: ["从击：选择任意张牌交给其他角色", cards2],
        selectButton: [1, cards2.length],
        ai: (button) => goon ? get.value(button.link) : button.link.name === "du" ? 1 : 0
      }).forResult();
      if (!buttonResult.bool) {
        event2.result = { bool: false };
        return;
      }
      const selectedCards = buttonResult.links;
      const targetResult = await player2.chooseTarget({
        prompt: "选择一名角色获得以下牌：",
        prompt2: get.translation(selectedCards),
        forced: true,
        filterTarget: lib.filter.notMe,
        ai(target) {
          if (selectedCards[0].name === "du") {
            return -get.attitude(player2, target);
          }
          let att = get.attitude(player2, target);
          if (att <= 0) {
            return 0;
          }
          if (target.hasSkillTag("nogain")) {
            att /= 10;
          }
          if (target.hasJudge("lebu")) {
            att /= 4;
          }
          return get.value(selectedCards, target) * att;
        }
      }).forResult();
      event2.result = {
        bool: targetResult.bool,
        cards: selectedCards,
        targets: targetResult.targets
      };
    },
    async content(event2, trigger, player2) {
      await event2.targets[0].gain({
        cards: event2.cards,
        animate: "gain2"
      });
    }
  }

