{
    audio: 2,
    trigger: { target: "useCardToTargeted" },
    usable: 1,
    filter(event2, player2) {
      return player2 != event2.player;
    },
    async cost(event2, trigger, player2) {
      const { player: target } = trigger;
      const choiceList = ["摸一张牌", `将${get.translation(target)}区域内的一张牌置于牌堆顶`];
      const choices = ["选项一"];
      if (target.countCards("hej") > 0) {
        choices.push("选项二");
      } else {
        choiceList[1] = '<span style="opacity:0.5">' + choiceList[1] + "</span>";
      }
      choices.push("cancel2");
      const result = await player2.chooseControl(choices).set("choiceList", choiceList).set(
        "choice",
        (() => {
          if (choices.length > 2 && get.effect(target, { name: "guohe_copy" }, player2, player2) > 0) {
            return 1;
          }
          return 0;
        })()
      ).forResult();
      event2.result = {
        bool: result?.control !== "cancel2",
        targets: [target],
        cost_data: result?.control
      };
    },
    async content(event2, trigger, player2) {
      const {
        targets: [target],
        cost_data
      } = event2;
      if (cost_data == "选项一") {
        await player2.draw();
      } else {
        const result2 = await player2.choosePlayerCard(target, "hej", true).forResult();
        if (result2?.links?.length) {
          const card = result2.links[0];
          target.$throw(get.position(card) == "h" ? 1 : card, 1e3);
          await target.lose(card, ui.cardPile, "insert");
        }
      }
      await game.delayx();
      if (player2.countCards("h") !== target.countCards("h")) {
        return;
      }
      const num = player2.storage.counttrigger?.[event2.name];
      if (typeof num == "number" && num > 0) {
        player2.storage.counttrigger[event2.name]--;
      }
      const result = await player2.chooseBool(`是否令${get.translation(trigger.card)}对自己无效？`).set("ai", () => {
        const evt = _status.event.getTrigger();
        return get.effect(evt.target, evt.card, evt.player, evt.target) < 0;
      }).forResult();
      if (result?.bool) {
        trigger.excluded.add(player2);
      }
    }
  }

