tw:twfengji.code:
{
    audio: 2,
    mahouSkill: true,
    trigger: { player: "phaseUseBegin" },
    filter(event2, player2) {
      return !player2.getExpansions("twfengji").length && !player2.hasSkill("twfengji_mahou") && player2.countCards("he");
    },
    async cost(event2, trigger, player2) {
      const result = await player2.chooseCard({
        position: "he",
        prompt: get.prompt2("twfengji"),
        ai: (card) => {
          const name = card.name;
          let num = 0;
          for (const node of ui.cardPile.childNodes) {
            if (node.name === name) {
              num++;
            }
          }
          if (num < 2) {
            return false;
          }
          return 8 - get.value(card);
        }
      }).forResult();
      if (!result.bool) {
        return;
      }
      const controlResult = await player2.chooseControl("1回合", "2回合", "3回合").set("prompt", "请选择施法时长").set("ai", () => {
        const player3 = _status.event.player;
        let safe = Math.min(player3.getHandcardLimit(), player3.countCards("h", "shan"));
        if (safe < Math.min(3, game.countPlayer())) {
          let next = player3.next;
          while (next !== player3 && get.attitude(next, player3) > 0) {
            safe++;
            next = next.next;
          }
        }
        return Math.max(2, Math.min(safe, 3, game.countPlayer())) - 1;
      }).forResult();
      event2.result = {
        bool: true,
        cards: result.cards,
        cost_data: controlResult.index
      };
    },
    async content(event2, trigger, player2) {
      const index = event2.cost_data;
      await player2.addToExpansion({
        cards: event2.cards,
        source: player2,
        animate: "giveAuto",
        gaintag: ["twfengji"]
      });
      player2.storage.twfengji_mahou = [index + 1, index + 1];
      player2.addTempSkill("twfengji_mahou", { player: "die" });
    },
    marktext: "示",
    onremove(player2, skill) {
      var cards2 = player2.getExpansions(skill);
      if (cards2.length) {
        player2.loseToDiscardpile(cards2);
      }
    },
    intro: {
      content: "expansion",
      markcount: "expansion"
    },
    subSkill: {
      mahou: {
        trigger: { global: "phaseEnd" },
        forced: true,
        popup: false,
        charlotte: true,
        async content(event2, trigger, player2) {
          const list = player2.storage.twfengji_mahou;
          list[1]--;
          if (list[1] === 0) {
            game.log(player2, "的“蜂集”魔法生效");
            player2.logSkill("twfengji");
            const cards2 = player2.getExpansions("twfengji");
            if (cards2.length) {
              let cards22 = [];
              const num = list[0];
              for (const card of cards2) {
                for (let i = 0; i < num; i++) {
                  const card2 = get.cardPile2((cardx) => cardx.name === card.name && !cards22.includes(cardx));
                  if (card2) {
                    cards22.push(card2);
                  } else {
                    break;
                  }
                }
              }
              game.delayx();
              if (cards22.length) {
                await player2.gain(cards22, "gain2");
              }
              await player2.loseToDiscardpile(cards2);
            }
            player2.removeSkill("twfengji_mahou");
          } else {
            game.log(player2, `的“蜂集”魔法剩余`, `#g${list[1]}回合`);
            player2.markSkill("twfengji_mahou");
          }
        },
        ai: { threaten: 2.5 },
        mark: true,
        onremove: true,
        //该图标为灵魂宝石
        marktext: "♗",
        intro: {
          name: "施法：蜂集",
          markcount(storage) {
            if (storage) {
              return storage[1];
            }
            return 0;
          },
          content(storage) {
            if (storage) {
              return "经过" + storage[1] + "个“回合结束时”后，若有“示”，则从牌堆中获得" + storage[0] + "张和“示”名称相同的牌";
            }
            return "未指定施法效果";
          }
        }
      }
    }
  }

