      event2.result = await player2.chooseCard(`${get.translation(trigger.player)}的${trigger.judgestr || ""}判定为${get.translation(trigger.player.judging[0])}，${get.prompt(event2.skill)}`, "hes", (card) => {
        const player3 = get.player();
