        const { player: player3, judging } = get.event();
        const result = trigger2.judge(card) - trigger2.judge(judging);
        const attitude = get.attitude(player3, trigger2.player);
        if (attitude == 0 || result == 0) {
          if (trigger2.player != player3) {
            return 0;
          }
          const checkx = get.color(card, player3) == get.color(judging);
          if (checkx > 0) {
            return checkx;
          }
          return 0;
        }
        return result * (attitude > 0 ? 1 : -1);
      }).set("judging", trigger.player.judging[0]).forResult();
