{
    audio: 2,
    global: "twyujue_give",
    trigger: {
      player: "gainAfter",
      global: "loseAsyncAfter"
    },
    direct: true,
    filter(event2, player2) {
      if (player2 === _status.currentPhase) {
        return false;
      }
      const cards2 = event2.getg(player2);
      if (!cards2.length) {
        return false;
      }
      return game.hasPlayer((current) => {
        if (current === player2) {
          return false;
        }
        const evt = event2.getl(current);
        if (!evt || !evt.cards2 || !evt.cards2.filter((card) => cards2.includes(card)).length) {
          return false;
        }
        return !current.hasSkill("twyujue_effect0") || !current.hasSkill("twyujue_effect1");
      });
    },
    async content(event2, trigger, player2) {
      const gainedCards = trigger.getg(player2);
      const targets = game.filterPlayer((current) => {
        if (current === player2) {
          return false;
        }
        const evt = trigger.getl(current);
        if (!evt || !evt.cards2 || !evt.cards2.filter((card) => gainedCards.includes(card)).length) {
          return false;
        }
        return !current.hasSkill("twyujue_effect0") || !current.hasSkill("twyujue_effect1");
      }).sortBySeat();
      for (const target of targets) {
        if (!target.isIn()) {
          continue;
        }
        let count = 2;
        if (target.hasSkill("twyujue_effect0")) {
          count--;
        }
        if (target.hasSkill("twyujue_effect1")) {
          count--;
        }
        count = Math.min(count, trigger.getl(target).cards2.filter((card) => gainedCards.includes(card)).length);
        for (let index = 0; index < count; index++) {
          const boolResult = await player2.chooseBool({
            prompt: get.prompt("twyujue", target),
            prompt2: "可令其选择本回合内未选择过的一项：⒈弃置攻击范围内一名角色的一张牌。⒉下一次使用牌时，从牌堆中获得一张同类别的牌。",
            ai: () => get.attitude(player2, target) > 0
          }).forResult();
          if (boolResult.bool) {
            player2.logSkill("twyujue", target);
            const availableEffects = [0, 1];
            if (target.hasSkill("twyujue_effect0")) {
              availableEffects.remove(0);
            }
            if (target.hasSkill("twyujue_effect1")) {
              availableEffects.remove(1);
            }
            let effectIndex;
            if (availableEffects.length === 1) {
              effectIndex = availableEffects[0];
            } else if (availableEffects.length > 1) {
              const controlResult = await target.chooseControl({
                choiceList: ["弃置攻击范围内一名角色的一张牌", "下一次使用牌时，从牌堆中获得一张同类别的牌"],
                ai: (event3, player3) => game.hasPlayer((current) => player3.inRange(current) && current.hasDiscardableCards(player3, "he") && get.effect(current, { name: "guohe_copy2" }, player3, player3) > 0) ? 0 : 1
              }).forResult();
              effectIndex = controlResult.index;
