            if (effectIndex != null) {
              target.addTempSkill(`twyujue_effect${effectIndex}`);
            }
            if (effectIndex === 0 && game.hasPlayer((current) => target.inRange(current) && current.hasDiscardableCards(target, "he"))) {
              const discardTargetResult = await target.chooseTarget({
                prompt: "弃置攻击范围内一名角色的一张牌",
                forced: true,
                filterTarget: (card, player3, target2) => player3.inRange(target2) && target2.hasDiscardableCards(player3, "he"),
                ai: (target2) => get.effect(target2, { name: "guohe_copy2" }, _status.event.player, _status.event.player)
              }).forResult();
              if (discardTargetResult.bool) {
                const discardTarget = discardTargetResult.targets[0];
                target.line(discardTarget, "green");
                await target.discardPlayerCard({ target: discardTarget, position: "he", forced: true });
              }
            }
          }
          await game.delayx();
        }
      }
    },
    subSkill: {
      clear: {
        onremove: true
      },
      effect0: { charlotte: true },
      effect1: {
        charlotte: true,
        trigger: { player: "useCard" },
        usable: 1,
        forced: true,
        popup: false,
        async content(event2, trigger, player2) {
          player2.unmarkSkill("twyujue_effect1");
          const type2 = get.type2(trigger.card, false);
