tw:twjieyu.code:
{
    audio: 2,
    trigger: { player: ["phaseJieshuBegin", "damageEnd"] },
    round: 1,
    filter(event2, player2) {
      if (event2.name !== "phaseJieshu") {
        const history = player2.getHistory("damage");
        for (const historyEvent of history) {
          if (historyEvent === event2) {
            break;
          }
          return false;
        }
        const all = player2.actionHistory;
        for (let i = all.length - 2; i >= 0; i--) {
          if (all[i].damage.length) {
            return false;
          }
          if (all[i].isRound) {
            break;
          }
        }
      }
      return player2.countCards("h") > 0 && !player2.hasCard(function(card) {
        return !lib.filter.cardDiscardable(card, player2, "twjieyu");
      }, "h");
    },
    check(event2, player2) {
      const names = [];
      for (const card of ui.discardPile.childNodes) {
        if (get.type(card, null, false) === "basic" && !names.includes(card.name)) {
          names.push(card.name);
        }
      }
      if (!names.includes("shan") || !names.includes("tao")) {
        return false;
      }
      if (player2.countCards("h", "shan") < 2 && player2.countCards("h", "tao") < 1) {
        return true;
      }
      return false;
    },
    async content(event2, trigger, player2) {
      await player2.discard({ cards: player2.getCards("h") });
      const cards2 = [];
      const names = [];
      for (const card of ui.discardPile.childNodes) {
        if (get.type(card, null, false) === "basic" && !names.includes(card.name)) {
          cards2.push(card);
          names.push(card.name);
        }
      }
      if (cards2.length) {
        await player2.gain({ cards: cards2, animate: "gain2" });
      }
    }
  }

