tw:twyuanhu.code:
{
    audio: "yuanhu",
    enable: "phaseUse",
    usable: 1,
    filter(event2, player2) {
      return player2.hasCard({ type: "equip" }, "eh");
    },
    filterCard: { type: "equip" },
    filterTarget(card, player2, target) {
      var card = ui.selected.cards[0];
      return target.canEquip(card);
    },
    discard: false,
    lose: false,
    prepare: "give",
    position: "he",
    check(card) {
      if (get.position(card) == "h") {
        return 9 - get.value(card);
      }
      return 7 - get.value(card);
    },
    logAudio(event2, player2) {
      const num = Math.min(get.equipNum(event2.cards[0]), 3);
      return "yuanhu" + num + ".mp3";
    },
    async content(event2, trigger, player2) {
      const {
        target,
        cards: [card]
      } = event2;
      await target.equip(card);
      switch (get.subtype(card)) {
        case "equip1":
          if (game.hasPlayer(function(current) {
            return current != target && get.distance(target, current) == 1 && current.countCards("hej") > 0;
          })) {
            const result = await player2.chooseTarget(true, "弃置一名距离" + get.translation(target) + "为1的角色区域内的一张牌", function(card2, player3, target2) {
              var current = _status.event.current;
              return current != target2 && get.distance(current, target2) == 1 && current.countCards("hej") > 0;
            }).set("current", target).set("ai", function(target2) {
              var player3 = _status.event.player;
              return get.effect(target2, { name: "guohe_copy" }, player3, player3);
            }).forResult();
            if (result?.bool) {
              const targetx = result.targets[0];
              player2.line(targetx);
              await player2.discardPlayerCard(targetx, true, "hej");
            }
          }
          break;
        case "equip2":
          await target.draw();
          break;
        case "equip3":
        case "equip4":
        case "equip5":
        case "equip6":
          await target.recover();
          break;
      }
      if (target.hp <= player2.hp || target.countCards("h") <= player2.countCards("h")) {
        await player2.draw();
        player2.addTempSkill("twyuanhu_end");
      }
    },
    ai: {
      order: 10,
      result: {
        player(player2, target) {
          if (get.attitude(player2, target) == 0) {
            return 0;
          }
          if (!ui.selected.cards.length) {
            return;
          }
          var eff = get.effect(target, ui.selected.cards[0], player2, player2), sub = get.subtype(ui.selected.cards[0], false);
          if (target == player2) {
            eff += 4;
          } else {
            var hp = player2.hp, hs = player2.countCards("h", (card) => card != ui.selected.cards[0]);
            var tp = target.hp, ts = target.countCards("h");
            if (sub == "equip2") {
              ts++;
            }
            if (tp < target.maxHp && (sub == "equip3" || sub == "equip4" || sub == "equip5" || sub == "equip6")) {
              tp++;
            }
            if (tp <= hp || ts <= hs) {
              eff += 2;
            }
          }
          if (sub == "equip1") {
            var list = game.filterPlayer(function(current) {
              return current != target && get.distance(target, current) == 1 && current.countCards("hej") < 0;
            }).map(function(i) {
              return get.effect(i, { name: "guohe_copy" }, player2, player2);
            }).sort((a, b) => b - a);
            if (list.length) {
              eff += list[0];
            }
          }
          return eff;
        },
        target(player2, target) {
          if (!ui.selected.cards.length) {
