          respondShan: true,
          skillTagFilter(player2, tag) {
            if (!player2.hasMark("fanghun")) {
              return false;
            }
            return get.info("ollongdan").ai.skillTagFilter(player2, tag);
          },
          order(item, player2) {
            if (!player2 || !player2.storage) {
              player2 = _status.event.player;
              if (!player2 || !player2.storage) {
                return 0;
              }
              if (Object.keys(player2.storage).some((i2) => {
                return typeof i2 == "string" && i2.indexOf("fuhan") != -1;
              })) {
                return 4;
              }
              return 1;
            }
            const awakened = Object.keys(player2.storage).some((i2) => typeof i2 == "string" && i2.indexOf("fuhan") != -1);
            if (!awakened || !player2.awakenedSkills.some((i2) => i2.indexOf("fuhan"))) {
              if (player2.countMark("fanghun") < 2 && player2.getHp() > 1) {
                return 0;
              }
            }
            if (_status.event.type == "phase") {
              var max = 0;
              var list = ["sha", "tao", "jiu"];
              var map = { sha: "shan", tao: "jiu", jiu: "tao" };
              for (var i = 0; i < list.length; i++) {
                var name = list[i];
                if (player2.countCards("hs", map[name]) > (name == "jiu" ? 1 : 0) && player2.getUseValue({ name }) > 0) {
                  var temp = get.order({ name });
                  if (temp > max) {
                    max = temp;
                  }
                }
              }
              if (max > 0) {
                max += awakened ? 0.3 : -0.3;
              }
              return max;
            }
            return awakened ? 4 : 1;
          }
        }
      }
    }
  }

