tw:twfuhan.code:
{
    audio: "fuhan",
    trigger: { player: "phaseZhunbeiBegin" },
    limited: true,
    skillAnimation: true,
    animationColor: "orange",
    filter(event2, player2) {
      return player2.countMark("fanghun") > 0;
    },
    prompt(event2, player2) {
      var num = Math.max(2, player2.storage.fanghun);
      num = Math.min(num, 8);
      return get.prompt("twfuhan") + "（体力上限：" + num + "）";
    },
    check(event2, player2) {
      if (player2.storage.fanghun >= Math.min(4, player2.maxHp)) {
        return true;
      }
      if (player2.hp <= 2 && player2.storage.fanghun >= 3) {
        return true;
      }
      return false;
    },
    async content(event2, trigger, player2) {
      let num = Math.max(2, player2.storage.fanghun);
      num = Math.min(num, 8);
      player2.removeMark("fanghun", player2.storage.fanghun);
      player2.awakenSkill(event2.name);
      let list = [];
      if (_status.characterlist) {
        for (let i2 = 0; i2 < _status.characterlist.length; i2++) {
          var name = _status.characterlist[i2];
          if (lib.character[name][1] == "shu") {
            list.push(name);
          }
        }
      } else if (_status.connectMode) {
        list = get.charactersOL(function(i2) {
          return lib.character[i2][1] != "shu";
        });
      } else {
        list = get.gainableCharacters(function(info) {
          return info[1] == "shu";
        });
      }
      var players = game.players.concat(game.dead);
      for (var i = 0; i < players.length; i++) {
        list.remove(players[i].name);
        list.remove(players[i].name1);
        list.remove(players[i].name2);
      }
      list.remove("zhaoxiang");
      const result = await player2.chooseButton(["扶汉：选择获得一张武将牌上的所有技能", [list.randomGets(5), "character"]], true).forResult();
      if (result?.links) {
        var name = result.links[0];
        player2.flashAvatar("twhuashen", name);
        game.log(player2, "获得了", "#y" + get.translation(name), "的所有技能");
        await player2.addSkills(lib.character[name][3]);
      }
      num = num - player2.maxHp;
      if (num > 0) {
        await player2.gainMaxHp(num);
      } else {
        await player2.loseMaxHp(-num);
      }
      await player2.recover();
      var card = get.cardPile("meiyingqiang", "field");
      if (card) {
        await player2.gain(card, "gain2", "log");
      }
    },
    ai: { combo: "refanghun" }
  }

