tw:cuijin.code:
{
    audio: 2,
    trigger: { global: "useCard" },
    filter(event2, player2) {
      return event2.card.name === "sha" && (event2.player === player2 || player2.inRange(event2.player)) && player2.hasCards("he");
    },
    checkx(event2, player2) {
      const nature = get.nature(event2.card);
      get.damageEffect(event2.player, player2, player2);
      let damageBonus = 0, mayDamage = 0, odds = -1;
      for (let tar of event2.targets) {
        if (event2.player.hasSkillTag("jueqing", false, tar) || tar.hasSkillTag("filterDamage", null, {
          player: event2.player,
          card: event2.card
        })) {
          continue;
        }
        const hitOdds = 1 - tar.mayHaveShan(player2, "use", true, "odds");
        if (hitOdds >= 1 || event2.player.hasSkillTag(
          "directHit_ai",
          true,
          {
            target: tar,
            card: event2.card
          },
          true
        )) {
          damageBonus += get.damageEffect(tar, event2.player, player2, nature);
        } else {
          odds = Math.max(odds, hitOdds);
          mayDamage += hitOdds * get.damageEffect(tar, event2.player, player2, nature);
        }
      }
      if (damageBonus) {
        return damageBonus;
      }
      if (!mayDamage || odds < 0) {
        return get.damageEffect(event2.player, player2, player2);
      }
      return mayDamage + (1 - odds) * get.damageEffect(event2.player, player2, player2);
    },
    async cost(event2, trigger, player2) {
      event2.result = await player2.chooseToDiscard("chooseonly", "he", get.prompt(event2.skill, trigger.player), `弃置一张牌并令${get.translation(trigger.player)}使用的${get.translation(trigger.card)}伤害+1，但若其未造成伤害，则你对其造成1点伤害。`).set("ai", function(card) {
        const goon = get.event().goon;
        if (goon) {
          return goon - get.value(card);
        }
        return 0;
      }).set(
        "goon",
        (() => {
          const num = lib.skill.cuijin.checkx(trigger, player2) * player2.countCards("he") / 10;
          return num;
        })()
      ).forResult();
    },
    logTarget: "player",
    async content(event2, trigger, player2) {
      await player2.discard(event2.cards);
      if (typeof trigger.baseDamage !== "number") {
        trigger.baseDamage = 1;
      }
      trigger.baseDamage++;
      player2.addTempSkill("cuijin_damage");
      player2.markAuto("cuijin_damage", [trigger.card]);
    },
    subSkill: {
      damage: {
        trigger: { global: "useCardAfter" },
        forced: true,
        popup: false,
        charlotte: true,
        onremove: true,
        filter(event2, player2) {
          return player2.getStorage("cuijin_damage").includes(event2.card);
        },
        async content(event2, trigger, player2) {
          player2.unmarkAuto(event2.name, [trigger.card]);
          if (!player2.getStorage(event2.name).length) {
            player2.removeSkill(event2.name);
          }
          if (trigger.player.isIn() && !game.hasPlayer2(function(current) {
            return current.hasHistory("damage", function(evt) {
              return evt.card === trigger.card;
            });
          })) {
            player2.line(trigger.player, "green");
            await player2.draw();
            await trigger.player.damage();
          }
        }
      }
    }
  }

