{
    audio: 2,
    enable: "phaseUse",
    usable: 1,
    filterTarget(card, player2, target) {
      return target.hp >= player2.hp;
    },
    async content(event2, trigger, player2) {
      const target = event2.targets[0];
      const str = get.translation(target);
      const { index } = await player2.chooseControl({
        choiceList: [`摸两张牌，然后令${str}视为对自己使用【杀】`, `令${str}摸两张牌，然后视为对其使用【杀】`],
        ai: () => {
          const evt = _status.event.getParent();
          const player3 = evt.player;
          const target2 = evt.target;
          const card = { name: "sha", isCard: true };
          const att = get.attitude(player3, target2) > 0;
          if (!target2.canUse(card, player3, false) || get.effect(player3, card, target2, player3) >= 0) {
            return 0;
          }
          if (att && (!player3.canUse(card, target2, false) || get.effect(target2, card, player3, player3) >= 0)) {
            return 1;
          }
          if (target2.hasSkill("nogain") && player3.canUse(card, target2, false) && get.effect(target2, card, player3, player3) > 0) {
            return 1;
          }
          if (player3.hasShan()) {
            return 0;
          }
          if (att && target2.hasShan()) {
            return 1;
          }
          return 0;
        }
      }).forResult();
      const list = [player2, target];
      if (index === 1) {
        list.reverse();
      }
      await list[0].draw(2);
      if (!list[1].isIn() || !list[0].isIn() || !list[1].canUse("sha", list[0], false)) {
        return;
      }
      await list[1].useCard({
        card: { name: "sha", isCard: true },
        targets: [list[0]],
        addCount: false,
        noai: true
      });
    },
    ai: {
      order: 5,
      expose: 0,
      result: {
        player(player2, target) {
          const card = { name: "sha", isCard: true };
          const att = get.attitude(player2, target) > 0;
          if (!target.canUse(card, player2, false) || get.effect(player2, card, target, player2) >= 0) {
            return 2;
          }
          if (att && (!player2.canUse(card, target, false) || get.effect(target, card, player2, player2) >= 0)) {
            return 2;
          }
          if (target.hasSkill("nogain") && player2.canUse(card, target, false)) {
            return get.effect(target, card, player2, player2);
          }
          if (player2.hasShan()) {
            return 1;
          }
          if (att && target.hasShan()) {
            return 1;
          }
          return 0;
        }
      }
    }
  }

