      if (!player2.countCards("h", (card) => {
        if (_status.connectMode) {
          return true;
        }
        return lib.filter.cardDiscardable(card, player2);
      })) {
        return false;
      }
      let bool = false;
      const history = player2.getHistory("useCard"), map = {};
      for (const evt of history) {
        if (get.type2(evt.card) == "trick") {
          if (!map[evt.card.name]) {
            map[evt.card.name] = true;
          } else {
            bool = true;
            break;
          }
        }
      }
      return bool;
    },
    async cost(event2, trigger, player2) {
      event2.result = await player2.chooseCardTarget({
        prompt: get.prompt(event2.skill),
        prompt2: "弃置一张手牌并令一名角色进行一个额外回合",
        filterCard: lib.filter.cardDiscardable,
        filterTarget: true,
        ai1(card) {
          if (card.name == "dz_mantianguohai") return 0.1;
          return 10 - get.value(card);
        },
        ai2(target) {
          if (target.hasJudge("lebu")) {
            return -1;
          }
          const player3 = get.player();
          if (get.attitude(player3, target) > 4) {
            return get.threaten(target) / Math.sqrt(target.hp + 1) / Math.sqrt(target.countCards("h") + 1);
          }
          return -1;
        }
      }).forResult();
    },
    async content(event2, trigger, player2) {
      const {
        targets: [target],
        cards: cards2
      } = event2;
      await player2.discard({ cards: cards2 });
      target.insertPhase();
    },
    ai: {
      effect: {
        player(card, player2, target) {
          let bool = false;
          const history = player2.getHistory("useCard"), map = {};
          if (history.length) {
            for (const evt of history) {
              if (get.type2(evt.card) == "trick") {
                if (!map[evt.card.name]) {
                  map[evt.card.name] = true;
                } else {
                  bool = true;
                  break;
                }
              }
            }
            if (bool && get.type(card) == "trick" && player2 == _status.currentPhase) {
              if (!player2.needsToDiscard() || card.name == "dz_mantianguohai") {
                return "zeroplayertarget";
              }
            }
          }
        }
      }
    },
    subSkill: {
      mark: {
        charlotte: true,
        init(player2, skill) {
          const history = player2.getHistory("useCard"), map = {};
          if (!history.length) {
            return;
          }
          let num = 0;
          for (const i of history) {
            if (get.type2(i.card) == "trick") {
              if (!map[i.card.name]) {
                if (num == 0) {
                  num = 1;
                }
                map[i.card.name] = true;
              } else {
                num = 2;
              }
            }
          }
          if (num > 0) {
            player2.addTip(skill, `${get.translation(skill)} ${num}`, "phaseAfter");
          }
        },
        onremove(player2, skill) {
          player2.removeTip(skill);
        },
        silent: true,
        popup: false,
        firstDo: true,
        trigger: { player: "useCard" },
        filter(event2, player2) {
          return get.type2(event2.card) == "trick";
        },
        async content(event2, trigger, player2) {
          const history = player2.getHistory("useCard"), map = {};
          let num = 0;
          for (const i of history) {
            if (get.type2(i.card) == "trick") {
              if (!map[i.card.name]) {
                map[i.card.name] = true;
                if (num == 0) {
                  num = 1;
                }
              } else {
                num = 2;
              }
            }
          }
          player2.addTip(event2.name, `${get.translation(event2.name)} ${num}`, "phaseAfter");
        }
      }
    }
  }

