tw:twlingbao.code:
{
    audio: 2,
    enable: "phaseUse",
    filter(event2, player2) {
      return player2.getExpansions("twdanfa").map((card) => get.suit(card)).unique().length > 1;
    },
    chooseButton: {
      dialog(event2, player2) {
        return ui.create.dialog("灵宝", player2.getExpansions("twdanfa"));
      },
      filter(button) {
        const buttons = ui.selected.buttons;
        if (!buttons.length) {
          return true;
        }
        return get.suit(buttons[0].link) != get.suit(button.link);
      },
      complexSelect: true,
      check(button) {
        const card = button.link;
        const suits = get.player().getHistory("lose", (evt) => {
          return evt.getParent().name == "discard" && evt.getParent(2).skill == "twlingbao_backup";
        }).map((evt) => evt.cards.map((card2) => get.suit(card2))).flat();
        if (!suits.includes(get.suit(card))) {
          return 2;
        }
        return 1;
      },
      select: 2,
      backup(links, player2) {
        return {
          audio: "twlingbao",
          cards: links,
          filterCard(card) {
            return get.info("twlingbao_backup").cards.includes(card);
          },
          selectCard: -1,
          position: "x",
          async content(event2, trigger, player3) {
            const cards2 = get.info("twlingbao_backup").cards, colors = cards2.map((card) => get.color(card)).unique();
            await player3.draw(2);
            if (colors.length == 1 && colors[0] == "red") {
              const result = await player3.chooseTarget(`灵宝：令一名角色从牌堆中获得两张基本牌`, true).set("ai", (target) => get.effect(target, { name: "wuzhong" }, get.player(), get.player())).forResult();
              if (result?.targets?.length) {
                const target = result.targets[0];
                player3.line(target);
                const gain = [];
                while (gain.length < 2) {
                  const card = get.cardPile((cardx) => get.type(cardx) == "basic" && !gain.includes(cardx));
                  if (card) {
                    gain.push(card);
                  } else {
                    break;
                  }
                }
                if (gain.length) {
                  await target.gain(gain, "gain2");
                }
              }
            }
            if (colors.length == 1 && colors[0] == "black" && game.hasPlayer((target) => target.countDiscardableCards(player3, "hej"))) {
              const result = await player3.chooseTarget(`灵宝：你弃置一名角色至多两个不同区域的共计至多两张牌`, true, (card, player4, target) => {
                return target.countDiscardableCards(player4, "hej");
              }).set("ai", (target) => get.effect(target, { name: "guohe_copy" }, get.player(), get.player())).forResult();
              if (result?.targets?.length) {
                const target = result.targets[0];
                player3.line(target);
                await player3.discardPlayerCard(target, "hej", [1, 2], true);
              }
            }
            if (colors.length > 1) {
              const canDiscard = game.hasPlayer((target) => target.countDiscardableCards(target, "hej"));
              const result = await player3.chooseTarget(`灵宝：你令一名角色摸两张牌` + (canDiscard ? `，另一名角色弃置一张牌` : ``), true, (card, player4, target) => {
                if (!ui.selected.targets.length) {
                  return true;
                }
                return target.countDiscardableCards(target, "hej");
              }).set("selectTarget", canDiscard ? 2 : 1).set("ai", (target) => {
                const player4 = get.player();
                if (!ui.selected.targets.length) {
                  return get.effect(target, { name: "wuzhong" }, player4, player4);
                }
                return get.effect(target, { name: "guohe_copy" }, player4, player4);
              }).set("complexTarget", true).set("complexSelect", true).set("targetprompt", ["摸牌", "弃牌"]).forResult();
              if (result?.targets?.length) {
                const draw = result.targets[0], discard = result.targets[1];
                player3.line(result.targets);
                await draw.draw(2);
                if (discard) {
                  await discard.chooseToDiscard("he", true);
                }
              }
            }
            const suits = player3.getHistory("lose", (evt) => {
              return evt.getParent().name == "discard" && evt.getParent(2).skill == "twlingbao_backup";
            }).map((evt) => evt.cards.map((card) => get.suit(card))).flat();
            if (suits.length != suits.unique().length) {
              player3.tempBanSkill("twlingbao");
            }
          }
        };
      }
    },
    ai: {
      order: 7,
      result: {
        player: 1
      }
    },
    subSkill: {
      backup: {}
    }
  }

