    filter(event2, player2) {
      return game.hasPlayer((current) => current !== player2 && current.countCards("h") > 0);
    },
    check(event2, player2) {
      if (player2.isTurnedOver()) return true;
      if (game.countPlayer((current) => {
        if (current === player2) return 0;
        if (get.attitude(player2, current) > 0) return current.countCards("h") >= 4;
        return current.countCards("h");
      }) < 4 / (1 + player2.getHp()))
        return false;
      return true;
    },
    logTarget(event2, player2) {
      return game.filterPlayer((current) => current !== player2).sortBySeat(_status.currentPhase);
    },
    async content(event2, trigger, player2) {
      const { targets } = event2;
      const list = [];
      for (const target of targets) {
        if (!target.countCards("h")) continue;
        const result2 = await target.chooseCard("枯心：展示任意张手牌", "h", [1, Infinity], true, "allowChooseAll").set("targetx", player2).set("ai", (card) => {
          const { player: player22, targetx } = get.event();
          const att = get.attitude(player22, targetx);
          const val = get.value(card);
          if (get.suit(card, false) === "heart") return att * 10086 - val;
          if (att < 0) return -val;
          if (att > 0) return get.value(card, targetx) - val;
          return val;
        }).forResult();
        if (!result2?.cards?.length) continue;
        list.push([result2.cards, target]);
        await target.showCards(result2.cards);
        await game.delay();
      }
      let result;
      let gains = [];
      if (list.length) {
        result = await player2.chooseButtonTarget({
          createDialog: [
            "枯心：请选择一项执行",
            [
              list.flatMap(([cards2, target]) => cards2.map((card) => [card, target])),
              (item, type, position, noclick, node) => {
                node = ui.create.buttonPresets.card(item[0], type, position, noclick);
                game.createButtonCardsetion(item[1].getName(true), node);
                return node;
              }
            ],
            [["获得所有角色的展示牌", "获得一名角色的未展示牌"].map((item, i) => [i, item]), "tdnodes"],
            [
              (dialog) => {
                dialog.css({ top: get.is.phoneLayout() ? "20%" : "40%" });
                dialog.buttons.forEach((button) => {
                  if (typeof button.link === "number") {
                    button.style.setProperty("width", "200px", "important");
                    button.style.setProperty("text-align", "left", "important");
                  } else {
                    button.style.setProperty("opacity", "1", "important");
                  }
                });
                dialog.buttons = dialog.buttons.filter((button) => typeof button.link === "number");
              },
              "handle"
            ]
          ],
          forced: true,
          filterTarget: lib.filter.notMe,
          selectTarget() {
            if (ui.selected.buttons.length) {
              const { link: link2 } = ui.selected.buttons[0];
              if (link2 === 1) return 1;
              return 0;
            }
            return 0;
          },
          filterOk() {
            if (ui.selected.buttons.length) {
              const { link: link2 } = ui.selected.buttons[0];
              if (link2 === 1) return ui.selected.targets.length === 1;
              return link2 === 0;
            }
            return false;
          },
          list,
          ai1(button) {
            const player22 = get.player();
            const cards2 = get.event().list?.map((i) => i[0]).flat() || [];
            const { num } = get.event().getTrigger();
            const { link: link2 } = button;
            if (typeof link2 !== "number") return 0;
            if (link2 === 1) {
              if (player22.isTurnedOver() && cards2.some((card) => get.suit(card, false) === "heart")) return 2;
              if (cards2.length <= num * 2 && game.hasPlayer((current) => current !== player22 && current.countCards("h", (cardx) => !cards2?.includes(cardx)) > cards2.length && get.attitude(player22, current) < 0)) return 2;
            }
            if (link2 === 0 && cards2.some((card) => get.suit(card, false) === "heart")) return 1;
            return 1;
          },
          ai2(target) {
            if (ui.selected.buttons[0].link === 0) return 1;
            const player22 = get.player();
            const cards2 = get.event().list?.map((i) => i[0]).flat() || [];
            return -get.attitude(player22, target) * target.countCards("h", (cardx) => !cards2?.includes(cardx));
          }
        }).forResult();
        if (!result?.links?.length) return;
        const [link] = result.links;
        if (link === 0) {
          game.log(player2, "选择了", "#g【枯心】", "的", "#y选项一");
          gains = list.flatMap(([cards2, target]) => cards2.filter((card) => lib.filter.canBeGained(card, target, player2)));
        } else if (link === 1 && result?.targets?.length) {
          game.log(player2, "选择了", "#g【枯心】", "的", "#y选项二");
          const [target] = result.targets;
          player2.line(target);
          gains = target.getCards("h", (card) => !list.flatMap((i) => i[0]).includes(card) && lib.filter.canBeGained(card, target, player2));
        }
      } else if (game.hasPlayer((target) => target !== player2)) {
        const targets2 = game.filterPlayer((target) => target !== player2);
        result = targets2.length === 1 ? { bool: true, targets: targets2 } : await player2.chooseTarget("枯心：选择一名其他角色获得其未展示的手牌", true, lib.filter.notMe).set("ai", (target) => {
          const player22 = get.player();
          return -get.attitude(player22, target) * target.countCards("h");
        }).forResult();
        if (result?.targets?.length) {
          game.log(player2, "选择了", "#g【枯心】", "的", "#y选项二");
          const [target] = result.targets;
          player2.line(target);
          gains = target.getCards("h", (card) => lib.filter.canBeGained(card, target, player2));
        }
      }
      if (gains.length) {
        await player2.gain(gains, "gain2");
        await player2.showCards(gains);
      }
      if (!gains.some((card) => get.suit(card, false) === "heart")) {
        if (gains.length) await player2.discard(gains);
      }
    },
    ai: {
      maixie: true,
      maixie_hp: true,
      threaten(player2, target) {
        if (target.getHp() === 1) return 2.5;
        return 0.5;
      },
      effect: {
        target(card, player2, target) {
          if (!target._dekuxin_eff && get.tag(card, "damage") && target.getHp() > (player2.hasSkillTag("damageBonus", true, { card, target }) ? 2 : 1)) {
            if (player2.hasSkillTag("jueqing", false, target)) return [1, -2];
            target._dekuxin_eff = true;
            let gain = game.countPlayer((current) => {
              if (target === current) return 0;
              if (get.attitude(target, current) > 0) return 0;
              if (current.hasCard((cardx) => lib.filter.canBeGained(cardx, target, current, "twkuxin"), "h")) return 0.9;
              return 0;
            });
            delete target._dekuxin_eff;
            return [1, Math.max(0, gain)];
          }
        }
      }
    }
  }

tw:twsigu.code:
{
    audio: "sxrmsigu",
    enable: "phaseUse",
    filter(event2, player2) {
      return game.hasPlayer((current) => player2 !== current);
    },
    usable: 1,
    filterTarget: lib.filter.notMe,
    async content(event2, trigger, player2) {
      const target = event2.targets[0];
