sp:benyu.code:
{
    audio: 2,
    audioname2: { sxrm_caocao: "benyu_sxrm_caocao", tw_sxrm_caocao: "benyu_sxrm_caocao" },
    trigger: { player: "damageEnd" },
    filter(event2, player2) {
      if (!event2.source) {
        return false;
      }
      var nh1 = player2.countCards("h");
      var nh2 = event2.source.countCards("h");
      var eh = player2.countCards("e");
      if (nh1 + eh > nh2 && event2.source.isIn()) {
        return true;
      }
      if (nh1 < Math.min(5, nh2)) {
        return true;
      }
    },
    direct: true,
    async content(event2, trigger2, player2) {
      const num1 = player2.countCards("h");
      const num2 = trigger2.source.countCards("h");
      const eh = player2.countCards("he", function(card2) {
        return lib.filter.cardDiscardable(card2, player2, "benyu");
      });
      let bool1 = false, bool2 = false;
      if (num1 < Math.min(num2, 5)) {
        bool1 = true;
      }
      if (eh > num2 && trigger2.source.isIn()) {
        bool2 = true;
      }
      if (bool1 && bool2) {
        event2.chosen = true;
        const result = await player2.chooseControl("cancel2").set("prompt", get.prompt("benyu", trigger2.source)).set("choiceList", ["将手牌摸至" + get.cnNumber(Math.min(num2, 5)) + "张", "弃置至少" + get.cnNumber(num2 + 1) + "张牌并对其造成1点伤害"]).forResult();
        if (result.control == "cancel2") {
          event2.finish();
          return;
        } else if (result.index != 1) {
          event2._result = { bool: true };
          if (event2._result.bool) {
            player2.logSkill("benyu", trigger2.source);
            player2.drawTo(Math.min(trigger2.source.countCards("h"), 5));
          }
          event2.finish();
          return;
        }
      } else if (!bool2) {
        const result = await player2.chooseBool(get.prompt("benyu", trigger2.source), "将手牌摸至" + get.cnNumber(Math.min(trigger2.source.countCards("h"), 5)) + "张").forResult();
        if (result.bool) {
          player2.logSkill("benyu", trigger2.source);
          player2.drawTo(Math.min(trigger2.source.countCards("h"), 5));
        }
        event2.finish();
        return;
      }
      const num = trigger2.source.countCards("h") + 1;
      const args = [[num, player2.countCards("he")], "he"];
      if (event2.chosen) {
        player2.logSkill("benyu", trigger2.source);
        args.push(true);
      } else {
        args.push(get.prompt("benyu", trigger2.source));
        args.push("弃置" + get.cnNumber(num) + "张牌并对其造成1点伤害");
      }
      const next = player2.chooseToDiscard.apply(player2, args);
      if (!event2.chosen) {
