{
    audio: 2,
    trigger: { global: "judge" },
    filter(event2, player2) {
      return event2.player.hasCards("h");
    },
    round: 1,
    prompt2(event2, player2) {
      return `观看${get.translation(event2.player)}所有手牌并选择一张代替之。若花色不为${get.translation(get.suit(event2.player.judging[0]))}，你受到其造成的1点伤害`;
    },
    check(event2, player2) {
      const target = event2.player;
      const cards2 = event2.player.getCards("h");
      const judging = target.judging[0];
      const attitude = get.attitude(player2, target);
      const better = cards2.some((card) => {
        const diff = event2.judge(card) - event2.judge(judging);
        if (attitude > 0) {
          return diff > 0;
        }
        if (attitude < 0) {
          return diff < 0;
        }
        return false;
      });
      return better;
    },
    async content(event2, trigger, player2) {
      const target = trigger.player;
      const judging = target.judging[0];
      if (!target.hasCards("h")) {
        return;
      }
      const result = await player2.chooseCardButton(target.getCards("h"), 1, `窥目：选择${get.translation(target)}的一张手牌代替判定牌，若花色不为${get.translation(get.suit(judging))}，则你受到其造成的1点伤害`, true).set("forced", true).set("ai", (button) => {
        const card = button.link;
        const trigger2 = get.event().getTrigger();
        const judging2 = trigger2.player.judging[0];
        const result2 = trigger2.judge(card) - trigger2.judge(judging2);
        const attitude = get.attitude(get.player(), trigger2.player);
        const val = get.value(card) / 4;
        if (attitude === 0 || result2 === 0) return 0;
        if (attitude > 0) return result2 - val;
        return -result2 - val;
      }).forResult();
      if (result?.links?.length) {
        game.broadcastAll(
          (card, player3) => {
            const node = player3.$throwordered(card.copy(), true);
            node.classList.add("thrownhighlight");
            ui.arena.classList.add("thrownhighlight");
          },
          result.links[0],
          player2
        );
        if (target.judging[0].clone) {
          target.judging[0].clone.classList.remove("thrownhighlight");
          game.broadcast((card) => {
            if (card.clone) {
              card.clone.classList.remove("thrownhighlight");
            }
          }, target.judging[0]);
          game.addVideo("deletenode", player2, get.cardsInfo([target.judging[0].clone]));
        }
        await game.cardsDiscard(target.judging[0]);
        await target.lose(result.links).set("noOdering", true);
        trigger.player.judging[0] = result.links[0];
        trigger.orderingCards.addArray(result.links);
        game.log(trigger.player, "的判定牌改为", result.links[0]);
        await game.delay(2);
        if (get.suit(result.links[0]) != get.suit(judging)) {
          await player2.damage(target);
        }
      }
    },
    ai: {
      rejudge: true,
      threaten: 1.5,
      tag: { rejudge: 1 }
    }
  }

