tw:twqianliu.code:
{
    audio: "sxrmqianliu",
    trigger: {
      global: "useCardToTargeted"
    },
    filter(event2, player2) {
      return get.distance(player2, event2.target) <= 1 && event2.card?.name == "sha";
    },
    frequent: true,
    logTarget: "target",
    async content(event2, trigger, player2) {
      const cards2 = get.bottomCards(3);
      await game.cardsGotoOrdering(cards2);
      const suits = cards2.map((i) => get.suit(i)).toUniqued();
      if (suits.length === 1 || suits.length === cards2.length) {
        const result2 = await player2.chooseBool(`是否展示并获得${get.translation(cards2)}？`).set("frequentSkill", event2.name).forResult();
        if (result2.bool) {
          await player2.showCards(cards2);
          await player2.gain(cards2, "gain2");
          return;
        }
      }
      const result = await player2.chooseToMove().set("list", [["牌堆顶"], ["牌堆底", cards2]]).set("prompt", "点击或拖动将牌移动到牌堆顶或牌堆底").set("processAI", (list) => {
        let cards3 = list[1][1], player3 = _status.event.player, target = _status.currentPhase || player3, name = _status.event.getTrigger()?.name, countWuxie = (current) => {
          let num = current.getKnownCards(player3, (card) => {
            return get.name(card, current) === "wuxie";
          });
          if (num && current !== player3) {
            return num;
          }
          let skills2 = current.getSkills("invisible").concat(lib.skill.global);
          game.expandSkills(skills2);
          for (let i = 0; i < skills2.length; i++) {
            let ifo = get.info(skills2[i]);
            if (!ifo) {
              continue;
            }
            if (ifo.viewAs && typeof ifo.viewAs != "function" && ifo.viewAs.name == "wuxie") {
              if (!ifo.viewAsFilter || ifo.viewAsFilter(current)) {
                num++;
                break;
              }
            } else {
              let hiddenCard = ifo.hiddenCard;
              if (typeof hiddenCard == "function" && hiddenCard(current, "wuxie")) {
                num++;
                break;
              }
            }
          }
          return num;
        }, top2 = [];
        switch (name) {
          case "phaseJieshu": {
            target = target.next;
            cards3.sort((a, b) => {
              return get.value(b, target) - get.value(a, target);
            });
            while (cards3.length) {
              if (get.value(cards3[0], target) > 6) {
                top2.push(cards3.shift());
              } else {
                break;
              }
            }
            return [top2, cards3];
          }
          case "phaseZhunbei": {
            let att = get.sgn(get.attitude(player3, target)), judges = target.getCards("j"), needs = 0, wuxie = countWuxie(target);
            for (let i = Math.min(cards3.length, judges.length) - 1; i >= 0; i--) {
              let j = judges[i];
              j.viewAs ? { name: j.viewAs, cards: j.cards || [j] } : j;
              if (wuxie > 0 && get.effect(target, j, target, target) < 0) {
                wuxie--;
                continue;
              }
              let judge = get.judge(j);
              cards3.sort((a, b) => {
                return (judge(b) - judge(a)) * att;
              });
              if (judge(cards3[0]) * att < 0) {
                needs++;
                continue;
              } else {
                top2.unshift(cards3.shift());
              }
            }
            if (needs > 0 && needs >= judges.length) {
              return [top2, cards3];
            }
            cards3.sort((a, b) => {
              return (get.value(b, target) - get.value(a, target)) * att;
            });
            while (needs--) {
              top2.unshift(cards3.shift());
            }
            while (cards3.length) {
              if (get.value(cards3[0], target) > 6 == att > 0) {
                top2.push(cards3.shift());
              } else {
                break;
              }
            }
            return [top2, cards3];
          }
          default:
            cards3.sort((a, b) => {
              return get.value(b, target) - get.value(a, target);
            });
            while (cards3.length) {
              if (get.value(cards3[0], target) > 6) {
                top2.push(cards3.shift());
              } else {
                break;
              }
            }
            return [top2, cards3];
        }
      }).forResult();
      let top = result.moved[0], bottom = result.moved[1];
      top.reverse();
      for (let i = 0; i < top.length; i++) {
        ui.cardPile.insertBefore(top[i], ui.cardPile.firstChild);
      }
      for (let i = 0; i < bottom.length; i++) {
        ui.cardPile.appendChild(bottom[i]);
      }
      game.addCardKnower(top, player2);
      game.addCardKnower(bottom, player2);
      player2.popup(get.cnNumber(top.length) + "上" + get.cnNumber(bottom.length) + "下");
      game.log(player2, "将" + get.cnNumber(top.length) + "张牌置于牌堆顶");
      game.updateRoundNumber();
      await game.delayx();
    }
  }
